insert into school_exam_questions (id, worksheet_id, question_no, question_type, category, is_multiple_choice, answer_text, explanation, sub_answer_count) values
('8095efb3-a64e-4cfa-9f7d-c82e5ea1c5ee', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 1, '내용일치', '독해/사실확인', true, '5', '소년은 휴대폰을 단지 게임과 영상 시청만을 위해 사 용하는 것이 아니라, 유용한 정보를 얻고 친구들과 소 통하는 데에도 사용한다고 말하였다. 즉, 게임과 영상 시청은 일부일 뿐이며, 다양한 용도로 사용하고 있다고 밝혔다.', 1),
('4ead9b26-e3c6-49f1-a30d-6fef9bb230e3', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 2, '내용일치', '독해/사실확인', true, '3', '담화문에서 언급되지 않은 내용이다. 담화문에서는 디지털 평판이 오프라인 평판만큼 중요하다고 하였지 만, 오프라인 평판보다 더 중요하다고 강조하지는 않았 다.', 1),
('285c233e-d739-4112-93f8-d3b71642bf7e', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 3, '제목요지', '주제파악', true, '2', '담화문에서 소셜 미디어에 퍼지는 잘못된 정보를 예 시로 들며 이를 그대로 믿는 것이 얼마나 위험한지를 강조하고 있다. 조작된 허리케인 경로 사진과 잘못된 조언을 통해, 온라인 정보를 비판적으로 받아들여야 한 다는 주제가 중심이 된다. 따라서 핵심 주제로 가장 적 절한 것은 ''소셜 미디어의 모든 것을 믿는 것의 위 험성''이다. 허리케인에 효과적으로 대비하는 방법 왜 홍수 중에는 식기세척기를 사용하면 안 되는가 날씨 관련 정보를 수정하는 과정 긴급 뉴스를 위해 소셜 미디어를 사용하는 것의 중요성', 1),
('9114d93a-9017-47ce-9fa8-646b48b6c41b', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 4, '제목요지', '주제파악', true, '3', '가짜 뉴스가 빠르게 퍼지는 이유를 설명하기 위해 글이 가짜 뉴스가 실제 뉴스보다 더 빨리 퍼진다는 연 구 결과를 제시하고, 그 이유를 사람들의 자극적인 정 보에 대한 선호와 비판적 사고 부족 같은 심리적 특성 으로 설명하고 있다. 소셜 미디어 사용을 자제시키 기 위해 가짜 뉴스의 사회적 해악을 설명하기 위해 가짜 뉴스와 전통 뉴스를 비교하기 위해 가짜 뉴스 확산을 막는 방법을 제안하기 위해', 1),
('86e74c40-87a8-456c-a3b2-9479daa2fae6', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 5, '내용일치', '독해/사실확인', true, '1', '지나가 당황한 이유는 자신이 공유한 흔들바위 관 련 뉴스가 TV를 통해 가짜 뉴스임이 밝혀졌기 때문이 라고 본문에 명시되어 답할 수 있다. 흔들바위는 손 상되지 않았다고 언급되므로 실제 손상 정도는 알 수 없다. 누가 처음 뉴스를 보도했는지에 대한 정보는 없다. , 지나가 설악산을 방문했는지, 친구들과 무엇을 했는지에 대한 내용은 글에 언급되지 않는다.', 1),
('382d82f7-8d53-4826-835f-dfe55e114b9b', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 6, '내용일치', '독해/사실확인', true, '5', '지문에서는 주민들이 가짜 뉴스 때문에 2주 동안 대 피소에 머물렀으며, 정부가 해당 정보가 거짓임을 발표 했다고만 나와 있다. 그러나 발표 이후에도 계속 대피 소에 머물렀는지 여부는 언급되지 않았다.', 1),
('e21a560d-f5f7-41cc-9870-28133175a7f1', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 7, '제목요지', '주제파악', true, '1', '본문은 가짜 뉴스가 사람들의 관심을 끌거나 특정 이 익을 얻기 위해 의도적으로 만들어지며, 사회를 혼란에 빠뜨리고 공공에 심각한 해를 끼칠 수 있다는 점을 인 도네시아 지진 사례를 통해 설명하고 있다. 따라서 글 의 요지로 가장 적절한 것은 ''가짜 뉴스는 공공에 심각한 해를 끼칠 수 있다.''이다.', 1),
('ae14ddaf-f94f-4f8c-8211-7fec7a7c360c', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 8, '내용일치', '독해/사실확인', true, '3', '왜 가짜 뉴스가 진짜 뉴스보다 더 빨리 퍼지는가 글이 가짜 뉴스가 실제 뉴스보다 6배 더 빠르게 퍼진다 는 연구 결과를 바탕으로, 그 이유를 자극적인 정보에 대한 사람들의 반응과 비판적 사고 부족 등 심리적 요 인으로 설명하고 있다. 사람들이 온라인에서 가짜 뉴스를 어떻게 식별할 수 있는가 누가 소셜 미디어 에서 가장 많은 가짜 뉴스를 퍼뜨리는가 가짜 뉴스 가 정신 건강에 미치는 영향은 무엇인가 가짜 뉴스 를 공유했을 때의 법적 결과는 무엇인가', 1),
('71442a6d-a5e3-4a6b-8182-79eb6087fc61', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 9, '제목요지', '주제파악', true, '3', '가짜 뉴스의 빠른 확산에 대한 설명 글의 핵심 내 용이 가짜 뉴스가 진짜 뉴스보다 훨씬 빠르게 퍼지는 현상을 설명하고, 그 이유를 사람들의 심리적 특성과 정보 소비 방식에서 찾고 있다. 바이럴 콘텐츠의 심 리학 우리가 소셜 미디어 거짓말에 속는 이유 진실을 퍼뜨리는 데 있어 기술의 역할 온라인 뉴스 에 대해 비판적으로 생각하는 방법', 1),
('10346294-3640-4637-b4dd-03a65df3357d', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 10, '내용일치', '독해/사실확인', true, '5', '본문은 자극적인 헤드라인 너머를 읽고, 비판적으로 생각하며, 자신의 편견을 점검하고, 출처의 신뢰도를 확인하는 등 가짜 뉴스에 속지 않는 구체적인 방법들을 제시하고 있다. 따라서 답할 수 있는 질문으로 가장 적 절한 것은 ''가짜 뉴스에 속지 않으려면 어떻게 해야 하는가?''이다. 가짜 뉴스의 정치적 영향은 무엇인 가? 가짜 뉴스가 너무 빠르게 퍼지면 어떤 일이 일 어나는가? 왜 사람들은 증거도 없이 가짜 뉴스를 믿는가? 누가 인터넷상의 가짜 뉴스를 규제할 책임 이 있는가?', 1),
('9e2fc9dd-021b-44e8-8446-98e1ea52e3f0', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 11, '빈칸추론', '논리/추론', false, '(1) headline (2) critical thinking (3) biases (4) credible, evidence', '(1) 가짜 뉴스에 속지 않으려면, 자극적인 제목만 읽 지 말고 전체 기사를 주의 깊게 읽어야 한다. 따라서 빈칸에는 headline이 들어간다. (2) 뉴스를 있는 그대 로 받아들이지 말고, 정보를 분석하고 판단하기 위해 비판적 사고를 적용해야 한다. 따라서 빈칸에는 critical thinking이 들어간다. (3) 뉴스를 해석하는 데 영향을 줄 수 있으므로, 자신의 편향을 점검하는 것이 중요하다. 따라서 빈칸에는 biases가 들어간다. (4) 뉴 스가 신뢰할 수 있는 출처에서 나온 것인지, 그리고 타 당한 근거가 포함되어 있는지를 확인해야 한다. 따라서 빈칸에는 credible과 evidence가 들어간다.', 4),
('2e0f7fa3-e53d-4f0c-8310-b3e5829a5684', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 12, '제목요지', '주제파악', true, '5', '글의 중심 내용이 가짜 뉴스가 자극적이고 놀라울 수록 더 많은 사람들에게 퍼지기 쉽다는 점을 설명하는 데 있다. 사람들은 새롭고 충격적인 정보를 보면 흥미 를 느끼고, 그 정보를 다른 사람들과 공유함으로써 주 목을 받고자 하며, 그 과정에서 가짜 뉴스가 빠르게 확 산된다고 글에서 밝히고 있다. 글에서는 가짜 뉴스 가 진짜 뉴스보다 6배 더 빠르게 퍼진다고 하며, 진짜 뉴스가 더 주목받는다는 내용은 없다. 소셜 미디어 는 가짜 뉴스가 퍼지는 통로로 등장하며, 항상 신뢰할 수 있는 정보를 전달한다고 하지 않는다. 오히려 가 짜 뉴스는 더 많은 관심을 끌기 위해 만들어진다고 서 술되므로 반대 내용이다. 글에서는 사람들이 비판적 사고 없이 정보를 수용하기 쉽다고 하며, 비판적 사고 부족이 문제라고 말한다.', 1),
('8b473d5c-c436-4eaa-9674-3e51e9d7497d', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 13, '빈칸추론', '논리/추론', true, '1', '지나는 누구나 진실을 확인하지 않고 충격적인 제목 을 공유함으로써 가짜 뉴스의 확산에 책임이 있을 수 있다는 것을 깨달았다. 글에서는 지나가 처음에는 가짜 뉴스 유포자를 비판했지만, 나중에는 자신도 무심코 가 짜 뉴스를 퍼뜨린 사람 중 하나가 되었다는 점에서 부 끄러움을 느꼈다고 서술한다. 이 경험을 통해 누구든 가짜 뉴스 확산에 책임질 수 있다는 교훈을 얻었으며, 그 계기가 된 것이 자극적인 제목을 사실 확인 없이 공 유한 행동이었다. 감정적인 지루한 도움이 되는 상세한 조심스러운 공식적인 혼란스러운 반복된', 1),
('90d36954-5d28-437f-a9ed-f37a6ef08c83', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 14, '내용일치', '독해/사실확인', true, '4', '대부분의 가짜 뉴스는 검증되고 신뢰할 수 있는 정보를 포함하고 있다. 지문에서는 가짜 뉴스가 이전에 알려지지 않았지만 거짓일 수 있는 정보를 담고 있으 며, 사람들은 이를 증거 없이 믿는 경향이 있다고 설명 하고 있다. 가짜 뉴스는 온라인에서 진짜 뉴스보다 더 빨리 퍼진다. 자극적인 제목은 사람들이 뉴스를 공유하고 싶게 만든다. 사람들은 주목을 받기 위해 놀라운 뉴스를 자주 공유한다. 사람들은 증거 없이 새로운 정보를 더 쉽게 믿는 경향이 있다.', 1),
('80931b5f-cb43-45f0-ae81-538007753e82', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 15, '빈칸추론', '논리/추론', false, '(1) avoid (2) fooled', '가짜 뉴스를 피하고(avoid) 그로 인한 피해를 줄이는 방법을 암시한다. ⓐ 본문 첫 문장에 나온 ''avoid''를 사용하여 ''가짜 뉴스에 속는 것을 피하는 방법''이라는 제목을 만들 수 있다. ⓑ 가짜 뉴스로부터 피해를 줄인 다는 것은 결국 ''속지(fooled) 않는 것''을 의미하므로, 제목을 완성하기에 가장 적절한 단어는 ''fooled''이다.', 2),
('f1e6024a-5d1b-4aac-b91d-1b0c4f77f818', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 16, '빈칸추론', '논리/추론', false, '(1) attention (2) beliefs (3) confirmation bias (4) opponents', '(1) 사람들은 소셜 미디어에서 더 많은 주목을 받기 위해 놀라운 뉴스를 공유한다. 글에서는 사람들이 놀라 운 정보를 공유함으로써 다른 사람의 관심을 끌고자 한 다고 설명하고 있으므로 attention(주목)이 가장 적절하 다. (2) 사람들은 자신의 신념이나 과거 경험에 맞는 뉴 스를 믿는다. 글에 따르면 사람들은 사실 여부보다 자 신의 기존 신념과 일치하는 정보를 더 쉽게 받아들이기 때문에 beliefs(신념)가 들어간다. (3) 많은 사람들은 자 신의 관점을 지지하는 것만 받아들임으로써 확증 편향 에 빠진다. 자신의 신념을 강화하는 정보만 선택적으로 수용하는 현상을 설명하기에 confirmation bias(확증 편향)가 들어간다. (4) 선거 기간 동안 사람들은 자신들 의 반대편 후보에 대한 부정적인 뉴스를 믿는다. 글에 서는 사람들이 자신이 지지하지 않는 후보에 대한 부정 적 정보에 무비판적으로 반응한다고 했으므로 opponents(상대편)가 알맞다.', 4),
('906b32f6-d8d0-4faf-a5d2-9ef25fa4f112', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 17, '내용일치', '독해/사실확인', true, '5', '글에서는 사람들이 놀랍고 자극적인 정보를 공유 하는 이유 중 하나로 다른 사람들의 주목을 받고 싶어 하기 때문이라고 명확히 설명하고 있다. 글에서는 오히려 사람들이 사실 여부를 확인하지 않고 자극적인 정보만 보고 쉽게 믿고 공유한다고 설명한다. 사람 들은 자신의 편견이나 경험에 부합하는 정보를 더 쉽게 믿는다고 하며, 경험과 무관한 정보는 잘 수용하지 않 는 경향이 있다. 관심이 줄어든다는 언급은 없으며, 오히려 선거철에는 지지하는 후보에 대한 긍정적 뉴스 나 반대 후보의 부정적 뉴스에 쉽게 현혹되는 경향이 있다고 나온다. 글에서는 사람들이 자신의 신념과 일치하는 뉴스만을 선택적으로 수용하는 경향, 즉 확증 편향에 빠지기 쉽다고 설명하고 있다.', 1),
('cd4aa36b-2814-44b2-91f7-00b69fcf860a', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 18, '제목요지', '주제파악', true, '5', '위기 상황에서 가짜 뉴스에 대해 경고하기 위해 글은 인도네시아 암본 지역에서 지진 후 가짜 뉴스가 퍼지며 사람들이 오랫동안 대피소에 머물렀고, 정부가 허위임을 공식 발표해야 했던 상황을 소개하고 있다. 지진을 설명하기 위해 재난 피해를 보도하기 위 해 소셜 미디어 사용을 장려하기 위해 전 세계 의 가짜 뉴스를 비교하기 위해', 1),
('19fff61d-ccb1-4675-a45e-80a33dc10394', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 19, '내용일치', '독해/사실확인', true, '5', '가짜 뉴스 때문에 사람들은 몇 달 동안 집을 떠나 있었다 지문에서는 사람들이 가짜 뉴스로 인해 2주간 대피소에 머물렀다고만 되어 있다. 암본에서의 지진 은 2019년에 발생했다. 한 메시지는 암본이 곧 가 라앉을 것이라고 주장했다. 정부는 나중에 그 뉴스 가 거짓이라고 발표했다. 사람들은 첫 번째 지진 이 후 또 다른 지진을 두려워했다.', 1),
('81696519-4206-4898-b803-aaf41656d275', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 20, '빈칸추론', '논리/추론', false, '(1) provocative (2) proof (3) beliefs (4) opponents', '(1) 사람들이 자극적인 이야기를 좋아하기 때문에 가 짜 뉴스는 빠르게 퍼진다. 글에서는 사람들이 새롭고 자극적인 내용을 선호하고, 그런 내용을 공유하려는 경 향이 있다고 설명한다. provocative(자극적인) (2) 사람 들은 증거 없이 새로운 정보를 믿는다. 글에 따르면 사 람들은 정보를 비판적으로 따지기보다는, 증거 없이 쉽 게 믿는 경향이 있다. proof(증거) (3) 사람들은 자신들 의 신념에 맞는 것만 받아들인다. 글에서는 사람들이 자신의 기존 신념이나 경험에 부합하는 정보만 선택적 으로 수용한다고 설명한다. beliefs(신념) (4) 선거에서 사람들은 자신의 상대편에 대한 나쁜 뉴스를 믿는다. 글에서는 사람들이 선거철에 자신이 지지하지 않는 후 보자에 대한 부정적 정보는 쉽게 믿는다고 설명한다. opponents(상대편)', 4),
('823ed13a-dedf-4b1e-94f1-4804db1e89d4', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 21, '내용일치', '독해/사실확인', true, '1', '정부가 가짜 뉴스의 확산을 어떻게 막을 수 있는 가 지문에서는 정부의 대응 방법이나 정책에 대한 언급 이 전혀 없으며, 오직 사람들의 심리적 경향과 가짜 뉴 스의 확산 이유에 대해서만 설명하고 있다. 왜 가짜 뉴스는 진짜 뉴스보다 더 빨리 퍼지는가 확증 편향 이란 무엇이며 사람들에게 어떤 영향을 미치는가 사 람들이 가짜 뉴스를 믿게 만드는 심리적 요인은 무엇인 가 왜 사람들은 자신의 신념에 맞는 뉴스를 믿으려 하는가', 1),
('f53d226b-1c8b-40c3-a8ed-71bc994920f8', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 22, '내용일치', '독해/사실확인', true, '3', '지나가 공유한 뉴스에 대해 그녀의 친구들이 어떻 게 반응했는가 지문에서는 지나가 친구들에게 가짜 뉴 스를 공유했다는 사실은 나오지만, 그 친구들이 어떻게 반응했는지는 전혀 언급되지 않는다. 왜 어떤 사람 들은 가짜 뉴스를 만드는가 지나가 소셜 미디어에서 본 가짜 뉴스는 무엇이었는가 지나가 가짜 뉴스를 퍼뜨렸다는 사실을 깨달은 후 어떻게 느꼈는가 설악 산의 흔들바위에 무슨 일이 일어났는가', 1),
('39824e39-55fd-40f7-8b27-393dd28f06ec', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 23, '제목요지', '주제파악', true, '3', '글의 중심 내용은 과거에 가짜 뉴스를 비판했던 지나 가, 이번에는 자신이 직접 가짜 뉴스를 퍼뜨렸다는 사 실을 깨닫고 부끄러움을 느끼는 경험에 초점이 맞춰져 있다. 따라서 글의 핵심 주제로 가장 알맞은 것은 '' 지나가 자신도 모르게 가짜 뉴스를 퍼뜨린 뒤 후회한 이야기''이다. 한국에서의 가짜 뉴스의 역사 온라 인에서 뉴스를 공유하기 전에 확인하는 방법 흔들바 위 붕괴에 대해 사람들이 어떻게 반응했는가 신뢰할 수 있는 뉴스를 만드는 콘텐츠 제작자의 역할', 1),
('445cd96c-6b5c-43d1-87a4-502114b830b7', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 24, '제목요지', '주제파악', true, '1', '가짜 뉴스에 속지 않기 위해 제목 너머를 읽고, 비판 적으로 사고하며, 자신의 편견을 점검하고, 출처를 확 인하는 등 개인이 할 수 있는 방법을 제시하고 있다. 따라서 글의 핵심 주제는 ''사람은 속지 않기 위해 비판적으로 사고해야 한다.''이다. 언론은 보다 긍정 적인 뉴스 기사를 더 많이 내보내야 한다. 독자들은 가짜 뉴스가 어떻게 만들어지는지 알아야 한다. 정 부는 소셜 미디어의 가짜 뉴스를 금지해야 한다. 뉴 스 제목은 보통 본문보다 더 신뢰할 수 있다.', 1),
('f36d7164-135d-48d2-9af6-b43e438c59f7', '3a582d53-4da3-45ca-8092-2b4d5e9ee46b', 25, '내용일치', '독해/사실확인', true, '5', '정부가 어떤 종류의 뉴스를 읽으라고 권장하는가 글 전체는 개인이 가짜 뉴스에 속지 않기 위해 해야 할 판단과 행동에 대한 설명에 초점이 있으며, 정부의 권 장 사항이나 뉴스 추천 내용은 전혀 언급되지 않는다. 왜 제목만 넘어서 읽는 것이 중요한가 독자들은 뉴스의 신뢰성을 어떻게 확인할 수 있는가 사람들이 가짜 뉴스에 속지 않기 위해 무엇을 할 수 있는가 확증 편향이란 무엇이며 판단에 어떤 영향을 미치는가', 1),
('90d3ac19-f738-4a5e-92de-02866f2bfab4', 'f608cb4e-5414-408b-ac81-537e9231fd20', 1, '지칭', '논리/추론', true, '5', '밑줄 친 it은 바로 앞 문장에서 언급된 ''A picture on social media that told us that Irma was going to hit Texas''를 가리킨다. 따라서 it이 가리키는 것으 로 가장 알맞은 것은 ''텍사스를 강타할 것이라고 보 여주는 허리케인 어마 관련 사진''이다. 허리케인 어 마 국립기상센터 홍수 피해를 보여주는 영상 식기세척기 관련 SNS 게시물', 1),
('8b67ab51-c0d3-420a-bab1-add48a3c897a', 'f608cb4e-5414-408b-ac81-537e9231fd20', 2, '대화문', '화용/의사소통', true, '2', '아들이 휴대폰 사용 시간을 조절하고 싶다고 도움을 요청했고, 엄마가 그에 대한 해결책을 제안하는 상황이 다. 아들이 제안에 대해 앱을 사용하겠다고 답했으므 로, 빈칸에 들어갈 말로 가장 알맞은 것은 ''너의 화 면 사용 시간을 제한해보는 게 어때?''이다. 새 휴대 폰 사고 싶니? 네 휴대폰 사용하는 법을 나한테 가 르쳐줄래? 요즘 무슨 게임 해? 휴대폰으로 숙제 는 끝냈니?', 1),
('94dfd97c-cff4-4db0-9717-d9f56cee34a3', 'f608cb4e-5414-408b-ac81-537e9231fd20', 3, '무관한문장', '글의흐름', true, '4', '너는 걱정 없이 자유롭게 너의 생각을 공유해야 한다. 지문에서는 온라인 활동이 영구적으로 남고, 사 생활 노출이나 범죄에 악용될 수 있으며, 디지털 평판 에도 영향을 준다고 경고하고 있으므로, 담화의 흐름과 전혀 맞지 않는다. 너의 온라인 존재를 현명하게 통 제해야 한다. 네가 온라인에 남긴 것을 관리해야 한 다. 너의 디지털 흔적에 대해 책임을 져야 한다. 너는 네 디지털 발자국을 신중히 관리해야 한다고 기대 된다.', 1),
('87d6b89c-73ba-4d60-b315-af624c194bbe', 'f608cb4e-5414-408b-ac81-537e9231fd20', 4, '지칭', '논리/추론', true, '4', '지나가 본 흔들바위에 관한 가짜 뉴스 바로 앞에 언급된 흔들바위가 무너졌다는 가짜 뉴스를 가리킨다. 그 뉴스가 과거의 또 다른 가짜 뉴스 사건(유명 운동선 수 사망 관련)을 떠올리게 했기 때문에, 지시어 it이 가 리키는 것은 흔들바위 관련 가짜 뉴스가 맞다. 아침 TV 뉴스 보도 가짜 뉴스를 퍼뜨린 후의 지나의 후 회 유명 운동선수의 죽음에 대한 지나의 기억 흔들바위의 사진', 1),
('d54e7d24-2b8e-4527-b1ad-a1ab78e33884', 'f608cb4e-5414-408b-ac81-537e9231fd20', 5, '내용일치', '독해/사실확인', true, '5', '지문에서는 지나가 처음에는 가짜 뉴스를 퍼뜨리 는 사람들을 비판하던 입장이었지만, 나중에 자신도 무 심코 가짜 뉴스(흔들바위 관련)를 퍼뜨린 사실을 깨닫 고 부끄러워했다고 나온다. 지나가 가짜 뉴스를 옹 호하거나 지지했다는 내용은 전혀 없고, 오히려 비판했 다고 나와 있다. 지나가 직접 제작한 적은 없으며, 비판하거나 퍼뜨린 입장으로만 언급된다. 사실 확인 없이 충격적인 제목만 보고 공유한 것이며, 그로 인해 부끄러움을 느꼈다. 지나가 퍼뜨린 뉴스가 가짜임을 나중에 알았고, 처음에는 진짜라고 믿고 공유했다.', 1),
('c85fa83b-9660-48e5-ba3b-bead130cb10a', 'f608cb4e-5414-408b-ac81-537e9231fd20', 6, '지칭', '논리/추론', true, '5', '밑줄 친 (A)의 This는 바로 앞 문장에서 서술된 ''수 천 명의 주민들이 집으로 돌아가지 못하고 2주 동안 대 피소에 머물렀던'' 상황 전체를 가리킨다. 따라서 (A)가 가리키는 것으로 가장 적절한 것은 ''주민들이 2주 동안 대피소에 머물렀던 사실''이다. 가짜 뉴스가 위 험한 이유 여진에 대한 사람들의 불안 암본을 강타한 지진 정부의 발표', 1),
('869d2a7c-6d2a-4467-baeb-b54f48b4fcf7', 'f608cb4e-5414-408b-ac81-537e9231fd20', 7, '빈칸추론', '논리/추론', true, '2', 'ⓐ 가짜 뉴스는 사람들을 의도적으로 속여 이익을 얻 으려는 시도이므로 ''조종하다(manipulate)''가 적절하다. ⓑ 지진과 같은 상황은 ''비상사태(emergency)''에 해당 한다. ⓒ 정부는 퍼져나간 정보가 사실이 아님을 밝혀 야 하므로 ''가짜의(fake)''라고 발표해야 한다.', 1),
('2f9c1790-964c-42b2-a0b5-b87c9516cafa', 'f608cb4e-5414-408b-ac81-537e9231fd20', 8, '제목요지', '주제파악', true, '5', '글 전체가 가짜 뉴스가 빠르게 확산되는 이유를 설명 하고 있다. 사람들이 자극적인 정보를 좋아하고, 주목 받기 위해 공유하며, 비판적 사고 없이 믿는 경향이 있 기 때문이라고 설명하므로, 이 글이 답하는 질문으로 가장 알맞은 것은 ''사람들이 왜 소셜 미디어에서 가 짜 뉴스를 믿고 퍼뜨리는 경향이 있는가?''이다. 너 무 많은 뉴스를 보는 것의 위험은 무엇인가? 오늘 날 정부는 가짜 뉴스를 어떻게 규제하는가? 온라인 에서 가짜 뉴스가 퍼지는 것을 막는 가장 좋은 방법은 무엇인가? 가짜 뉴스와 진짜 뉴스를 어떻게 구별할 수 있는가?', 1),
('7a8f5370-1abd-4230-9210-70a0df66b4a5', 'f608cb4e-5414-408b-ac81-537e9231fd20', 9, '지칭', '논리/추론', true, '4', '밑줄 친 it은 바로 앞의 ''astonishing information'' 을 가리키며, 이는 문맥상 ''새롭고 자극적인 정보''를 의 미한다. 따라서 it이 가리키는 것으로 가장 알맞은 것은 ''새롭고 자극적인 정보''이다. 소셜 미디어 플랫 폼 사람들의 개인적인 의견 그들이 얻은 관심 정부가 만든 가짜 뉴스', 1),
('56c20f19-f8ce-4232-81e8-218679863276', 'f608cb4e-5414-408b-ac81-537e9231fd20', 10, '빈칸추론', '논리/추론', true, '3', '빈칸 앞뒤 문장은 가짜 뉴스가 퍼지는 이유를 추가로 설명하는 관계이므로, ''게다가'', ''더욱이''라는 의미로 내 용을 덧붙이는 접속사 ''Moreover''가 가장 적절하 다. 그러나 그러므로 그렇지 않으면 한편', 1),
('b5f2b51c-a817-4f5c-a0cf-3db616c33eba', 'f608cb4e-5414-408b-ac81-537e9231fd20', 11, '영작', '쓰기', false, '그들은 자신들의 신념을 확인시켜 주는 방식으로 뉴스를 선택적으로 받아들이고, 그들을 지지하지 않는 뉴스는 무시한다.', 'selectively accept news는 뉴스를 선택적으로 받아 들인다는 뜻이며, in a way that only confirms their beliefs는 자신의 신념을 확인해주는 방식으로라 는 뜻이고, ignore news that doesn''t support them 은 자신을 지지하지 않는 뉴스는 무시한다는 뜻이다.', 1),
('88bb01ae-77bc-4ade-9847-51cb31e7049d', 'f608cb4e-5414-408b-ac81-537e9231fd20', 12, '영작', '쓰기', false, 'They can be so stimulating to get more clicks that you may click on them accidentally.', '이 문장은 so ~ that 구문이 사용된 구조이다. so stimulating은 ''너무 자극적이어서''라는 의미이고, to get more clicks는 ''더 많은 클릭을 얻기 위한 목적''을 나타내는 표현이다. that you may click on them accidentally는 ''그래서 실수로 클릭하게 된다''는 결과 를 나타낸다. 전체적으로 ''너무 자극적이어서 사람들이 무심코 클릭하게 된다''는 원인과 결과 관계를 설명하는 문장 구조이다.', 1),
('2341a7d3-cb28-4973-81d3-3df3d3683c40', 'f608cb4e-5414-408b-ac81-537e9231fd20', 13, '제목요지', '주제파악', true, '5', '가짜 뉴스에 속지 않기 위해 정보를 비판적으로 읽는 방법, 편향을 점검하는 법, 출처의 신뢰성을 확인하는 법 등을 구체적으로 안내하고 있다. 따라서 이 글이 답 하는 질문으로 가장 알맞은 것은 ''우리가 가짜 뉴스 에 속지 않기 위해 어떻게 자신을 보호할 수 있는가?'' 이다. 가짜 뉴스는 정치적 의견에 어떤 영향을 주는 가? 우리는 왜 소셜 미디어에 의견을 공유해야 하 는가? 온라인 뉴스를 빠르게 만드는 방법에는 무엇 이 있는가? 가짜 뉴스 확산을 막을 책임은 누구에 게 있는가?', 1),
('f98ac810-7720-4336-b1af-7bbcbda8a408', 'f608cb4e-5414-408b-ac81-537e9231fd20', 14, '내용일치', '독해/사실확인', true, '5', '지문에 따르면, 가짜 뉴스는 진짜 뉴스보다 평균 6배 더 빠르게 퍼진다고 명시되어 있다. 또한 사람들은 새롭고 자극적인 정보를 좋아하고, 비판적 사고 없이 쉽게 믿고 공유하는 경향이 있다고 설명하고 있다. 지문에서는 사람들이 증거 없이 정보를 믿고, 비판적으 로 검토하지 않는다는 내용이 나오므로 사실과 반대이 다. 지문에서는 가짜 뉴스가 사람들의 주목을 끌기 위해 일부 그룹이나 개인에 의해 제작된다고 설명하며, 정부 관련 내용은 없다. 사람들은 진실보다는 자극 적이고 눈길을 끄는 정보를 좋아해서 가짜 뉴스가 퍼지 는 것이라고 설명하고 있다. 이 선택지는 내용과 반대 이다. 지문에 따르면, 사람들은 단순하고 즉각적으 로 이해되는 정보를 선호하고 쉽게 믿는다고 되어 있으 므로, 복잡할수록 믿는다는 내용은 지문과 다르다.', 1),
('75892f66-2bd9-4c97-9172-d893960f6a95', 'f608cb4e-5414-408b-ac81-537e9231fd20', 15, '빈칸추론', '논리/추론', true, '1', '지문의 빈칸 앞뒤 문장은 모두 사람들이 비판적 사고 없이 정보를 쉽게 받아들인다는 내용을 담고 있다. 첫 번째 빈칸은 증거 없이 새로운 정보를 믿는다, 두 번째 빈칸은 선거철에 자신이 지지하는 후보에 대한 뉴스를 무비판적으로 믿는다는 문맥이다. 만들다 조사하 다 피하다 무시하다', 1),
('e85c3e9e-455e-4c6e-99ff-04464a28d673', 'f608cb4e-5414-408b-ac81-537e9231fd20', 16, '제목요지', '주제파악', false, '가짜 뉴스에 속지 않기 위한 방법들', '제시된 지문 전체가 가짜 뉴스에 속지 않기 위해 개 인이 할 수 있는 구체적인 방법들을 설명하고 있다. 자 극적인 제목을 넘어서 읽기, 비판적 사고 적용하기, 편 향 점검하기, 출처의 신뢰성 확인하기 등이 그 방법들 에 해당한다.', 1),
('e7f3dd3e-4353-4973-968c-c9bfc71ade67', 'f608cb4e-5414-408b-ac81-537e9231fd20', 17, '빈칸추론', '논리/추론', true, '1', 'ⓐ ''사람을 잘못된 방향으로 이끌다''는 뜻으로, 가 짜 뉴스가 사람들을 오도할 수 있다는 문맥에 가장 정 확하게 맞는다. ⓑ 지루한, 자극 없는 지문에서는 자극적인 제목이 클릭을 유도한다고 했으므로, 자극적 인(stimulating)이라는 단어가 들어가야 한다. ⓒ 공 정함 판단에 영향을 줄 수 있는 요소로 지문은 편향 (biases)을 점검하라고 했다. ⓓ 신뢰할 수 없음 뉴 스 출처가 믿을 만한지 확인하라고 했으므로, 신뢰도 (credibility)라는 단어가 들어가야 한다. ⓔ 무효의, 타당하지 않은 뉴스의 근거가 타당한지 판단하라고 했 으므로, 타당한(valid)이라는 단어가 들어가야 한다.', 1),
('0f9cce99-150f-44da-aeb5-86ce95b1105e', 'f608cb4e-5414-408b-ac81-537e9231fd20', 18, '빈칸추론', '논리/추론', true, '2', 'provocative는 ''자극적인, 도발적인''이라는 뜻으 로, 콘텐츠 제작자들이 사람들의 관심을 끌기 위해 자 극적인 거짓 이야기를 만들어낸다는 문맥과 정확히 맞 는다. 지루한 혼란스러운 교육적인 감정 적인', 1),
('67f07fff-4ab2-4527-bb2f-73d15cc8a924', 'f608cb4e-5414-408b-ac81-537e9231fd20', 19, '내용일치', '독해/사실확인', false, '사람들의 관심을 끌고, 게시물의 조회 수를 높여 돈을 벌기 위해서이다.', '지문에 따르면, 가짜 뉴스는 콘텐츠 제작자들이 사람 들의 주목을 끌고 수익을 올리기 위해 만들어낸다고 설 명되어 있다. to make money by raising~라는 문장 이 바로 그 이유를 직접적으로 나타낸다.', 1),
('418358db-77c1-451b-84b8-72d958adcffc', 'f608cb4e-5414-408b-ac81-537e9231fd20', 20, '내용일치', '독해/사실확인', false, 'anxious, believe', '비상사태 동안 가짜 뉴스가 퍼지는 한 가지 이유는 사람들이 불안해하고 소셜 미디어의 가짜 뉴스 이야기 를 믿기 때문이다. 비상사태 상황에서 사람들은 여진에 대한 불안감 때문에 사실 여부를 확인하지 않은 채 소 셜 미디어의 정보를 믿고 행동하게 되며, 이런 심리 상 태가 가짜 뉴스 확산의 원인이 된다.', 1),
('cd80cd37-66b0-43c9-bd14-ad4118106551', 'f608cb4e-5414-408b-ac81-537e9231fd20', 21, '어법', '문법/어휘', true, '1', '본문의 빈칸 문장은 so ~ that ... 구문이다. 이 구문 은 ''너무 ~해서 …하다''의 의미를 가진 결과 표현이며, 반드시 that이 들어가야 한다. 그녀는 그가 정직하 다고 믿는다. 여기서 that은 명사절 접속사로 쓰였으며, believe의 목적어가 되는 절이다. 비가 왔기 때문에 나는 집에 있었다. 날씨가 좋으면 우리는 하이킹 갈 것이다. 그는 피곤했지만 계속 일했다. 역에 도 착하면 나에게 전화해라.', 1),
('ca7f3aac-07aa-40dc-afff-5456ec0bd578', 'f608cb4e-5414-408b-ac81-537e9231fd20', 22, '지칭', '논리/추론', true, '2', '밑줄 친 표현들 중 ㉠, ㉢, ㉣, ㉤는 모두 가짜 뉴스 와 관련된 내용, 사건, 영향을 가리킨다. 그러나 ㉡은 TV 뉴스 방송이라는 진짜 뉴스를 가리키므로, 나머지 넷과 다른 대상을 지시한다.', 1),
('87092356-21b3-4f28-971a-6e6ff2239358', 'f608cb4e-5414-408b-ac81-537e9231fd20', 23, '내용추론', '독해/사실확인', true, '3', '지나가 가짜 뉴스를 퍼뜨린 사실을 깨닫고 부끄러움 을 느끼는 것으로 끝난다. 이 경험에 대한 자연스러운 귀결은 반성과 다짐이므로, 뒤에 이어질 내용으로 가장 적절한 것은 ''지나가 다시는 확인되지 않은 뉴스를 퍼뜨리지 않겠다고 다짐했다.''이다. 지나의 친구들은 그녀를 용서했다. 그 가짜 뉴스 게시물은 빠르게 삭 제되었다. 몇몇 학생들은 수업 중 토론에서 지나의 사례에 대해 이야기했다. 한 교사는 잘못된 정보의 위험성을 가르치기 위해 지나의 경험을 사용했다.', 1),
('6ed7e566-2195-456c-a3fe-47fd07f38a9d', 'f608cb4e-5414-408b-ac81-537e9231fd20', 24, '어법', '문법/어휘', true, '2', 'ⓐ가 들어갈 자리는 모두 결과절(so ~ that) 또는 관 계절을 필요로 하는 문맥이다. that은 결과를 이끌기도 하고, 관계대명사로서 명사 수식도 가능하므로 네 군데 모두에 자연스럽게 쓰일 수 있다. 반면, because, although, unless, while은 특정 부사절 접속사로 일 부 문장에만 쓸 수 있어 공통 적용이 불가능하다.', 1),
('c7244ead-4c2d-419e-8291-3970660f1420', 'f608cb4e-5414-408b-ac81-537e9231fd20', 25, '어법', '문법/어휘', true, '5', '빈칸 (가)는 앞선 조언들과 마찬가지로 ''~해야 한다'' 라는 의무나 권고의 의미를 나타내는 조동사가 필요하 다. 따라서 ''should''가 가장 적절하다. 번 문장 역시 ''~해야 한다''는 조언의 의미로 조동사 ''should''를 사용 하고 있으므로 정답이다. 그는 6시쯤 여기 올 것이 다. 나는 네 숙제를 도와줄 수 있다. 그들은 휴 일 동안 우리를 방문할지도 모른다. 우리는 자전거 를 탈 때 헬멧을 반드시 써야 한다.', 1),
('8078f18a-2414-4a57-b77c-4874f0fa109e', 'e804729f-d260-40a9-bad7-528c3cac67d4', 1, '어휘', '문법/어휘', true, '5', '주어진 영어 설명은 ''허용되거나 가능한 최대의 양, 수 또는 수준''을 의미하며, 이는 ''제한, 한계''를 뜻하는 limit에 대한 설명이다. 본문에서 엄마가 아들에게 화면 사용 시간에 제한(limit)을 두라고 제안하므로 가 정 답이다. 앱 시간 도움 잠', 1),
('335d98d2-4ec0-4309-a0da-ae5c74403e5b', 'e804729f-d260-40a9-bad7-528c3cac67d4', 2, '어휘', '문법/어휘', true, '4', '빈칸은 ''온라인 정보를 접할 때 요구되는 태도''를 나 타내며, 뒤 문장에 ''비판적으로 생각하라''는 내용이 이 어지므로, 주의, 비판, 경계와 관련된 형용사가 적절하 다. curious는 ''호기심 있는''이라는 의미로, 온라인 정보에 대해 신중하고 비판적으로 접근해야 한다는 문 맥과 맞지 않는다. 조심스러운 주의 깊은 비 판적인 방심하지 않는, 경계하는', 1),
('8dfd76d6-9326-46df-a8d5-17ad86ffdda5', 'e804729f-d260-40a9-bad7-528c3cac67d4', 3, '무관한문장', '글의흐름', true, '4', '어떤 사람들은 서로 충돌하는 의견으로 인한 불안을 줄여주기 때문에 에코 챔버가 편안하다고 느낀다. 바로 앞 문장인 ⓒ에서는 에코 챔버가 사회적 협력을 어렵게 만들고 분열을 심화시킨다고 했고, 뒤이어 나오는 ⓔ에 서는 이를 극복하기 위한 해결책으로 다양한 정보와 시 각을 수용해야 한다고 제시하고 있다. 즉, ⓓ의 내용은 앞뒤 문장이 전개하는 비판적인 흐름과 정반대의 태도 를 보이며, 에코 챔버의 부정적 결과를 약화시키는 내 용이므로 글의 전체 흐름에 어울리지 않는다.', 1),
('e5ecc804-5017-4a12-8929-4f2b5a248d84', 'e804729f-d260-40a9-bad7-528c3cac67d4', 4, '문장삽입', '글의흐름', true, '4', '주어진 문장의 ''it''은 (C)에서 언급된 ''유명 운동선수 가 사망했다는 가짜 뉴스''를 가리킨다. 이 문장은 그 뉴스가 사실은 관심을 끌기 위한 콘텐츠 제작자들에 의 해 만들어진 가짜였다는 점을 밝힌다. (D)는 그 당시 지나가 그러한 가짜 뉴스를 만들고 퍼뜨린 사람들을 비 판했다는 내용이다. 주어진 문장을 (D) 다음에 넣으면, 지나의 비판 대상이었던 그 뉴스가 구체적으로 어떻게 가짜였는지를 부연 설명한 후, (E)에서 현재 지나 자신 의 상황으로 자연스럽게 전환된다. 따라서 정답은 번 이다.', 1),
('8ac22bbb-1c05-470f-8e41-3a221820dae3', 'e804729f-d260-40a9-bad7-528c3cac67d4', 5, '글의순서', '글의흐름', true, '3', '(c)는 지나가 가짜 뉴스를 퍼뜨린 사실을 알고 당황 한 감정 반응을 보여주며, 바로 이어지는 (b)는 그 경험 이 과거 사건을 떠올리게 했다는 회상이다. 그 뒤의 (a) 는 떠올린 과거 사건의 구체적인 예시(운동선수 관련 가짜 뉴스)를 제시하고, (d)는 그 뉴스가 만들어진 이유 를 설명하며 자연스럽게 마무리된다. 감정 → 회상 → 예시 → 원인의 순서가 글의 흐름에 가장 잘 맞는다.', 1),
('9fb74d9f-dcb7-4bd3-b9b8-09b9d8996d44', 'e804729f-d260-40a9-bad7-528c3cac67d4', 6, '문장삽입', '글의흐름', true, '3', '주어진 문장은 ''그것(자극적인 뉴스)을 다른 사람에게 전달함으로써, 사람들은 주목을 받을 수 있다''는 내용 으로, 앞서 언급된 ''사람들이 자극적인 뉴스를 공유하 고 싶어 하는'' 이유와 그 방식에 대한 구체적인 설명이 다. (B) 다음 문장에서는 사람들이 놀랍고 자극적인 정 보를 공유하고 싶어 한다고 말한다. 여기에 주어진 문 장을 삽입하면, 사람들이 왜 그리고 어떻게 그 정보를 공유하는지(주목을 받기 위해, 먼저 게시함으로써)가 명 확해진다. 그 후 (C) 다음 문장의 ''Also''를 통해 가짜 뉴스가 퍼지는 또 다른 이유(단순하게 생각하는 경향) 로 자연스럽게 넘어간다. 따라서 주어진 문장이 들어가 기에 가장 적절한 곳은 (C)이다.', 1),
('a9a69038-a0ef-454f-b6bf-127eedd24205', 'e804729f-d260-40a9-bad7-528c3cac67d4', 7, '어휘', '문법/어휘', true, '5', 'ⓔ에서 사용된 ignored(무시했다)는 문법적으로는 맞 지만, 문맥상 부적절하다. 지문 전체에서 Gina는 가짜 뉴스를 무시한 것이 아니라, 그것을 믿고 친구들과 공 유했으며, 그 사실을 부끄러워한 것이다. 즉, Gina의 행동은 spread(퍼뜨리다)에 해당한다.', 1),
('71d05126-e42d-4ea2-bcdc-cf09b1b37eb2', 'e804729f-d260-40a9-bad7-528c3cac67d4', 8, '빈칸추론', '논리/추론', true, '1', 'ⓐ는 가짜 뉴스가 비상 상황에서 흔히 퍼진다는 일반 적인 설명 다음에 등장하며, 실제 사례를 소개하는 자 리이다. 또한 두 번째 ⓐ도 가짜 뉴스의 구체적인 내용 을 인용하기 전, 앞 문장을 더 자세히 설명하거나 구체 화하는 흐름이므로 같은 접속사로 자연스럽게 반복 사 용된다. 이처럼 두 ⓐ 모두에서 공통적으로 예시 도입 의 기능이 필요하므로, 예를 나타내는 접속사 for example이 가장 적절하다. 그러므로 대조적으로 그러나 결과적으로', 1),
('6ac270e6-ad63-4c5e-bea1-c97f0b51cc62', 'e804729f-d260-40a9-bad7-528c3cac67d4', 9, '글의순서', '글의흐름', true, '4', '(다)는 이야기의 도입부 사건 전개로, 지나가 가짜 뉴 스를 보고 친구들에게 공유한 뒤, TV 뉴스에서 그것이 거짓임을 알게 되는 장면이다. (가)는 그 일을 겪은 지 나의 반응과 회상으로 이어진다. 그녀는 부끄러움을 느 끼고, 예전에 있었던 또 다른 가짜 뉴스 사건을 떠올린 다. (나)는 과거의 사건에 대한 지나의 비판적인 태도와 현재 자신의 행동과의 대조를 보여준다. 이 부분은 회 상의 결론과 현재의 반성으로, (가)의 연장선이자 마무 리 역할을 한다.', 1),
('292a57c3-2fe4-4b8b-aa77-abe2055e7b5f', 'e804729f-d260-40a9-bad7-528c3cac67d4', 10, '어휘', '문법/어휘', true, '4', 'ⓓ invalid는 신뢰할 수 없는, 부적절한이라는 뜻이 다. 하지만 원래 문장은 뉴스의 출처가 믿을 만한지, 그리고 그 근거가 타당한지를 점검하라는 내용이다. 따 라서 여기에 들어가야 할 적절한 단어는 valid(타당한, 신뢰할 수 있는)이어야 한다.', 1),
('b01cfecb-cc1f-41c5-be19-5fdf959bf56a', 'e804729f-d260-40a9-bad7-528c3cac67d4', 11, '영작', '쓰기', false, 'You should examine who wrote the news story and what the intent was behind writing the news story.', '이 문장은 조언을 주는 문장이므로, 먼저 should examine이라는 조동사 표현으로 시작한다. 그 다음에 살펴봐야 할 두 가지 대상이 나오는데, 이 두 내용은 각각 간접의문문(who / what)의 형태로 쓰였고, examine의 목적어로 함께 연결되기 때문에 and로 병 렬 처리된다.', 1),
('550182f2-74f9-4e1d-a6fa-b6fc5e025638', 'e804729f-d260-40a9-bad7-528c3cac67d4', 12, '글의순서', '글의흐름', true, '2', '처음 문단 끝에 첫 번째 조언이 제시된다. (나)는 자 극적인 제목이 클릭을 유도할 수 있다는 설명과 함께 두 번째 조언이 이어지므로, 가장 먼저 나와야 한다. 그 다음 (가)에서는 세 번째 조언이 이어진다. 자신의 편향을 점검하고, 다양한 의견에 열린 자세를 가지라는 내용이다. 마지막으로 (다)는 뉴스를 누가 썼는지, 그 의도는 무엇이었는지를 살펴보라는 마지막 조언에 대한 구체적 설명이다.', 1),
('0e880005-703a-4247-88a6-5f5763b688ee', 'e804729f-d260-40a9-bad7-528c3cac67d4', 13, '영작', '쓰기', false, 'Anyone can be the next person to produce or spread fake news.', '문장은 누구나 ~할 수 있다라는 구조로 시작하므로 주어 ''anyone + 조동사 can + be 동사'' 형태가 온다. 그 뒤 the next person은 다음 사람이라는 명사구이 고, 이를 수식하기 위해 to produce or spread fake news라는 to부정사가 사용되었다.', 1),
('1bb8f427-aa4c-4d15-b5dd-d3bc72d310e6', 'e804729f-d260-40a9-bad7-528c3cac67d4', 14, '영작', '쓰기', false, 'Make sure that personal information is not sent when you use public Wi-Fi networks.', '문장은 명령문 형태이므로 주어 없이 make sure로 바로 시작하고, ''개인정보가 전송되지 않도록''은 is not sent라는 수동태 부정문으로 표현한다. 마지막으로 ''공 용 와이파이를 사용할 때''라는 상황은 when you use public Wi-Fi networks라는 시간 표현으로 자연스럽 게 덧붙이면 된다.', 1),
('8b33703c-2c7d-4c5f-9dcb-2113980ffbb3', 'e804729f-d260-40a9-bad7-528c3cac67d4', 15, '어휘', '문법/어휘', true, '3', 'randomly는 무작위로, 아무렇게나라는 뜻인데, 문맥 에서는 사람들이 자신의 믿음을 뒷받침하는 뉴스만 선 택적으로 받아들인다는 뜻이므로, selectively(선택적으 로)로 고쳐야 한다.', 1),
('77163f92-af41-44c0-9236-8f6a31f3c80c', 'e804729f-d260-40a9-bad7-528c3cac67d4', 16, '어휘', '문법/어휘', true, '5', '정확한 의미는 to move or be sent out to a larger area or group of people (퍼지다, 확산되다) 인데, 보기에서는 to limit(제한하다)라고 잘못 정의되어 있다. 관심이나 흥미를 끄는 어떤 것을 이해하거 나 판단하기 위해 주의 깊고 철저히 살펴보다 어떤 것에 반대하거나 막으려 하다 올바르거나 적절한지 확인하다', 1),
('89bf767b-000b-402c-9657-62b8b12994a4', 'e804729f-d260-40a9-bad7-528c3cac67d4', 17, '문장삽입', '글의흐름', true, '4', '가짜 뉴스를 만든 사람들이 조회 수를 올려 돈을 벌 기 위해 자극적인 거짓 이야기를 만들었다는 내용이다. 이는 (D)에서 지나가 가짜 뉴스를 만든 사람들을 비판 한 이유를 구체적으로 설명해주는 내용으로, 그 뒤에 자연스럽게 이어진다. 따라서 글의 흐름상 가장 적절한 위치는 (D)이다.', 1),
('ec390e60-cc0a-4d01-b6e0-f39ef3753ae8', 'e804729f-d260-40a9-bad7-528c3cac67d4', 18, '글의순서', '글의흐름', false, 'C-A-D-B', '(C) 가짜 뉴스의 정의와 목적을 설명하며 글의 시작 으로 적절하다. 이어서 (A)는 가짜 뉴스의 피해와 긴급 상황에서 퍼지기 쉬움을 이어 설명하고 있고, (D)는 (A) 의 내용을 구체적으로 보여주는 사례 소개로 연결된다. 마지막으로 (B)는 (D)에서 소개한 사례의 가짜 뉴스 내 용과 그 결과를 구체적으로 보여준다. 따라서 전체 흐 름은 정의(C) → 영향(A) → 사례(D) → 사례의 세부 내용(B) 으로 이어진다.', 1),
('f7ac3953-db9b-4af5-b837-481997506587', 'e804729f-d260-40a9-bad7-528c3cac67d4', 19, '내용일치', '독해/사실확인', false, 'a researcher at the Massachusetts Institute of Technology', '감정적이고 놀라운 내용이 거짓 정보의 확산 속도에 영향을 줄 수 있다는 점이 흥미롭다. 이 문장은 가짜 뉴스가 자극적일수록 더 빨리 퍼진다는 현상을 분석적 으로 바라보는 말이다. 본문에서 이 현상을 연구하고 수치로 제시한 유일한 주체는 MIT의 연구진이다.', 1),
('928a2820-ab6d-4562-bae5-c6e1f165640a', 'e804729f-d260-40a9-bad7-528c3cac67d4', 20, '빈칸추론', '논리/추론', true, '3', '빈칸 뒤에는 지나처럼 실수로 가짜 뉴스를 퍼뜨리는 일이 드문 일이 아니다라는 부정적인 현실 인식이 나온 다. 앞 문장에서는 지나가 가짜 뉴스를 퍼뜨린 일을 후 회하는 장면이 나오므로, 이런 상황이 흔하다는 사실을 강조하는 연결사로는 불행히도(Unfortunately)가 가장 자연스럽다. 그러므로 예를 들어 한편 대 조적으로', 1),
('ca96c398-842b-4c61-b7e3-05d272994084', 'e804729f-d260-40a9-bad7-528c3cac67d4', 21, '무관한문장', '글의흐름', true, '4', '앞까지 지나의 경험을 중심으로 진행되던 이야기에서 갑자기 가짜 뉴스의 정의나 긍정적인 측면을 말하면서 흐름을 끊고, 전체적인 비판적 톤과도 맞지 않아 어색 하다. 따라서 가장 자연스럽지 않은 문장은 Ⓓ이다.', 1),
('1cabf716-ed40-434e-971b-b1bbb03ea4ec', 'e804729f-d260-40a9-bad7-528c3cac67d4', 22, '문장삽입', '글의흐름', true, '3', '문장은 사람들이 자신이 믿고 싶은 정보에 끌리는 심 리, 즉 확증 편향과 관련된 내용을 다룬다. (A)와 (B)는 가짜 뉴스가 퍼지는 이유를 설명하는 인지적 요인 중심 의 내용이고, (C)는 ''이런 과정에서 사람들은 쉽게 ''확 증 편향''의 함정에 빠진다''라는 내용이다. 이때 주어진 문장이 들어가면, 확증 편향이라는 개념을 도입하기 전 그 배경이 되어 흐름이 자연스럽다. (D)는 이미 확증 편향의 정의를 구체적으로 설명하는 문장이므로, 그보 다 앞인 (C)에 주어진 문장을 넣는 것이 가장 논리적인 위치이다.', 1),
('18fe22d8-35d5-45f9-8097-5ca7ba1bd91a', 'e804729f-d260-40a9-bad7-528c3cac67d4', 23, '어휘', '문법/어휘', true, '5', '1번 문장은 공용 와이파이가 보통 안전하지 않기 때 문에 개인정보를 입력하지 말아야 한다는 내용이다. 여 기에는 안전한이라는 뜻의 secure가 가장 잘 어울린 다. 2번 문장은 지나가 가짜 뉴스를 퍼뜨린 사실에 대 해 느낀 감정을 말하고 있다. 당황한이라는 뜻의 embarrassed가 자연스럽다. 3번 문장은 어떤 뉴스가 사실이 아니었다는 내용을 다루고 있다. 가짜의라는 뜻 의 fake가 자연스럽다. 4번 문장은 비상 상황에서 가짜 뉴스가 퍼지는 일이 얼마나 흔한지를 말하고 있다. 흔 한이라는 의미의 common이 잘 어울린다. 5번 문장은 사람들이 선거철에 자신이 지지하는 후보에 대한 긍정 적인 뉴스를 쉽게 믿는다는 내용이다. 여기에는 지지하 는이라는 의미의 favored와 같은 단어가 적절하다.', 1),
('b3c2481c-97b3-4dae-824e-5d495f09de0e', 'e804729f-d260-40a9-bad7-528c3cac67d4', 24, '문장삽입', '글의흐름', true, '2', '주어진 문장은 ''예를 들어''로 시작하며 구체적인 사례 를 제시한다. (A)에서 가짜 뉴스가 사람들을 혼란시키 고 해를 끼칠 수 있다고 언급한 후, 이의 구체적인 예 시로 암본 지진 사례를 (B) 위치에 넣어 설명할 수 있 다. 그 뒤에 이어지는 문장 "It is very common for fake news to spread during states of emergency."는 이 사례를 바탕으로 일반적인 진술을 하는 것으로 볼 수 있으며, (C)의 ''This''는 (B)에 삽입 된 암본 지진 사례를 가리키게 되어 자연스러운 흐름을 만든다. 따라서 정답은 번이다.', 1),
('c0e7a415-511f-4a82-98c8-27c3b526037a', 'e804729f-d260-40a9-bad7-528c3cac67d4', 25, '빈칸추론', '논리/추론', true, '1', '(A)에는 ''자극적인 제목 때문에 클릭하게 된다''는 문 맥이 오므로, 우연히라는 의미의 accidentally가 가장 자연스럽다. (B)에는 ''자신의 판단에 영향을 줄 수 있는 요소''를 언급하고 있으므로, 편견들이라는 뜻의 biases 가 적절하다. (C)에는 ''출처의 무엇을 확인해야 하는가'' 라는 질문에 답해야 하므로, 정보의 신뢰성을 뜻하는 credibility가 가장 적절하다. - 12 -', 1),
('5ded08e3-9be5-4ad8-96e9-88a63a23e3f0', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 1, '제목요지', '주제파악', true, '3', '본문은 가뭄으로 인해 수도에서 물이 나오지 않게 되 어 사람들이 쇼핑몰에서 생수를 구매하는 상황을 묘사 하고 있다. 따라서 주제로 가장 적절한 것은 ''가뭄 으로 인한 물 부족 위기''이다. ''물 절약의 중요성''은 언급되지 않는다. ''가족의 쇼핑몰 나들이''는 글의 일 부 내용일 뿐 주제가 아니다. ''언론이 자연재해를 보도하는 방식''은 부분적으로만 언급된다. ''비상 상 황에서의 쇼핑 행동''은 글의 후반부 내용일 뿐 전체 주 제가 아니다.', 1),
('2192dc84-e9c0-4fe1-8bc4-4acde2edf154', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 2, '내용일치', '독해/사실확인', true, '4', 'Uncle Basil은 아이들과 함께 쇼핑몰에 들어갔다 ''는 본문의 내용과 일치하지 않는다. 본문에서 "You two go in. I''ll meet you inside"라고 언급하며 Uncle Basil은 아이들을 먼저 보내고 나중에 들어가겠 다고 했다. 따라서 정답은 이다.', 1),
('6c76d4ed-9875-4d00-a602-3c21e16a7354', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 3, '내용일치', '독해/사실확인', true, '2', '남자는 "Looks like you could use some help."라 고 말한 후 글쓴이의 대답을 기다리지 않고 카트 손잡 이를 잡았다고 했으므로(He doesn''t wait for us to answer before grabbing the cart''s handle), 글의 내용과 일치하지 않는 것은 이다.', 1),
('495491c8-4bfb-4d53-bf93-0d8c65065f9c', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 4, '내용일치', '독해/사실확인', true, '4', '건설 노동자는 "construction has almost stopped due to the severe heat"라고 말했으므로, 건설 작업 이 ''완전히 중단된 상태''가 아닌 ''거의 중단된 상태''이 다. 따라서 대화의 내용과 일치하지 않는 것은 이다.', 1),
('dc73823c-82aa-4eac-90c1-af2903ed9ca6', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 5, '어법', '문법/어휘', true, '5', 'ⓔ emphasize는 동사원형으로 쓰였는데, ''would like''의 목적어로 사용되는 동사는 to부정사 형태가 되 어야 한다. 따라서 emphasize를 to emphasize로 고 쳐 써야 한다.', 1),
('b5f70b77-7823-4b98-af6d-2586573d43f3', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 6, '내용추론', '독해/사실확인', true, '3', '가뭄으로 인해 집에서 수돗물이 나오지 않는 위기 상 황에서 Alyssa는 삼촌과 함께 물을 구하러 몰에 갔는 데, 사람들이 필수품인 생수를 사기 위해 블랙 프라이 데이 때처럼 몰려있는 상황을 묘사하고 있다. 이러한 위기 상황에서 Alyssa가 느끼는 심경으로 가장 적절한 것은 ''걱정되고 불안한''이다.', 1),
('b682c550-2b41-470c-9752-d92d815b3e62', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 7, '내용일치', '독해/사실확인', true, '2', 'Alyssa가 이전에 축구 연습 중에 Hali와 물을 나누었 다고 언급했으므로(Didn''t I share my water with you at the practice last week?), 글의 내용과 일치 하는 것은 이다.', 1),
('6b7cb942-b0f8-4842-a399-24be4f372566', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 8, '빈칸추론', '논리/추론', true, '2', 'Hali가 Alyssa에게 물을 나누어 주기를 거절했고(she turns back to me shaking her head), Alyssa는 얼 음을 가져가는 똑똑한 해결책을 찾았으며(Ice is water), 얼음은 나중에 물로 변할 수 있다는 내용의 글 이다. 따라서 요약문의 빈칸 (A), (B)에 들어갈 말로 가 장 적절한 것은 ''refused - change''이다.', 1),
('e26a6653-a651-49c0-849f-870fc087daa6', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 9, '내용일치', '독해/사실확인', true, '5', '본문에서는 사하라 사막의 눈, 60도 섭씨의 온도 차 이, 해수면 상승으로 50년 내에 사라질 것으로 예상되 는 파나마 지역의 섬, 모래폭풍으로 인해 노란 먼지와 모래로 덮인 프랑스의 스키 리조트 등 극단적인 기후 변화의 사례들을 언급하고 있다. 그러나 이러한 기후 변화를 막기 위한 해결책에 대한 내용은 언급되지 않았 다. 따라서 글을 읽고 답할 수 없는 것은 이다.', 1),
('475cb853-6138-49fe-9d82-fddb59708a91', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 10, '내용일치', '독해/사실확인', true, '5', '대화에서 건설 노동자가 임금 인상을 요구하는 내용 은 언급되지 않았다. 건설 노동자는 쉬는 시간에 시원 한 대피소와 작업 중 의료 지원이 필요하다고 말했지만 (We also need healthcare support while working), 임금에 관한 내용은 없다. 따라서 글을 읽고 답할 수 없는 것은 이다.', 1),
('58288e23-3b1b-48eb-b868-1f3b9a79c0f7', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 11, '내용일치', '독해/사실확인', true, '4', '글쓴이의 삼촌인 Uncle Basil이 나타났다는 내용은 있지만(It is Uncle Basil. He has arrived just in time.), 그가 어디에서 왔는지에 관한 정보는 본문에 언 급되어 있지 않다. 따라서 글을 읽고 답할 수 없는 것 은 이다.', 1),
('c01ca828-ffac-4ccd-988e-a194d2907c7f', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 12, '내용일치', '독해/사실확인', true, '5', '글쓴이가 "Ice is water. Just help me"라고 말한 후 "Garrett and I put one bag of ice after another into our cart"라고 했으므로, Garret이 글쓴이를 도와 얼음을 모았다는 것을 알 수 있다. 따라서 글의 내용과 일치하지 않는 것은 이다.', 1),
('0e2ec34f-7e84-442a-b747-307a4e837ebf', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 13, '내용일치', '독해/사실확인', true, '2', 'Alyssa가 "Didn''t I share my water with you at the practice last week?"라고 말한 것으로 보아, 이전 에 축구 연습 중에 Hali와 물을 나눠 마신 적이 있음을 알 수 있다. 따라서 글의 내용과 일치하는 것은 이 다.', 1),
('4493a26b-2e44-4ebb-a3a7-b007198c4ac5', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 14, '어법', '문법/어휘', true, '4', 'since''는 ''~이후로'' 또는 ''~때문에''라는 의미로 사용되는데, 문맥상 카트에 얼음이 높이 쌓인 것은 결 과이지 원인이 아니다. 따라서 ''since''를 ''until''(~할 때 까지)로 고쳐 써야 한다.', 1),
('81aeb32d-8182-4b6f-86d7-37c0d6e32270', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 15, '영작', '쓰기', false, 'Have you heard', '조건에 따라 ''have''로 시작하고, 무언가에 대해 알고 있는지 묻는 표현인 ''Have you heard''를 사용했다. 이는 ''have'' 다음에 ''you'' 주어와 ''heard'' 동사 과거분 사형으로, 3단어로 구성되어 있다.', 1),
('c656ce38-8f0b-45ec-8c27-a5994352a20c', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 16, '내용일치', '독해/사실확인', true, '3', '대화에서 A가 Ecofont에 대해 B에게 질문하고 설명 해주는 것으로 보아 A는 Ecofont에 대해 이미 알고 있 고, B가 "That''s news to me."라고 답한 것으로 보아 B가 처음 들어보았다는 것을 알 수 있다. 따라서 대화 의 내용과 일치하지 않는 것은 이다.', 1),
('4ddbbb05-26b0-493d-9397-4b2098a15dd8', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 17, '제목요지', '주제파악', true, '1', '가정에서 수돗물이 나오지 않는 비상 상황에서 가족 들이 물을 구하기 위해 쇼핑몰로 향하게 되고, 그곳에 서도 생수를 사려는 사람들로 붐비는 상황을 묘사하고 있다. 이 글은 가뭄으로 인한 물 부족 상황에서 가족이 겪는 비상 상황에 초점을 맞추고 있다. 따라서 글의 주 제로 가장 적절한 것은 ''물 부족으로 인한 가족의 비상 상황''이다.', 1),
('71996cca-1658-44ca-ad3c-4ddb4734a44a', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 18, '내용추론', '독해/사실확인', true, '1', '글쓴이는 일반적인 사고방식(물이 필요하다면 물을 구해야 한다)에서 벗어나 얼음이 물로 변할 수 있다는 창의적인 발상을 했다. 이렇게 기존의 틀에서 벗어나 새로운 관점으로 문제를 해결하는 모습은 ''Think outside the box.(틀에서 벗어난 사고를 하라)''라는 속 담에 가장 잘 맞는다. 따라서 "Ice is water"라고 생각 한 것에 가장 잘 맞는 속담은 이다.', 1),
('5fc39d10-dc8d-4120-a125-790586a4e445', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 19, '내용추론', '독해/사실확인', true, '2', '사람들이 물병을 사기 위해 줄을 서 있고, 참을성이 없는 표정과 얇은 예의로 가려진 적대감이 있으며, 진 열대는 이미 비어 있고, 글쓴이가 간신히 찾은 마지막 한 상자의 물을 다른 여성이 가로채 가는 상황이 묘사 되어 있다. 이런 상황은 물 부족으로 인한 긴장감과 절 박함을 보여준다. 따라서 글에 나타난 분위기로 가장 적절한 것은 ''긴장되고 절박한''이다.', 1),
('4fbd761e-7b50-4253-bc79-4fcf570bc120', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 20, '내용일치', '독해/사실확인', true, '2', '본문에서 "A concerning prediction for an island in the Panama region. It''s expected to disappear within 50 years due to rising sea levels."라고 언급 했으므로, 파나마 지역의 섬이 사라지는 원인이 해수면 상승이라는 것을 알 수 있다. 따라서 글을 읽고 답할 수 있는 내용으로 적절한 것은 이다.', 1),
('d8071eae-5d6f-4258-a0c0-c242b6201d98', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 21, '내용일치', '독해/사실확인', true, '4', '남자는 글쓴이의 제안(얼음 한 봉지를 가져가라)에 동 의하지 않고 오히려 "Why don''t you take a bag of ice for yourselves, and I''ll keep the rest."라고 말 하며 대부분의 얼음을 자신이 가져가겠다고 제안했다. 따라서 글의 내용과 일치하지 않는 것은 이다.', 1),
('dd579316-f0b3-4eff-8247-02d6b6aa6b00', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 22, '영작', '쓰기', false, 'As long as his hands are firmly locked on the handle of our cart', '밑줄 친 부분의 의미(그의 손이 우리 카트의 손잡이 에 단단히 고정되어 있는 한)를 표현하기 위해 조건에 맞게 영작했다. 조건의 부사절 접속사 ''as long as''를 사용하고, ''are firmly locked''와 같은 현재시제를 활 용하여 완전한 문장으로 작성했다.', 1),
('c97bf173-8f7a-4d80-ad90-3c2e6bb7073a', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 23, '빈칸추론', '논리/추론', true, '1', '건설 노동자는 "I always feel thirsty and can''t sleep soundly"라고 말했으므로 (A)에는 ''thirsty''가 적 절하다. 또한 인터뷰어는 마지막에 "health and safety should always be a top priority"라고 강조했으므로 (B)에는 ''safety''가 적절하다. 따라서 빈칸 (A)와 (B)에 들어갈 말로 가장 적절한 것은 ''thirsty - safety''이 다.', 1),
('b03d82fa-ae93-4299-9a7f-70299aa62254', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 24, '내용일치', '독해/사실확인', true, '4', '강연자는 숲이 수분을 대기 중으로 방출하고 구름 형 성과 강우를 촉진하기 때문에 산림 벌채로 인해 가뭄이 악화된다고 설명했다. 따라서 숲이 많을수록 가뭄이 더 심해진다는 것은 글의 내용과 일치하지 않는다.', 1),
('2b9bd02d-fd2c-46df-9334-b12e2e1bd84f', '14b43fa4-a06d-42b7-abe8-8a4abfdf0bce', 25, '영작', '쓰기', false, 'importance of understanding these factors', '<조건>에 맞게 ''importance''를 사용하고 ''of understanding''을 포함하여 5단어 이내로 ''가뭄 관리 를 위한 이러한 요소들의 이해의 중요성''을 영작했다.', 1),
('fa8815a4-f4f7-4a43-b82e-a24dac03cb0a', '795866e4-d30b-43b8-b721-be3dc12bbf90', 1, '어법', '문법/어휘', true, '5', 'ⓔ pulling은 어법상 틀린 형태이다. find의 목적어인 a single case of water에 대한 관계대명사절 내에서 that은 목적격 관계대명사로 water를 수식하고 있다. 그런데 ''pulling away''는 능동형으로 쓰였으나 문맥상 ''(물병이) 당겨져 멀어지는'' 수동의 의미가 되어야 하므 로 pulled away로 고쳐야 한다.', 1),
('23723ea4-fa68-4f1a-940d-a1775e7cbf97', '795866e4-d30b-43b8-b721-be3dc12bbf90', 2, '어휘', '문법/어휘', true, '2', '본문은 줄을 서 있는 사람들의 얼굴에 조바심의 표정 과 공손함에 가려진 적대감이 있다는 내용이다. 그 공 손함도 얇게 늘어져 있다(stretched thin)고 표현했으 므로, 빈칸에는 ''층, 겹''을 의미하는 layer가 가장 적절 하다. 더미 왕관 위기 쌓아 올린 것', 1),
('4f22c3c9-799d-40c5-9beb-4c12bad9c7cf', '795866e4-d30b-43b8-b721-be3dc12bbf90', 3, '어휘', '문법/어휘', true, '3', '빈칸 앞에서 언급된 "flow crisis"는 가뭄을 나타내는 표현이며, 빈칸 다음 문장에서 수돗물이 나오지 않는다 는 내용이 이어지므로, 빈칸에는 ''위기''를 의미하는 ''crisis''가 가장 적절하다.', 1),
('29b74e76-1198-4b86-bb29-437afd9e6721', '795866e4-d30b-43b8-b721-be3dc12bbf90', 4, '어휘', '문법/어휘', true, '3', '뉴스 앵커가 "flow crisis"(물 부족 위기)에 대해 이야 기하고 있는 상황에서 ''축하하다''는 의미의 ''celebrating''은 문맥상 적절하지 않다. 위기 상황을 보 도하는 상황이므로 ''reporting''(보도하다)이나 ''discussing''(논의하다)과 같은 단어가 더 적절하다.', 1),
('c30f6637-e793-439f-b455-ee1da280eda5', '795866e4-d30b-43b8-b721-be3dc12bbf90', 5, '어법', '문법/어휘', true, '4', 'ⓓ에서 ''what''은 관계대명사로 사용되었는데, 이 경 우 선행사가 있으므로 ''which''나 ''that''을 사용해야 한 다. 따라서 ''what''을 ''that''으로 고쳐 써야 한다.', 1),
('2e160dcd-e97a-4f95-9a16-cc9fd1cfddca', '795866e4-d30b-43b8-b721-be3dc12bbf90', 6, '문장삽입', '글의흐름', true, '1', '주어진 문장 "There is even hostility, hidden by a thin layer of politeness."는 사람들의 표정에 대한 묘사로, 참을성 없는 표정(a look of impatience)과 예 의가 얇게 늘어져 있다는 표현(politeness is stretched thin) 사이에 위치하는 것이 자연스럽다. 따 라서 주어진 문장이 들어가기에 가장 적절한 곳은 (A) 이다.', 1),
('15fb887c-15bd-447e-b758-0ebd5d2d37ae', '795866e4-d30b-43b8-b721-be3dc12bbf90', 7, '어휘', '문법/어휘', true, '1', '(A) "해수면 상승으로 인해 50년 이내에 사라질 것으 로 예상된다"는 내용이므로 ''disappear''(사라지다)가 적 절하다. (B) "극단적인 기후 변화가 계속해서 우리 세계 에 도전하고 있다"는 의미이므로 ''challenge''(도전하다) 가 적절하다. (C) "이러한 환경적 문제들에 대한 더 많 은 통찰력을 얻기 위해 계속 지켜봐 주세요"라는 맥락 이므로 ''insights''(통찰력)가 적절하다. 따라서 문맥상 적절한 단어로 이루어진 것은 ''disappear - challenge - insights''이다.', 1),
('42f7cc7c-ff58-467a-a0ab-2a100f5e47f2', '795866e4-d30b-43b8-b721-be3dc12bbf90', 8, '어휘', '문법/어휘', true, '2', '극단적인 기후 변화가 계속해서 우리 세계에 도전하 고 있다는 내용 뒤에, 이러한 환경적인 무언가에 대한 더 많은 정보를 제공하겠다는 말이 이어지므로, 빈칸에 는 ''도전''이라는 의미의 ''challenges''가 가장 적절하다.', 1),
('03406c10-19a3-4e33-b1fc-290e0d2f569d', '795866e4-d30b-43b8-b721-be3dc12bbf90', 9, '어휘', '문법/어휘', true, '3', '사람들이 물을 마시거나 씻을 수 없는 심각한 가뭄 상황에 대해 말하고 있는데, ''delightful''(즐거운, 유쾌 한)이라는 표현은 부정적인 상황을 묘사하는 맥락에 어 울리지 않는다. ''terrible''(끔찍한)이나 ''concerning''(우 려스러운)과 같은 단어가 더 적절하다.', 1),
('39a21224-aa13-45b3-af33-65edb393e6da', '795866e4-d30b-43b8-b721-be3dc12bbf90', 10, '문장삽입', '글의흐름', true, '5', '주어진 문장 "Even Korea is in danger of having water shortages in the near future"는 가뭄 문제가 우리 모두에게 경고가 된다는 내용을 뒷받침하고 구체 화하는 예시로 작용한다. 따라서 "I''d like to emphasize that it''s a warning for us all."이라는 말 다음인 (E)에 위치하는 것이 가장 적절하다.', 1),
('546b1894-e70a-46bc-9d32-79b254f21d95', '795866e4-d30b-43b8-b721-be3dc12bbf90', 11, '글의순서', '글의흐름', true, '4', '주어진 글에서 뉴스 앵커가 "flow crisis"에 대해 이 야기하고 있다는 내용 다음에는, 그것이 무엇인지 설명 하는 (C)가 이어지는 것이 자연스럽다. 그 다음으로는 위기 상황에 대응하기 위해 삼촌이 쇼핑몰로 가자고 제 안하는 (A)가 오고, 마지막으로 쇼핑몰에 도착한 후 상 황을 묘사하는 (B)가 이어지는 것이 논리적인 흐름이다. 따라서 주어진 글 다음에 이어질 글의 순서로 가장 적 절한 것은 이다.', 1),
('c3247043-029f-4f88-8c32-713bcee3d9ba', '795866e4-d30b-43b8-b721-be3dc12bbf90', 12, '내용일치', '독해/사실확인', true, '4', '(A)에서 "As we pull into the parking lot, we can see the crowd"라고 했으므로, 마트 주차장에 많은 사 람이 있었다는 것을 알 수 있다. 따라서 마트 주차장은 사람들이 많지 않았다는 내용은 글의 내용과 일치하지 않는다.', 1),
('f553d4d9-6a3a-4504-bc80-acc1c42484ab', '795866e4-d30b-43b8-b721-be3dc12bbf90', 13, '문장삽입', '글의흐름', true, '4', '남자가 카트 손잡이를 잡아준 후에 글쓴이가 고마움 을 표현하는 것이 자연스러운 흐름이다. 남자가 "Looks like you could use some help"라고 말하고 대답을 기다리지 않고 카트 손잡이를 잡은 후, 그에 대한 글쓴 이의 감사 인사 "Thank you for helping us"가 오고, 이어서 남자의 답변 "Not a problem. We all need to help one another"가 오는 것이 논리적인 순서이다. 따라서 주어진 문장이 들어가기에 가장 적절한 곳은 (D)이다.', 1),
('5150bec0-75e9-4431-a92f-02701f258dda', '795866e4-d30b-43b8-b721-be3dc12bbf90', 14, '어법', '문법/어휘', true, '1', 'ⓐ ''ridiculous''는 형용사로, 부사어 위치에 쓰였으므 로 부사형인 ''ridiculously''로 고쳐 써야 한다. ''ridiculously heavy''는 ''터무니없이 무거운''이라는 의 미이다.', 1),
('1777fcb2-67fe-4afc-a5b7-f450ac1e7b0a', '795866e4-d30b-43b8-b721-be3dc12bbf90', 15, '내용추론', '독해/사실확인', true, '5', '상점에 온 사람들의 참을성 없는 표정과 감춰진 적대 감, 얇게 늘어진 예의, 비어 있는 진열대, 마지막 남은 물을 다른 사람에게 뺏기는 상황 등이 묘사되어 있다. 이러한 상황은 물 부족으로 인한 절박함을 보여준다. 따라서 글의 분위기를 묘사한 단어로 가장 적절한 것은 ''절박한''이다. 기쁜 단조로운 유머러스한 평화로운', 1),
('f8de7f8b-36e2-4dbd-8275-279d53824596', '795866e4-d30b-43b8-b721-be3dc12bbf90', 16, '영작', '쓰기', false, 'difficult times can bring out the best in people', 'bring out the best in'' 표현을 사용하고, ''people'' 을 포함하며, ''can''을 사용하여 ''어려운 시기에 사람들 의 가장 좋은 면이 드러날 수 있다''는 의미를 표현한 다.', 1),
('0f01d00e-4242-4d64-892f-9599048675c0', '795866e4-d30b-43b8-b721-be3dc12bbf90', 17, '영작', '쓰기', false, 'Didn''t I share my water with you at the practice last week?', '조건에 맞게 의문문 형태로 작성하고, ''Didn''t''를 사 용하여 과거시제를 표현한다. 또한 ''share ~ with''와 ''at the practice'' 표현을 활용하여 ''지난 주 연습 때 내가 너와 물을 나누지 않았니?''라는 의미를 영작한다.', 1),
('e6205533-b516-4fc5-bd4a-5225431fb674', '795866e4-d30b-43b8-b721-be3dc12bbf90', 18, '글의순서', '글의흐름', true, '4', '주어진 글 다음에는 수도관 차단의 직접적인 결과를 언급하는 (C)가 자연스럽게 이어진다. 이후 B의 상황 평가와 뉴스 언급(B), G의 가뭄 원인 설명(A), 마지막으 로 실제 영향을 보여주는 사진에 대한 B의 반응(D) 순 으로 대화가 논리적으로 전개된다. 따라서 가장 적절한 순서는 ''(C) - (B) - (A) - (D)''이다.', 1),
('0ca167a6-e09a-4cb0-a19c-946b6e20a486', '795866e4-d30b-43b8-b721-be3dc12bbf90', 19, '빈칸추론', '논리/추론', true, '3', '남자는 친절하게 도움을 주는 척하다가 진짜 의도를 드러낸다. 글쓴이가 얼음 한 봉지를 제안하자, 남자는 대부분의 얼음을 자신이 가져가겠다는 이기적인 제안을 한다. 이후 글쓴이가 놀라는 반응을 보이는 것으로 보 아, 빈칸에는 "I''ll keep the rest"(내가 나머지를 가 져갈게)가 가장 적절하다.', 1),
('a8a2fc3a-527a-49a9-8bdb-8e3775ed7802', '795866e4-d30b-43b8-b721-be3dc12bbf90', 20, '대화문', '화용/의사소통', true, '5', '빈칸 다음에 "droughts worsened by deforestation?"이 이어지고, 그 후에 산림 벌채가 가 뭄을 악화시키는 이유에 대한 설명이 제시된다. 이러한 맥락에서는 강연자가 청중에게 ''산림 벌채로 인해 악화 된 가뭄에 대해 들어본 적이 있는지'' 묻는 표현이 자연 스럽다. 따라서 빈칸에 들어갈 말로 가장 적절한 것은 "Have you heard of"(~에 대해 들어본 적이 있나 요?)이다.', 1),
('6f798369-d01d-403d-8e57-f522c94d0a30', '795866e4-d30b-43b8-b721-be3dc12bbf90', 21, '대화문', '화용/의사소통', true, '5', 'B의 "That''s news to me"(처음 듣는 소식이네요)라 는 응답과 "What is Ecofont?"(Ecofont가 무엇인가 요?)라는 질문은 A가 B에게 Ecofont에 대해 알고 있는 지 물었다는 것을 나타낸다. 따라서 빈칸에는 ''~에 대 해 들어본 적이 있나요?''라는 의미의 "Have you heard of"가 가장 적절하다.', 1),
('6fd94db3-e4c4-4098-b092-aa0176ca527f', '795866e4-d30b-43b8-b721-be3dc12bbf90', 22, '어휘', '문법/어휘', true, '1', '극단적인 기후 변화가 계속해서 우리 세계에 도전하 고 있다는 내용 뒤에, 이러한 환경적인 문제에 대한 더 많은 정보를 제공하겠다는 맥락이므로, 빈칸에는 ''통찰 력, 이해''라는 의미의 ''insights''가 가장 적절하다.', 1),
('78f4ab09-14c4-49c1-a496-21621e68f802', '795866e4-d30b-43b8-b721-be3dc12bbf90', 23, '어법', '문법/어휘', true, '4', 'ⓓ ''challenge''는 단수형으로 사용되었는데, 앞에 ''these environmental''이라는 표현이 있으므로 복수형 인 ''challenges''로 고쳐 써야 한다. ''these''는 복수 지 시형용사이므로 뒤에 오는 명사도 복수형이어야 한다.', 1),
('9f3f3b85-b958-4f18-8297-9ad4de9cdcaf', '795866e4-d30b-43b8-b721-be3dc12bbf90', 24, '어휘', '문법/어휘', true, '3', '가뭄으로 인해 수돗물이 나오지 않는 상황에서 사람 들이 쇼핑몰에서 물병을 사려고 하는 모습이 묘사되어 있다. 이러한 상황에서 물은 생존에 필수적인 요소임을 강조하기 위해 빈칸에는 ''필수품''이라는 의미의 ''essentials''가 가장 적절하다.', 1),
('cdd6a70f-ba9c-4649-b492-8fd19a9c643b', '795866e4-d30b-43b8-b721-be3dc12bbf90', 25, '어법', '문법/어휘', true, '4', 'ⓓ ''heard''는 과거분사형으로 사용되었는데, 전치사 ''of'' 다음에 동명사 형태가 와야 한다. 따라서 ''heard'' 를 ''hearing''으로 고쳐 써야 한다. ''got tired of hearing''은 ''듣는 것에 질리다''라는 의미이다.', 1),
('5ea57e17-5d79-40c9-9226-84ca320e58cf', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 1, '글의순서', '글의흐름', true, '4', '주어진 글 다음에는 Garret을 찾아 얼음을 발견하는 (B)가 먼저 오고, 얼음이 물이라고 설명하며 카트에 얼 음을 담는 (C)가 이어진다. 마지막으로 다른 사람들도 얼음을 가져가기 시작하고 무거운 카트와 양복 입은 남 자를 만나는 (A)로 연결되는 것이 자연스럽다. 따라서 가장 적절한 순서는 이다.', 1),
('994e76db-3836-425e-9a54-1d03610013b5', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 2, '글의순서', '글의흐름', true, '5', '주어진 글에서 건설 노동자가 더위로 인해 목마름을 느끼고 숙면을 취하지 못한다고 말한 후, 진행자가 그 것이 위험하다며 일에 어떤 영향을 미치는지 묻는 (E) 가 먼저 이어져야 한다. 그 다음 노동자가 일정을 조정 하고 물과 선풍기를 가지고 다닌다는 대답(B), 진행자의 시원한 대피소 제공 제안(C), 노동자의 의료 지원 필요 성 언급(D), 마지막으로 진행자의 건강과 안전을 강조 하는 마무리(A) 순으로 대화가 자연스럽게 전개된다.', 1),
('14bf2de6-80f3-46e4-850e-ace4361ebbec', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 3, '글의순서', '글의흐름', true, '2', '주어진 글에서 가뭄으로 인해 수돗물이 나오지 않는 위기 상황을 묘사한 후, 삼촌이 쇼핑몰로 가자고 제안 하고 트럭을 타고 이동하는 내용의 (B)가 이어지는 것 이 자연스럽다. 그 다음으로는 쇼핑몰 내부의 혼잡한 모습과 물병을 사려는 사람들의 모습을 묘사한 (A)가 오고, 마지막으로 사람들의 얇게 늘어진 예의와 빈 진 열대를 발견하는 내용의 (C)가 이어지는 것이 논리적인 흐름이다. 따라서 주어진 글 다음에 이어질 글의 순서 로 가장 적절한 것은 이다.', 1),
('e4b549f2-e074-4f93-83d9-11f8711af747', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 4, '어법', '문법/어휘', true, '4', 'ⓓ ''approaching''은 현재분사로 사용되었는데, 문맥 상 주어인 ''I''가 행동하는 현재시제 동사가 필요하다. 따라서 ''approaching''을 ''approach''로 고쳐 써야 한 다.', 1),
('17699737-76bd-411d-8226-e226b2747388', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 5, '내용추론', '독해/사실확인', true, '1', '남자가 "Why don''t you take a bag of ice for yourselves, and I''ll keep the rest"(너희는 얼음 한 봉지만 가져가고, 내가 나머지를 가져갈게)라고 제안한 것은 글쓴이가 모은 얼음 대부분을 남자가 가져가겠다 는 터무니없는 제안이다. 그래서 글쓴이는 처음에 남자 가 농담하는 것으로 생각했다가 그가 진지하다는 것을 깨달았다. 따라서 글쓴이가 (A)라고 생각한 이유로 가 장 적절한 것은 이다.', 1),
('c9e362cb-6628-4802-bf4c-4e15638d8fb2', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 6, '어법', '문법/어휘', true, '4', 'ⓓ ''had arrived''는 과거완료 시제로 사용되었는데, 문맥상 현재완료 시제인 ''has arrived''가 적절하다. Uncle Basil이 ''바로 적시에'' 도착했음을 나타내기 위 해서는 현재완료 시제를 사용하는 것이 맞다.', 1),
('4255cfe5-2d80-4d87-8a69-c6a4906d2a99', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 7, '문장삽입', '글의흐름', true, '1', '주어진 문장은 "flow crisis"에 대한 설명으로, 이것 이 미디어가 사람들이 ''drought''라는 단어를 듣는 데 지쳤기 때문에 가뭄을 부르는 새로운 방식이라는 내용 이다. 이러한 설명은 뉴스 앵커가 "flow crisis"에 대해 이야기하고 있다는 언급 다음, 위기가 새로운 단계로 접어들고 있다는 내용 전에 위치하는 것이 자연스럽다. 따라서 주어진 문장이 들어가기에 가장 적절한 곳은 (A)이다.', 1),
('e8c17cd1-190b-4871-877c-de1eeb6b331e', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 8, '빈칸추론', '논리/추론', true, '3', '어제만 해도 그렇게 귀중한 물품이 아니었을 때 누군 가가 버려둔 물 한 상자를 발견했다는 내용이다. 가뭄 으로 인해 물이 부족해진 상황에서 물이 귀중한 자원이 되었음을 나타내는 맥락이므로, 빈칸에는 ''귀중한, 소중 한''이라는 의미의 ''precious''가 가장 적절하다.', 1),
('0ae4539a-cf95-41a1-b610-e3c724439a69', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 9, '문장삽입', '글의흐름', true, '1', '주어진 문장 "The shelves are already empty"(진 열대가 이미 비어 있다)는 글쓴이가 상점 뒤쪽으로 가 서 물병을 찾았지만 늦었다는 것을 깨달은 이유를 설명 해주는 내용이다. 따라서 "I realize I am too late"(너 무 늦었다는 것을 깨닫는다) 다음인 (A)에 위치하는 것 이 논리적으로 가장 자연스럽다.', 1),
('6eeddbeb-d094-4aa9-9e15-3dfb124df1be', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 10, '영작', '쓰기', false, 'It is expected to disappear within 50 years due to rising sea levels.', '조건에 맞게 ''is expected to'' 구문의 축약형 ''It''s expected to''를 사용하고, ''due to'' 표현과 ''within 50 years''를 포함하여 ''파나마 지역의 한 섬은 해수면 상 승으로 인해 50년 이내에 사라질 것으로 예상됩니다''라 는 의미를 완전한 문장으로 영작했다.', 1),
('2c98515d-522e-406b-b19b-0d0590984eb9', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 11, '빈칸추론', '논리/추론', true, '2', 'Garret이 물이 필요하지 얼음이 필요한 것이 아니라 고 말하자, 글쓴이는 얼음이 물이라는 사실(얼음이 녹 으면 물이 됨)을 깨닫고 도움을 요청한다. 이후 두 사 람이 함께 카트에 얼음을 담는 장면이 이어지므로, 빈 칸에는 "Ice is water. Just help me."(얼음은 물이야. 그냥 도와줘)가 가장 적절하다.', 1),
('95c4035e-57e6-44a0-bcdf-0e224549fddf', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 12, '어휘', '문법/어휘', true, '4', '문맥상 평소보다 절반도 안 되는 강우량이 내렸다는 내용이 되어야 가뭄이 심각하다는 내용과 일치한다. 그 러나 ⓓ ''increased''(증가했다)는 강우량이 늘었다는 의 미가 되어 문맥과 맞지 않는다. ''decreased''(감소했다) 또는 ''fallen''(내렸다)과 같은 단어가 더 적절하다. 따라 서 문맥상 가장 어울리지 않는 것은 ⓓ이다.', 1),
('b9879d7b-87c6-4384-879b-2b651fdefe76', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 13, '어휘', '문법/어휘', true, '5', '남자는 글쓴이의 카트에 있는 얼음 대부분을 가져가 려고 했다가 Uncle Basil이 나타나자 자신의 계획을 포 기하고 떠나게 된다. 이런 상황에서 남자가 "a joyful face"(기쁜 표정)으로 얼음을 보는 것은 문맥상 어울리 지 않는다. 오히려 실망하거나 불만스러운 표정이 더 적절하다. 실제로 원문에서는 "a bitter face"(쓴 표정, 씁쓸한 표정)으로 표현되어 있다. 따라서 문맥상 어울 리지 않는 것은 ⓔ이다.', 1),
('973814df-117b-41a5-b3dd-031886b2e665', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 14, '대화문', '화용/의사소통', true, '3', '빈칸 다음에 "droughts worsened by deforestation?"이라는 의문문이 이어지고, 그 후에 산 림 벌채가 가뭄을 악화시키는 이유에 대한 설명이 제시 된다. 이러한 맥락에서는 강연자가 청중에게 ''산림 벌 채로 인해 악화된 가뭄에 대해 들어본 적이 있는지'' 묻 는 표현이 자연스럽다. 따라서 빈칸에 들어갈 가장 적 절한 표현은 "Have you heard of"(~에 대해 들어 본 적이 있나요?)이다.', 1),
('e642fa6f-cdab-468e-9aa9-31669d7bb92e', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 15, '내용일치', '독해/사실확인', true, '4', '본문에서는 "trees release moisture into the atmosphere, and foster cloud formation and rainfall"(나무는 대기 중으로 수분을 방출하고, 구 름 형성과 강우를 촉진한다)이라고 했으므로, 나무가 대기 중 수분을 흡수한다는 내용은 글의 내용과 일치하 지 않는다. 오히려 나무는 대기 중으로 수분을 방출하 여 비가 내리도록 돕는다. 따라서 글의 내용과 일치하 지 않는 것은 이다.', 1),
('931a172c-5c33-4eee-9a29-9cb40f43bc1d', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 16, '빈칸추론', '논리/추론', true, '1', '줄을 서 있는 사람들의 참을성 없는 표정과 얇은 예 의로 가려진 적대감에 대한 묘사 다음에, 그 얇은 예의 마저도 ''늘어져 있다''는 표현이 문맥상 자연스럽다. 이 것은 사람들의 인내심이 한계에 도달하여 예의조차 거 의 유지되지 못하고 있음을 의미한다. 따라서 빈칸에 들어갈 말로 가장 적절한 것은 ''stretched''(늘어난, 팽팽하게 된)이다.', 1),
('a2cdf85c-da63-45b1-8dc5-e3c2afa61102', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 17, '대화문', '화용/의사소통', true, '2', '대화의 흐름과 B의 "Yes" 응답으로 볼 때, G가 캘리 포니아 가뭄에 대해 들어봤는지 묻는 표현이 자연스럽 다. B가 뉴스에서 읽었다고 대답하는 것으로 보아, 빈 칸에는 정보를 확인하는 "Have you heard that"이 가장 적절하다.', 1),
('7cd00d0b-b1c6-494e-b3f5-fdd5d00e08a8', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 18, '내용일치', '독해/사실확인', true, '4', 'B가 "It shows empty store shelves where water bottles used to be"라고 말했으므로, 사진에는 물병이 비어 있는 상점 선반이 보인다. 따라서 물병이 가득 찬 선반이 보인다는 는 대화의 내용과 일치하지 않는다.', 1),
('14f43d17-3211-4d8b-aa18-f0288587d69a', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 19, '빈칸추론', '논리/추론', true, '3', '뉴스 앵커가 ''유동 위기''(flow crisis)에 대해 이야기 하는 상황에서 ''위기가 새로운 단계로 접어들고 있다'' 고 한 후, 그 새로운 단계의 구체적인 현상으로 수돗물 이 나오지 않는 상황이 언급되는 것이 자연스럽다. 그 리고 그 심각한 상황 때문에 삼촌이 "쇼핑몰로!"라고 말 하며 물을 구하러 가자고 제안하는 흐름이 된다. 따라 서 빈칸에 들어갈 말로 가장 적절한 것은 "We have no running water out of the tap."(수돗물이 나오지 않는다)이다.', 1),
('730eb51f-5d8f-4e02-bcce-675ba41781f7', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 20, '빈칸추론', '논리/추론', true, '4', '빈칸 다음에 "This is because trees release moisture into the atmosphere, and foster cloud formation and rainfall"이라는 설명이 이어지므로, 빈 칸에는 산림 벌채가 가뭄을 악화시킨다는 내용이 들어 가야 한다. 특히 이전 문장에서 "not the only cause" 라고 했으므로 다른 원인을 소개하는 형태가 자연스럽 다. 따라서 빈칸에 들어갈 말로 가장 적절한 것은 "Have you heard of droughts worsened by deforestation?"(산림 벌채로 악화된 가뭄에 대해 들어 본 적이 있나요?)이다.', 1),
('87800115-6f58-4563-8d4e-1fa42f0b7752', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 21, '어법', '문법/어휘', true, '5', 'ⓔ에서 ''that''은 emphasize의 목적어를 이끄는 접속 사로 사용되었는데, "the importance of understanding these factors"라는 명사구가 그 목적 어이다. 이 경우 ''that''은 불필요하므로 삭제해야 한다. 따라서 "I''d like to emphasize the importance of understanding these factors"가 올바른 표현이다.', 1),
('698fb47c-3ae7-4f79-b1c0-1b27a2e6e2dc', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 22, '어법', '문법/어휘', true, '3', 'ⓒ ''have been taken notice''는 어법상 어색하다. ''take notice''는 ''주목하다''라는 의미의 구동사인데, 여 기서는 현재완료 시제로 표현해야 하므로 ''have taken notice''가 올바른 형태이다. ''been''은 불필요하다.', 1),
('0624eeb9-5cc2-4f13-a83d-51a86f9e897a', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 23, '글의순서', '글의흐름', true, '4', '주어진 글에서 수돗물이 나오지 않는 위기 상황을 묘 사한 후, 삼촌이 쇼핑몰로 가자고 제안하고 트럭을 타 고 이동하는 내용의 (C)가 이어지는 것이 자연스럽다. 그 다음으로는 쇼핑몰 내부의 혼잡한 모습과 물병을 사 려는 사람들의 모습을 묘사한 (A)가 오고, 마지막으로 사람들의 참을성 없는 표정과 빈 진열대를 발견하는 내 용의 (B)가 이어지는 것이 논리적인 흐름이다. 따라서 주어진 글 다음에 이어질 글의 순서로 가장 적절한 것 은 이다.', 1),
('05c194dd-e172-495d-97c3-20b1c4c83d58', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 24, '영작', '쓰기', false, 'Now the crisis is entering a new stage.', 'crisis''와 ''stage''를 포함하고, ''entering''을 사용한 다. ''is entering''은 be동사(is)와 현재분사(entering)의 결합으로 현재진행형의 형태를 갖추어 ''가뭄이 새로운 단계에 접어들고 있다''는 진행 중인 상황을 표현한다.', 1),
('db75cccf-6327-4ebf-84cc-138612d7f82c', 'f7d535c6-263c-4ec3-8fa0-751346bf85b7', 25, '내용추론', '독해/사실확인', true, '4', 'Hali는 엄마가 이미 통로를 따라 이동하고 있는 것을 보고 고개를 젓는 것으로 보아, 엄마의 뜻을 거스르지 못해(disobey mother) Alyssa에게 물을 나눠주지 않 았다. 그리고 Alyssa는 "Ice is water"(얼음은 물이다) 라고 말하며 얼음이 물로 변한다(becomes water)는 사실을 깨닫고 얼음을 가져가기로 결정했다. 따라서 가 장 적절한 표현 짝은 ''disobey mother - becomes water''이다.', 1),
('dcc59139-e0fe-4124-8bfe-d32cd40b99dd', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 1, '문장삽입', '글의흐름', true, '3', 'Arias가 박물관을 짓겠다고 답변한 직후에 Picasso 가 감동하여 돕기로 맹세하는 내용이 와야 하므로 이 가장 적절하다.', 1),
('4434b8fe-bb9d-4d55-85f7-5cd3529169fd', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 2, '무관한문장', '글의흐름', true, '4', 'Arias가 Picasso에게 받은 작품들을 고향에 기증하 여 미술관이 설립되었고, 그 작품들이 두 사람의 우정 을 상징한다는 것이 글의 중심 내용이다. Arias는 상인 의 유혹에도 작품을 팔지 않고 모두 기증했으므로, 일 부 작품이 기증 전 개인 수집가들에게 고가에 팔렸다는 의 내용은 글의 맥락과 일치하지 않으며 흐름을 방해 한다.', 1),
('ef978b1b-36f9-4cdd-8096-c927c24e9baf', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 3, '어법', '문법/어휘', true, '2', 'ⓑ 문장의 술어 동사가 필요한 자리인데 현재분사 형 태인 giving이 쓰였으므로, 과거 시제에 맞춰 gave로 고쳐야 한다. ⓐ 머리를 자르기 위해 ⓒ 더 강해진 ⓓ 어울리기 위해 ⓔ 내가 ~인.', 1),
('e376f442-06b4-42a6-87da-4643874f9b6f', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 4, '제목요지', '주제파악', true, '4', '이발사와 화가 모두 자신의 작업물에서 실수를 발견 한다는 공통된 인식을 통해 Picasso가 Arias를 예술가 로 인정하는 내용이므로 정답은 ‘예술가를 식별하 기: 불완전함에 대한 공유된 의식’이다. 창의적 과정 의 차이: 예술 대 이발 세계적으로 유명한 인물을 위해 일하는 것의 정서적 보상 수작업에서 기술적 완벽함을 달성하는 것의 어려움 유명 예술가들이 평 범한 전문가들로부터 인정을 구하는 이유', 1),
('8d151a42-17ea-4166-ab8a-6107ab716b8e', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 5, '제목요지', '주제파악', true, '2', 'Arias는 이발을 끝낸 뒤 자신의 실수를 본다고 말했 고, Picasso도 그림을 끝낼 때마다 실수를 본다고 말한 다. Picasso는 이러한 태도를 예술가의 특징으로 인정 하며 Arias를 “artist”라고 부른다. 따라서 이 글의 주 제는 완벽함이 아니라 자신의 작업 속 부족함을 인식하 는 진정한 예술적 태도이다. 외부 평가를 의도적으 로 피하는 것 개인적 관계에 대한 정서적 의존 창의적 상상력에 대한 직업적 우월성 기계적 정확성 을 통한 기술적 성취', 1),
('64e381d5-bd19-498d-9029-5f3c79575e0d', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 6, '문장삽입', '글의흐름', true, '2', '다른 손님들이 Picasso를 먼저 배려해준 상황을 설 명한 후, Picasso가 느낀 불편함을 설명하고 그에 따라 Arias가 해결책을 제시하는 구조가 자연스러우므로 가 적절하다.', 1),
('441a019f-83cb-4a19-8ea0-556496491b99', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 7, '내용추론', '독해/사실확인', true, '2', 'Picasso가 Arias에게 깊은 인상을 받으며 긍정적인 첫 만남을 마쳤으므로, 이후에는 이 만남이 어떻게 반 복적인 방문과 지속적인 유대로 이어졌는지를 보여주는 내용이 오는 것이 적절하다. 따라서 정답은 ‘Picasso의 첫인상이 어떻게 반복되는 유대로 이어졌는 지에 대한 묘사’이다. Picasso는 오히려 감명 받았 으므로 부정적 반응은 틀렸으며, , , 는 핵심 흐 름인 우정의 발전과는 다소 거리가 있다.', 1),
('623a1e5f-3b9a-4101-9eec-a267fdd0d205', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 8, '내용일치', '독해/사실확인', true, '3', '피카소는 박물관이 완공되는 것을 보지 못하고 1973 년에 사망했다고 서술되어 있으므로 글의 내용과 일치 하지 않는 것은 이다.', 1),
('16d8a801-23b7-4823-abce-ade2e13a45e0', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 9, '어법', '문법/어휘', true, '3', '(A) ''전시하기 위해''라는 목적을 나타내는 to부정사의 부사적 용법이므로 to display가 적절하다. (B) 감정의 원인을 나타내는 to부정사 표현이므로 to hear가 적절 하다. (C) 지각동사 see의 목적어인 the museum이 '' 완성되는'' 수동의 관계이므로 과거분사 completed가 와야 한다.', 1),
('bafdd301-a9fc-4c6d-8b2c-a4445f5c0e5f', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 10, '빈칸추론', '논리/추론', true, '1', '신체적 제약으로 세상과 고립된 부유한 Philippe와 자유로운 영혼의 가난한 Driss가 만나 편견 없이 서로 를 알아가며 진한 우정을 쌓는 영화 ''Untouchable''에 관한 내용이다. 따라서 빈칸에 들어갈 말로 가장 적절 한 것은 ''친구들이 서로를 어떻게 받아들이는지''이 다. 친구들이 어떻게 그들의 과거를 무시하는지 친구들이 서로를 어떻게 변화시키는지 친구들이 외 모로 어떻게 판단하는지 친구들이 성공을 위해 어떻 게 경쟁하는지', 1),
('20efd17d-e550-4193-8b8b-b6cc67c17c8d', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 11, '어휘', '문법/어휘', true, '4', 'Gunner가 Delta에게 처음부터 흥미를 느꼈다는 문 맥이므로, ''지루해했다''는 뜻의 ⓓ bored는 적절하지 않다. ''매료되었다'' 혹은 ''흥미를 느꼈다''는 의미인 intrigued 등으로 바꾸어야 한다. ⓐ bloomed는 ''피어 났다'', ⓑ encounter는 ''만남'', ⓒ fascinated는 ''매료 된'', ⓔ politely는 ''공손하게''라는 의미이다.', 1),
('217a3209-8777-48f7-9c3d-e28a1b28bd94', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 12, '대화문', '화용/의사소통', true, '5', '스터디 그룹의 도움에 감사를 표하며 시험 결과에 대 해 긍정적인 반응을 보이는 상황이므로 시험을 아주 잘 보았다는 내용이 적절하다. 따라서 빈칸에 들어갈 말로 가장 적절한 것은 ‘유난히 잘해냈다’이다. 비참 하게 낙제했다 약간 고전했다 겨우 합격했다 간신히 만족했다', 1),
('c1fbe7a0-d919-4e08-adcf-969dcfeb457f', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 13, '내용일치', '독해/사실확인', true, '1', '자신의 머리카락이나 손톱을 소유한 사람이 자신을 통제할 것이라는 미신적인 믿음 때문에 스스로 머리를 잘랐다는 내용이 있으므로 답할 수 있는 질문은 ‘어 떤 심리적 요인이 피카소로 하여금 정기적으로 스스로 이발을 관리하게 강제했는가?’이다. ‘피카소는 떠나 기로 결정하기 전에 파리에서 몇 년 동안 거주했는가?’ ‘두 남자는 그들의 짧은 첫 대화 동안 어떤 구체적 인 주제들을 논의했는가?’ ‘아리아스는 피카소에게 그의 첫 이발 서비스 대금으로 얼마의 돈을 요구했는 가?’ ‘아리아스는 전문 이발사가 되기 위한 정식 교 육을 어디에서 받았는가?’', 1),
('8463c90a-52e2-4e22-b090-26f7fa59c798', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 14, '내용일치', '독해/사실확인', true, '4', '본문에서 ''호기심 많은 군중이 차 주변으로 모여들었 다(A curious crowd gathered around the car)''고 했으므로 관심이 없었다는 는 일치하지 않는다. Vallauris라는 마을이며, 검은 리무진이 있었고, 저녁 식사에 늦을까 봐 걱정했고, Arias에게 빨리 나오라고 소리쳤다.', 1),
('92fdbeca-5721-4078-ac82-c60eae230deb', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 15, '내용추론', '독해/사실확인', true, '4', 'Tom은 Hannah에게 밥부터 먹으라고 조언하며 자신 의 샌드위치를 나눠주는 등 Hannah의 건강을 우선시 하고 있으므로 는 추론 가능한 내용이다. 반면 Hannah가 고마워하며 친절에 감사하고 있으므로 관심 이 없다고 보기 어렵고, Tom의 숙제에 대한 언급 은 없으며, Hannah는 친절에 감사해하고 있고, Hannah의 불안은 신체적 능력 부족이 아니라 많은 숙 제 때문이므로 나머지는 모두 추론할 수 없거나 사실과 다르다. 이 중 Tom의 행동을 통해 확실히 알 수 있는 것은 이다.', 1),
('733acd52-df38-481d-871f-d646f35fb1ed', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 16, '어법', '문법/어휘', true, '3', 'ⓒ 주절의 동사가 과거(responded)이므로 시제 일치 원칙에 따라 종속절의 조동사 will을 과거형인 would로 고쳐야 한다. ‘쇠퇴했다’는 의미의 동사로 적절하다 미래시제의 의문문으로 어순이 적절하다 감정의 원인을 나타내는 to부정사로 적절하다 결과를 나타 내는 to부정사 부사적 용법으로 적절하다', 1),
('c461b9d1-be7f-4794-99e8-e96add4d3e1e', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 17, '내용일치', '독해/사실확인', true, '5', '피카소가 아리아스에게 자네가 여기 있을 때면 고향 스페인에 돌아온 것 같은 기분이 든다고 직접 말한 내 용이 있으므로 내용과 일치하는 것은 ‘피카소는 아 리아스가 그의 집에 있을 때 스페인에 돌아온 것 같은 기분이 들었다’이다. 아리아스는 피카소의 집이 너 무 멀어서 방문하기를 거부했다. 피카소는 그의 스 케치 대금으로 아리아스에게 많은 액수의 돈을 청구했 다. 아리아스는 그들의 첫 말다툼 이후 피카소를 방 문하는 것을 중단했다. 아리아스는 피카소의 면도를 해 주어야 할 때만 그의 집에 들렀다.', 1),
('a8875ac4-3ba1-4050-a1eb-2df1759a7e22', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 18, '어법', '문법/어휘', true, '3', '의 if는 ''만약 ~라면''이라는 뜻의 조건의 부사절 접 속사이고, 나머지는 모두 ''~인지 아닌지''라는 뜻의 명사 절 접속사이다. 당신이 저녁 식사에 오는지 알고 싶 다 이 근처에 약국이 있는지 아시나요 만약 내 일 비가 오면, 경기는 취소될 것이다 그녀는 나에게 짐을 도와줄 수 있는지 물었다 우리는 기차가 10시 에 떠나는지 11시에 떠나는지 확실하지 않다.', 1),
('6ddccd94-9db4-488d-8e0e-6aba785da19e', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 19, '어휘', '문법/어휘', true, '4', '개가 돌고래의 움직임에 흥미를 느끼는 상황이므로 ⓓ의 bored(지루해하는)는 intrigued(흥미를 느끼는)와 같은 의미의 단어로 바뀌어야 한다. ⓐ bloomed(피어 났다) ⓑ extraordinary(놀라운) ⓒ fascinated(매료된) ⓔ friendly(친근한)', 1),
('664d8117-7a79-46f8-8d40-6cf8755832ef', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 20, '무관한문장', '글의흐름', true, '3', '이 글은 개와 돌고래가 서로 교감하며 쌓아가는 우정 에 대한 내용이다. 은 야생 동물의 본능인 고독한 사 냥에 대한 설명으로, 개와 돌고래의 친밀한 우정이라는 글의 흐름과는 관계가 없다.', 1),
('0a0a933e-521e-4a51-81bf-84a66d371128', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 21, '제목요지', '주제파악', true, '2', 'Arias가 기증한 작품들로 세워진 이 박물관이 Picasso와 그의 우정을 보여주는 기념비적인 장소임을 설명하고 있으므로 정답은 ‘깊은 유대의 물리적 현 시로서의 박물관’이다. Picasso의 소품들에 나타나 는 기법적 차이점 스페인 지방 자치 지역 내 예술품 기부의 역사적 배경 예술품의 개인 소유권과 공공 전시 사이의 갈등 세계적 명작의 진품 인증에 있어 명문의 역할', 1),
('446cc94b-b809-4f56-a9f3-8605464dd6c0', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 22, '내용추론', '독해/사실확인', true, '2', 'Arias가 Picasso의 작업을 돕고 Picasso가 그에 대 해 농담을 던지는 훈훈하고 협력적인 장면이므로 글의 분위기는 ''장난스럽고 지지해주는''이다. 엄숙하 고 긴장된 지루하고 반복적인 혼란스럽고 당혹 스러운 경쟁적이고 질투하는', 1),
('b9b3acf5-14dc-4a11-a246-374bb1c94e7b', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 23, '어법', '문법/어휘', true, '1', 'ⓐ ''...한 이래로''라는 뜻의 접속사 since는 현재완료 시제와 함께 쓰여 어법상 적절하다. ⓑ ''어떻게 지내고 있니?''라는 의미의 진행형 표현으로 적절하다. ⓒ 의문 문이므로 ''do you miss''로 고쳐야 한다. ⓓ 라자냐를 '' 만들었다''는 능동의 의미가 되어야 하므로 ''made''로 고쳐야 한다. ⓔ 이탈리아 요리사에 의해 ''운영되는''이 라는 수동의 의미로 명사를 수식해야 하므로 ''run''으로 고쳐야 한다.', 1),
('6bf78fb0-e78a-4a12-89db-cde24e727529', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 24, '내용일치', '독해/사실확인', true, '4', 'Arias는 어떤 돈을 가져와도 팔지 않겠다고 했으므로 ‘Arias는 제안이 충분히 높다면 가격을 협상할 의향 이 있었다’는 지문의 내용과 일치하지 않는다. 전시 회의 규모는 국제적인 인기를 방해하지 않았다 Arias의 고국 복귀는 전시회를 위한 전제 조건이었다 작품을 획득하려는 상인의 시도는 성공하지 못했다 Arias는 제안이 충분히 높다면 가격을 협상할 의향 이 있었다 Picasso의 작품은 Arias와 전 세계 대중 사이의 가교 역할을 했다는 모두 지문의 내용과 일치한 다.', 1),
('537d88f9-12fd-4560-a70c-6bff63b6c7c7', '88d393f0-f69d-43f0-9591-1b7bfcafec3d', 25, '내용추론', '독해/사실확인', true, '1', 'Picasso가 그의 예술을 통해 계속 살아갈 것임을 알 며 위안을 얻었다는 대목과 막대한 돈을 거절한 것을 통해, Arias가 예술품을 단순한 자산이 아닌 친구의 살 아있는 존재의 연장선으로 보았음을 추론할 수 있다. 전시는 세계적 관심을 끌었으므로 성공적이었고, 상인이 정부 대표라는 근거는 없으며, 가격 상승을 노린 것이 아니라 우정의 가치를 지키려 한 것이며, 유언장에 외국인에게 팔지 말라고 했다는 내용도 없다.', 1),
('802dde80-9f9c-4e65-8be2-dff1ae1ec941', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 26, '어법', '문법/어휘', true, '5', 'ⓔ 뒤에 완전한 문장(Picasso was twenty-eight years older than Arias)이 이어지고 있으며, 앞의 the fact와 동격의 관계를 이루어야 하므로 관계대명사 which를 접속사 that으로 고쳐야 한다. ⓐ 주차되었다 ⓑ 소리쳤다 ⓒ 궁금해 하며 ⓓ 나타났다.', 1),
('3b964798-3e41-424d-a13f-274914aa1778', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 27, '어법', '문법/어휘', true, '2', 'refuse는 목적어로 to부정사를 취하는 동사이며, 동 명사는 올 수 없다 ⓐ 설득하려고 시도했다 ⓒ 나 ⓓ ~ 였다 ⓔ 기부했다.', 1),
('42186f1f-6818-4333-b2d1-c1c613191e66', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 28, '빈칸추론', '논리/추론', true, '1', '고향인 스페인을 그리워했으므로 (A)에는 nostalgia (향수)가 적절하며, 머리카락을 통해 조종당할까 봐 이 발소 방문을 꺼렸으므로 (B)에는 fear(두려움) 또는 미 신에 근거한 불안함이 와야 한다. 정답은 이다.', 1),
('5d85230f-47a9-4d42-b447-744309186c8b', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 29, '내용일치', '독해/사실확인', true, '3', '본문에서 Picasso가 며칠 동안 밤을 새우며 열심히 일하고 있었다(staying up at night for days)고 했으 므로, 충분한 잠을 잤다는 은 내용과 일치하지 않는 다. Picasso는 ''전쟁과 평화''라는 프로젝트를 작업 중이었고, Arias는 Picasso가 바쁠 때 방문했으며, 사다리를 옮기고 인물을 그리는 등 Arias가 Picasso를 도왔고, Picasso는 서명에 Arias의 이름 을 추가하는 농담을 했다.', 1),
('a6467d00-3b0b-42cb-845c-2eeb58322b59', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 30, '어법', '문법/어휘', true, '3', 'ⓒ ''...하기를 간절히 원하다''라는 뜻의 ''be eager to'' 구문에서 to는 to부정사의 to이므로 meeting을 동 사원형인 meet으로 고쳐야 한다. ⓐ 너무 미신적이라 서 ~할 수 없는 ⓑ 자르기로 선택했다 ⓓ 대우했다 ⓔ 안내하며.', 1),
('5cde9e84-a0a6-4134-a0b0-a4d30e57cc9e', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 31, '영작', '쓰기', false, 'age gap', '원문은 Despite the fact that Picasso was twenty-eight years older than Arias (피카소가 아 리아스보다 28살 더 많았다는 사실에도 불구하고) 라는 의미이다. 이를 ‘Despite + 명사구’ 형태로 바꾸면 Despite their age gap of twenty-eight years 가 된 다. age gap: 나이 차이라는 뜻이다.', 1),
('9e326ead-2b79-4cb7-8fb7-fa67da3126c2', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 32, '내용추론', '독해/사실확인', true, '2', '개와 돌고래가 함께 놀며 즐거움과 동료애를 나누는 모습을 묘사하고 있으므로 정답은 ‘마음이 따뜻해지 고 즐거운(heartwarming and joyful)’이다. 엄숙하 고 의식적인 단조롭고 반복적인 신비롭고 긴장 감 넘치는 경쟁적이고 공격적인', 1),
('ac562885-6e7f-4477-a38c-1d5449d677f5', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 33, '내용추론', '독해/사실확인', true, '4', '전설적인 예술가와 평범한 이발사라는 사회적 지위와 명성 차이, 그리고 28세라는 상당한 나이 차이에도 불 구하고 20년 지기였다는 점을 통해 그들의 우정이 이례 적임을 추론할 수 있다. 글을 통해 Picasso의 사회 적 지위가 주민들보다 높았던 걸 알 수 있으며, Arias는 유쾌한 미소를 가진 사람이었지 오만하지 않았 고, 군중은 Picasso를 기다리게 하는 사람에게 놀란 것이며, 그들은 Vallauris에서 만났다.', 1),
('d19ee3cd-aa4e-4e7b-bd09-4828e632b7c4', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 34, '어법', '문법/어휘', true, '3', 'ⓒ 과거 시점인 Arias의 방문 이전부터 며칠 동안 작 업을 해왔던 과거의 상태를 나타내야 하므로, 현재완료 진행형인 has been working을 과거완료 진행형인 had been working으로 고쳐야 한다. ⓐ 그리느라 바 쁜 ⓑ 프로젝트들 ⓓ 이것을 보고 ⓔ 옮기는 것에서.', 1),
('e146ee68-a2b7-4335-b1ec-a29772f4e1aa', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 35, '제목요지', '주제파악', true, '2', '나이 차이가 많이 나는 두 사람이 우정을 쌓게 된 배 경과 과정을 소개하고 있으므로 정답은 ‘격차를 좁 히기: 세대를 초월한 우정’이다. 왜 Picasso가 파리 에서의 경력을 포기했는가 1947년 스페인 예술가들 의 전략적 재배치 타국에서의 문화적 소외에 대처하 는 방법 거장과 견습생 사이의 세대 갈등은 지문의 핵심에서 벗어난 제목들이다.', 1),
('3044cc40-ce20-41db-8c1e-492881d53441', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 36, '어휘', '문법/어휘', true, '1', '밑줄 친 ㉮의 eager는 뒤에 to부정사를 수반하여 ''~ 를 간절히 바라는, 열망하는''이라는 뜻으로 쓰였다. 이 와 같은 뜻으로 바꾸어 쓸 수 있는 단어로 가장 알맞은 것은 ''갈망하는''이다. 보통의 격식 없는 망설이는 무관심한', 1),
('791430b6-5f80-4d09-841b-514bd0c2514b', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 37, '내용추론', '독해/사실확인', true, '4', 'Keller와 Bell이 처음 만났을 때 각각 6세와 40세였 음에도 불구하고 나이 차이를 극복하고 좋은 친구가 되 어 생각을 나누었다는 내용을 통해 를 추론할 수 있 다. Bell이 Keller를 학교에 소개해 주었으며, 이 탈리아로 떠났다는 내용은 없고, Helen Keller와 Bell은 독특한 우정을 나누었다고 언급되었으며, Bell이 Keller보다 나이가 훨씬 많았다.', 1),
('52f1f9db-2579-4a21-aefd-ad0b9535ea82', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 38, '문장삽입', '글의흐름', true, '5', '주어진 문장은 두 사람의 나이 차이와 우정의 기간을 설명하는 내용으로, 두 사람이 리무진을 타고 떠나는 장면 직후에 그들의 관계가 얼마나 오래되었는지를 부 연 설명하는 위치인 가 가장 적절하다. 이후 세대를 초월한 그들의 우정이 시작된 시점으로 이어지는 문장 이 나오므로 정답은 이다.', 1),
('334b0f7c-87ca-4125-906a-83b03d078b2e', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 39, '내용일치', '독해/사실확인', true, '5', '본문 마지막 부분에서 그들의 상호작용이 신체적 능 력의 장벽을 깨뜨렸다(breaking the barriers of their different physical abilities)고 했으므로 어려움을 겪 었다는 는 내용과 일치하지 않는다. 함께 게임을 즐겼고, 물방울을 뒤쫓았으며, 즐겁게 하기 위해 도약을 했고, 조화로운 모습이었다.', 1),
('474a6007-b0da-442e-9b66-a2b1ef3a526f', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 40, '내용추론', '독해/사실확인', true, '3', '개가 돌고래의 물보라를 쫓고 돌고래는 개를 위해 뛰 어오르는 등 서로 즐거운 놀이 게임을 주고받는 상황을 묘사하고 있으므로, 밑줄 친 부분은 친밀감을 바탕으로 한 상호적인 놀이 활동을 의미한다. 따라서 정답은 ‘친밀감을 바탕으로 한 놀이 행동의 상호 교환’이다. 신체적 우월함을 증명하기 위한 경쟁적인 경기 센터 의 관객들을 위해 대본에 짜인 공연 신체적 불편함 을 초래한 우연한 만남 익숙하지 않은 수중 환경에 적응하기 위한 고군분투.', 1),
('dadd6b81-4b1c-4453-a52b-98d653dd4850', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 41, '제목요지', '주제파악', true, '3', 'Arias가 Picasso의 작품을 우정의 상징으로 여겨 막 대한 돈을 제안 받아도 팔지 않겠다고 거절하는 내용이 므로 주제로 가장 적절한 것은 ''개인적인 우정을 돈 과 바꾸는 것에 대한 거절''이다. Picasso 작품의 높 은 시장 가치 외국 예술 상인들의 끈질긴 설득 외국에서 예술을 보존하는 것의 어려움 예술 시장에 서 협상 기술의 중요성', 1),
('6854538c-0e5d-4fa3-962f-b4fe992e2a3c', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 42, '빈칸추론', '논리/추론', true, '1', '(A)는 Picasso가 Arias를 돕기로 맹세했지만 불행히 도 박물관 완공을 보지 못하고 사망했다는 상반된 내용 을 연결하므로 But(하지만)이 적절하다. (B)는 외국 상 인이 작품을 팔라고 설득했음에도 불구하고 거절했다는 내용이므로 Yet(하지만)이 문맥에 맞며, (C)는 박물관 완공이 가능했던 이유가 Arias의 작품 기증 때문이므로 인과관계를 나타내는 because(~때문에)가 적절하다. 따 라서 빈칸에 들어갈 말로 가장 적절한 것은 ‘하지만 - 하지만 - ~때문에’이다.', 1),
('0a661daf-e7b7-40f0-ace9-e4c4dd9f5121', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 43, '내용추론', '독해/사실확인', true, '5', '부유하지만 휠체어에 의존해야 하는 Philippe이 세상 으로부터 고립되고 소외된 기분을 느끼고 있다는 맥락 을 통해, 밑줄 친 부분이 장애의 심리적 영향으로 인해 사회적으로 소외된 상태를 의미함을 추론할 수 있다. 따라서 밑줄 친 부분이 의미하는 바로 가장 적절한 것 은 ‘장애의 심리적 영향으로 인해 사회적으로 배제 된 기분을 느낌’이다. 신체적으로 자리에서 움직일 수 없음 법적으로 특정 구역 내에 머물러야 함 부가 제공하는 사치에 만족함을 느낌 새로운 사람들 을 만나는 것을 피하기 위해 고독한 삶을 선택함', 1),
('08fdc79c-79c5-4fd6-8c40-5b6de38dc2fc', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 44, '제목요지', '주제파악', true, '3', '아리아스는 피카소의 불편함을 덜어주기 위해 가정 방문 서비스를 제안하고 요금을 청구하지 않았으며, 피 카소는 예술품으로 화답하며 우정을 나누고 서로의 집 을 오갔다는 내용의 글이다. 따라서 글의 제목으로 가 장 적절한 것은 ‘요금은 없지만 순수한 기쁨으로 커 져가는 우정’이다. 스페인 요리의 역사 손님들과 이발사 사이의 갈등 피카소가 친구의 집 방문을 중 단한 이유 예술적 스케치를 통해 재산을 모으는 방 법', 1),
('08c0224d-896c-4cbb-86a1-deda1d98b644', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 45, '내용일치', '독해/사실확인', true, '1', '피카소가 아리아스에게 우정의 표시로 스케치, 그림, 도자기를 주었다고 했으므로 답할 수 있는 질문은 ‘피카소는 그의 친구에게 보답의 선물로 어떤 정확한 형태의 예술적 창작물을 제공했는가?’이다. ‘아리아 스가 가정 방문 서비스를 시작하기 전 그의 월수입은 얼마였는가?’ ‘두 남자는 그들의 저녁 식사 시간 동 안 보통 대화하는 데 몇 시간을 보냈는가?’ ‘아리아 스의 어머니는 전통 음식을 요리하기 위해 어떤 구체적 인 재료들을 활용했는가?’ ‘아리아스의 어머니는 스 페인 요리법을 언제 공식적으로 배웠는가?’', 1),
('ae9fb632-fc8b-410c-a177-227bcc1c8e19', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 46, '내용일치', '독해/사실확인', true, '5', '글에서 피카소가 이발소에 들어갔을 때 다른 손님들 이 대기하고 있었는지에 대한 정보는 언급되지 않으므 로 답할 수 없는 질문은 ‘그날 이발소에서 얼마나 많은 다른 손님들이 기다리고 있었는가?’이다. 피카 소는 몇 년도에 발로리스 마을로 이주했는가? 머리 카락과 손톱에 관한 피카소의 믿음은 무엇이었는가? 누가 피카소에게 아리아스라는 지역 이발사에 대해 알려주었는가? 아리아스는 피카소를 알아보고 어떻 게 대했는가?', 1),
('c68e4141-848b-43ea-bb33-79a559a2a71b', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 47, '어휘', '문법/어휘', true, '2', '글의 문맥상 빈칸 ⓑ에는 피카소가 아리아스의 제안 을 기쁘게 받아들였다는 의미의 accepted가 들어가야 하므로 ‘제공된 무언가를 받기를 거절하다’는 적절 하지 않다. ⓐ routine: 일을 하는 통상적이거나 고 정된 방식 ⓒ gesture: 특정 감정이나 의도를 보여 주기 위해 당신이 하는 무언가 ⓓ frequent: 자주 또는 반복적으로 일어나는 ⓔ dined: 식사를 했다.', 1),
('66261070-f63f-4af8-a46a-58765c2cd96e', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 48, '내용추론', '독해/사실확인', true, '2', '유명 예술가인 피카소를 평범한 고객처럼 대하면서도 스페인어로 따뜻하게 환대하고 직설적이면서도 소박하 게 이야기했다고 했으므로 아리아스가 피카소를 처음 맞이할 때의 태도로 가장 적절한 것은 ‘다정하고 가 식 없는’이다. ‘차가우며 초연한’ ‘비판적이고 까 다로운’ ‘회의적이고 의심 많은’ ‘오만하고 과도 하게 자랑스러워하는’', 1),
('82167c2b-3ce7-48a3-b5b4-22be3b550e13', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 49, '빈칸추론', '논리/추론', true, '5', '부유하고 신체적 제약이 있는 Philippe과 가난하고 자유로운 영혼인 Driss가 편견 없이 우정을 쌓아가는 과정을 통해 우정이 서로의 차이를 수용하는 것임을 보 여주는 글이다. 따라서 빈칸에 들어갈 말로 가장 적절 한 것은 ‘동반자들이 서로의 차이를 수용하는지’이 다. 친구들이 그들의 의무를 무시하는지 개인들 이 성공을 위해 경쟁하는지 사람들이 사회적 관습을 따르는지 사람들이 재정적 독립을 추구하는지', 1),
('2c51ee8f-86c9-497a-8cb8-0529a892aa8b', '2dc73e83-0930-47b9-bd2d-84cf7d7ca2a1', 50, '글의순서', '글의흐름', true, '2', '주어진 글에서 부유하지만 휠체어에 갇혀 소외감을 느끼는 Philippe을 소개하고 있으므로, ‘반면에’라는 뜻 의 On the other hand를 사용해 대조적인 처지의 Driss를 소개하는 (B)가 뒤에 오는 것이 적절하다. 이 후 Philippe이 Driss를 고용하며 편견 없는 우정을 쌓 는 과정인 (A)가 이어지고, 마지막으로 두 사람이 함께 인생의 교훈을 얻는다는 결론적 내용인 (C)로 마무리하 는 것이 논리적인 흐름이다. 따라서 주어진 글 다음에 이어질 글의 순서로 가장 적절한 것은 이다.', 1),
('55d76aa2-18e0-4f0c-8291-4447a5e732f6', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 1, '내용추론', '독해/사실확인', true, '1', '창의적 인지 수행이 고정된 것이 아니라 신체 움 직임을 통해 향상될 수 있다는 점이 본문의 핵심이다. 실험 대상이 오직 학생뿐이었다는 정보는 없으며, 16분 이상 걸을 때 창의력이 감소한다는 데이터도 제시되지 않았고, 본문은 오히려 움직일 때 학습과 기억 부위가 효율적이라고 했으며, 창의적 아이디어 가 ''탈진'' 상태에서 잘 나온다는 근거도 없다.', 1),
('07e22d86-fe31-4fc9-af13-baa75449dfc0', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 2, '제목요지', '주제파악', true, '1', '글의 초반부에서 걸음 수 목표를 정하고 노력하라고 권유하며, 일상생활 속에서 걷기 챌린지에 참여할 수 있는 구체적인 방법들을 제시하고 있으므로 글의 목적 으로 가장 적절한 것은 이다.', 1),
('3acda190-c55c-461e-85e9-0ef8e06d8e30', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 3, '내용일치', '독해/사실확인', true, '4', '지문 후반부에 수록된 정보를 검토하면, 상대방과의 흥미진진한 소통 시퀀스에 정서적으로 크게 몰입하여 휩쓸리다 보면 보행자가 당일 가로질러 주파해 온 물리 적 척도나 거리를 인지적으로 뚜렷하게 실감하지 못하 게 된다고 서술했으므로 는 본문과 맞지 않아 불일치 항이다.', 1),
('c73af168-e491-4dac-a200-c0a56ee36855', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 4, '제목요지', '주제파악', true, '3', '스탠퍼드 대학교의 정량적 연구 데이터와 애플의 스 티브 잡스가 고안해 낸 혁신적 아이디어 사례를 들어, 걷는 행동이 학습과 기억을 담당하는 뇌 영역의 대사 효율을 향상시켜 창의력을 비약적으로 발달시킨다는 것 을 밝히는 글이다. 따라서 글의 주제로 가장 적절한 것 은 ‘걷기가 창의력에 미치는 긍정적 효과’이다. 스탠퍼드 대학교의 역사 스티브 잡스와 그의 경영 스타일 학습 및 기억 테스트의 중요성 효율적인 사무실 좌석 공간을 디자인하는 방법', 1),
('5fed8ff4-2922-4873-afbf-7c56b3bf7377', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 5, '빈칸추론', '논리/추론', true, '4', '걷기가 창의력을 높여주는 이유를 설명하는 문장으 로, 걷는 동안 인지 기능과 관련된 특정 뇌 부위가 더 효율적으로 작동한다는 내용이 와야 한다. 창의적 아이 디어 도출의 기반이 되는 ‘학습과 기억’이 빈칸에 가장 적합하다.', 1),
('f34acf7c-5866-40c3-ac8a-fe634ac81226', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 6, '문장삽입', '글의흐름', true, '3', '주어진 문장은 빈번한 신체 활동이 뇌 기능을 향상시 켜 초콜릿과 같은 단 음식의 섭취를 제한하는 것을 더 쉽게 만든다는 이유를 설명하고 있다. 번 문장에서는 매일 15분간 걷는 것이 초콜릿 소비량을 절반으로 줄일 수 있다는 엑서터 대학교의 연구 결과를 제시했으므로, 그 결과에 대한 과학적 근거를 설명하는 주어진 문장은 번에 위치하는 것이 논리적이다. 그 뒤인 번 다음 부터는 질병 예방과 관련된 새로운 이점으로 화제가 전 환된다.', 1),
('63c65a2b-a4fb-4a60-94eb-18f571dcb1c2', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 7, '어법', '문법/어휘', true, '2', '(b) 부정어 Little에 의한 도치가 올바른 문장이다. (e) Not until절에 의한 도치가 올바른 문장이다. (a) in case 절은 현재 시제를 써야 하므로 runs로, (c) Rarely는 Rarely does the manager visit으로, (d) Under no circumstances는 should the lab equipment be used로 고쳐야 한다. 옳은 문장은 2개 이다.', 1),
('14ecc716-f169-45dd-bd01-958a7f9942dd', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 8, '문장삽입', '글의흐름', true, '3', '주어진 문장은 신체가 휴식을 필요로 하듯이 정신 또 한 웰빙을 위해 휴식해야 한다는 비유를 통해 뇌 휴식 의 필요성을 주장하고 있다. 번 뒤에서 건강하지 않 은 뇌가 삶을 방해할 수 있다는 점을 언급한 뒤, 에 이 문장이 오면 자연스럽게 ''멍 때리기(spacing out)'' 를 통한 뇌의 휴식 방법으로 내용이 이어지기에 가장 적절하다.', 1),
('84355e3a-e569-41a2-bda1-1c666e0a33cc', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 9, '빈칸추론', '논리/추론', true, '2', '스티브 잡스의 사례로 언급된 ''walking meetings''를 의미하는 ''이동 중에 개최된 회의''가 정답이다.', 1),
('2f24a4e8-0b03-4e00-9d2d-7892fc74410f', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 10, '제목요지', '주제파악', true, '2', '고유의 모바일 앱 기기를 활용하여 보행 단계를 꾸준 히 모니터링하고, 일상의 작은 주기(계단 오르기나 양 치 중 움직임)를 흥미로운 걸음 수 채우기 임무로 치환 하여 보람과 흥미를 다방면으로 유도하는 기법을 전하 는 내용의 글이다. 따라서 글의 제목으로 가장 적절한 것은 ‘당신의 일상을 걷기 챌린지로 바꾸어라!’이다. 음식 섭취를 추적하는 최고의 앱 왜 사람들은 건강 목표 달성에 실패하는가? 소셜 미디어: 공부 팁을 공유하기 좋은 장소 엘리베이터 대 계단: 당신 에게 어느 것이 더 안전한가?', 1),
('a05319eb-79df-4ede-a1ec-9df09f6efe3d', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 11, '문장삽입', '글의흐름', true, '3', '주어진 문장은 걷기 도전을 위해 별도의 시간을 낼 필요 없이 점심시간이나 계단 이용, 양치질 중 제자리 걷기 등을 통해 참여할 수 있다는 구체적인 예시를 보 여준다. 번 뒤의 문장에서 ''이 걷기 도전을 위해 시 간을 따로 낼 필요가 없다''고 언급했으므로, 그에 대한 부연 설명이자 구체적인 실천 사례를 나열하는 주어진 문장은 번에 들어가는 것이 가장 적절하다.', 1),
('df6591d0-3eed-4bd0-ac2e-66fba7b16933', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 12, '빈칸추론', '논리/추론', true, '2', '멍 때리는 동안 뇌 활동이 완전히 멈추는 것이 아니 라 특정 부위가 활성화되어 정보를 정리하고 뇌 기능을 회복시킨다는 내용이다. 이는 본문의 ''reset''과 같은 의 미인 ''재조정(재설정) 과정을 거치다''와 일맥상통한 다.', 1),
('52610b78-ef29-4a94-8702-c28ab3a957f7', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 13, '내용추론', '독해/사실확인', true, '1', '신체적 이점(면역력)에 대한 설명을 마친 뒤 창의 성과 관련된 정신적/인지적 이점으로 주제를 전환하는 것이 걷기의 다각적 혜택을 다루는 글에서 논리적이다. 영양제, 선천적 면역, 식단 준비, 민간요 법 가이드는 걷기를 중심으로 한 글의 전개와 맞지 않 는다.', 1),
('2bda0d1a-f324-4c4f-9d93-ccc60efcf192', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 14, '내용일치', '독해/사실확인', true, '3', '본문 중반부 진술을 보면 소정의 시간인 약 5분 내지 16분가량을 의도적으로 움직여 걸었던 대상자들이 미동 없이 앉아 보낸 집단에 견주어 약 60% 수준의 창의력 향상 추이를 나타냈다고 했으므로 정확한 내용은 이 다.', 1),
('42eb8fe6-d3e3-4034-93a4-766bdb4cf4c6', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 15, '어법', '문법/어휘', true, '2', '부정어 Never before를 강조하기 위해 문두로 보내 면 [have + 주어 + p.p.] 어순으로 도치된다. 따라서 Never before have I witnessed...가 정답이다.', 1),
('019e04bf-6dca-45fe-a0c6-bc2d91087c0c', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 16, '내용일치', '독해/사실확인', true, '4', '본문 네 번째 줄 진술에 따르면 동료와의 흥미로운 대화 주제와 흐름에 무척 빠져들고 몰입한 나머지, 본 인이 정작 도보로 도달한 구체적인 총 이동 거리를 제 대로 실감하거나 도중에 지각하지 못할 정도(will not even realize how far you have walked)라 했으므로 는 인과와 사실이 비틀어져 정답이다. 걷기 친구 는 당신이 지루함을 느낄 때 운동할 동기를 제공할 수 있다. 당신은 친구를 실망시키고 싶지 않기 때문에 걷기 계획을 지킬 가능성이 더 높다. 대화에 참여하 는 것은 당신이 실제로 운동하고 있다는 사실을 잊게 만들 수 있다. 친구와 함께 걷는 것은 당신이 주변 환경의 아름다움을 함께 나눌 수 있게 해준다.', 1),
('36b4a977-f695-4e6d-8870-59aace3c36ec', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 17, '내용추론', '독해/사실확인', true, '2', '지문 마지막에 걷기가 의자병을 퇴치하는 가장 안전 하고 저렴한 운동 중 하나라고 소개했으므로, 이어질 내용은 질병 예방을 넘어선 걷기의 구체적인 추가 효능 이나 건강상의 이점들이 오는 것이 가장 자연스럽다. 마라톤과의 상세 비교 용어의 역사적 유래 우울증 증가 통계 심장병 치료 장비 선택법은 글의 전개상 우선순위에서 밀린다.', 1),
('3824bd83-cfb3-4859-bfc8-3bbd4fd87624', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 18, '대화문', '화용/의사소통', true, '2', '밤늦게 음식을 먹는 것이 소화 불량을 일으키고 건강 에 좋지 않다는 이유로 야식을 피할 것을 권하는 어머 니와 아들의 대화이다. 따라서 빈칸에 들어갈 말로 가 장 적절한 것은 ‘야간 취식을 삼가는 것’이다. 엄격한 식단을 유지하는 것 일일 섬유질 섭취량을 늘리는 것 소화하기 쉬운 음식을 섭취하는 것 규칙적으로 아침을 거르는 것을 피하는 것.', 1),
('ee985f3b-2b5f-4b46-a5c5-5ae7aa639e64', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 19, '무관한문장', '글의흐름', true, '4', '건강한 삶을 영위하기 위한 방법으로 숙면, 스트레스 대처, 균형 잡힌 식단, 신체 활동 등을 소개하는 글이 다. 월간 예산을 현명하게 관리하기 위해 시장의 식품 가격을 확인하는 것이 유익하다는 의 내용은 건강관 리라는 전체 흐름에서 벗어난다.', 1),
('84d848b9-1828-447a-9303-1bdadd5529a8', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 20, '빈칸추론', '논리/추론', true, '3', '뇌가 신체 움직임을 관리하므로 뇌가 건강하지 않으 면 몸 상태가 괜찮더라도 움직임에 지장이 생긴다는 맥 락이다. 본문의 ''hinder body movements''를 의미하 는 ''운동 과업의 수행을 방해하다''가 정답이다.', 1),
('57bedf71-9d53-44d3-9169-ce90045d5415', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 21, '영작', '쓰기', false, 'Energetic songs will motivate you to walk harder.', '수동태 문장에서 by 이하의 행위자를 주어로 바꾸고, 동사를 능동태로 전환한다. motivate는 목적격보어 자 리에 to부정사를 취하므로 Energetic songs will motivate you to walk harder.가 된다.', 1),
('e93402a9-1d1b-4a67-aeda-dc1ca168c2ef', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 22, '대화문', '화용/의사소통', true, '2', '밤늦게 음식을 먹으면 소화가 제대로 되지 않아 배탈 이 날 수 있다는 엄마의 설명을 듣고 아들이 설득되는 대화이므로, 빈칸에는 야식을 피하라는 내용이 적절하 다. 따라서 빈칸에 들어갈 말로 가장 적절한 것은 ‘야식을 피하는 것’이다. 매일 운동하는 것 가벼 운 간식을 먹는 것 충분한 물을 마시는 것 숙면 을 취하는 것.', 1),
('e99135de-6296-48c3-863d-e366a6053c8d', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 23, '내용추론', '독해/사실확인', true, '5', '지문의 마지막 문장에서 화자가 휴식 후에 걷기의 이 점과 그것이 건강에 미치는 영향을 이야기하겠다고 언 급했으므로 가 가장 적절하다. 다양한 종류의 영 양가 있는 견과류 수면의 질을 개선하는 방법들 스트레스를 관리하는 효과적인 방법들 만성 질환이 발생할 위험들 걷기가 건강에 미치는 긍정적인 영향 들', 1),
('37d958ce-e8c3-429f-9473-9c25a0821749', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 24, '빈칸추론', '논리/추론', true, '1', '(A) 앞부분에서는 이미 잘 알려진 걷기의 이점을 나 열하고, 빈칸 뒤에서는 잘 모를 수 있는 새로운 사실 (단 음식에 대한 갈망 감소)을 의문문 형식으로 제시하 며 화제를 전환하고 있으므로 역접의 접속사 But(또는 However)이 적절하다. (B) 앞뒤 문장은 모두 걷기의 이로운 점을 나열하고 있으므로 내용을 추가하는 연결 어 Moreover(또는 Furthermore, In addition)가 적 절하다. 따라서 정답은 ''하지만 - 게다가''이다.', 1),
('b1a40426-7eb2-4071-a300-cf081338c00f', '1f5f3990-c7f8-4118-87c4-353343f0dabf', 25, '무관한문장', '글의흐름', true, '4', '이 글은 걷기 친구와 함께 대화하며 걷는 것이 주는 심리적 동기 부여와 즐거움에 관해 설명하고 있다. 번 문장은 공공장소 에티켓에 관한 내용으로, 걷기 동 료와의 긍정적인 상호작용이라는 주제와 무관하다.', 1),
('b87e7a5c-3527-4ca3-a136-58ba66465400', '17cee299-a353-4023-b25f-2c26601c7ef8', 26, '내용추론', '독해/사실확인', true, '4', '지문에서 걷기가 단 음식에 대한 갈망을 낮추어 주 며, 15분간의 산책이 초콜릿 소비를 절반으로 줄일 수 있다고 언급하고 있다. 이는 단 음식의 섭취량을 줄인 다는 맥락이므로 정답은 ''설탕이 든 항목의 섭취를 상당히 줄이다''이다. 다른 사람들과 단 간식을 나누 어 먹다 설탕이 든 음식의 생산을 늘리다 매일 먹는 음식의 양을 두 배로 늘리다 초콜릿의 성분을 더 건강하게 바꾸다.', 1),
('b49f07aa-12dd-470b-8060-63210779eb99', '17cee299-a353-4023-b25f-2c26601c7ef8', 27, '제목요지', '주제파악', true, '2', '걷기가 제공하는 심혈관 기능 개선 및 뼈 강화라는 기본적 이점에 더하여, 단 음식에 대한 식욕 억제와 면 역 체계 강화 및 질병 예방 효과를 종합적으로 보여주 는 글이다. 따라서 글의 주제로 가장 적절한 것은 ‘식욕 조절 및 면역 향상을 포함한 걷기의 다방면의 신 체적 이점’이다. 겨울 동안 심혈관 문제를 진단하는 데 있어서의 임상적 도전들 청소년들의 고혈압과 설 탕 섭취 사이의 부적 상관관계 독감 및 면역 반응 연구의 역사적 발전 뇌 효율성을 증가시키기 위해 엑서터 대학교에 의해 제안된 식단 방법들', 1),
('b65eeb63-69ec-47a5-83e2-9b7ab1ebbc29', '17cee299-a353-4023-b25f-2c26601c7ef8', 28, '빈칸추론', '논리/추론', true, '2', '빈칸 앞에서는 특정 생각 없이 짧은 휴식을 취하면 특정 뇌 영역이 활성화된다고 하고, 빈칸 뒤에서는 이 시간 동안 뇌가 정보를 정리하며 더 나은 환경을 만든 다고 서술한다. 뇌가 균형을 회복하고 최적의 상태로 돌아갈 수 있게 한다는 가 이 흐름에 가장 자연스럽 게 이어진다. 장기 기억 유지를 지원하는 신경 연결 을 강화하면서 분석적 추론과 연결된 영역에 부과되 는 인지적 부하를 감소시키면서 지속적인 경계 수준 을 높이는 신경 화학 물질의 분비를 유발하면서 휴 식 동안 축적된 무관한 정보를 마음이 걸러내고 버리게 해 주면서', 1),
('9b485462-a90c-4e14-9e7e-1a9db4dcb7f9', '17cee299-a353-4023-b25f-2c26601c7ef8', 29, '빈칸추론', '논리/추론', true, '2', '견과류는 뇌 기능(brain function)과 전반적인 세포 건강을 돕고, 유제품은 뼈를 튼튼하게(strengthening bones) 하는 데 도움이 된다는 내용의 글이다. 따라서 요약문의 빈칸 (A), (B)에 들어갈 말로 가장 적절한 것 은 이다. 소화 - 에너지 신체적 성장 - 면역 체계 스트레스 감소 - 정신 건강 심혈관 건강 - 시력', 1),
('589eb8d5-3ed2-41a6-a193-65e9332960a4', '17cee299-a353-4023-b25f-2c26601c7ef8', 30, '내용추론', '독해/사실확인', true, '3', 'Dave는 처음에 빵을 먹고 싶어 했으나, 늦은 밤 음 식을 먹는 것이 소화 불량을 일으킬 수 있다는 어머니 의 설득을 받아들이고 다음 날 아침까지 기다리기로 했 으므로 이 적절한 추론이다. 대화 전에 소화 불량 을 겪었다는 언급은 없다. 처음에는 배고픔을 우선 시했으나 결국 조언을 받아들였다. 빵을 먹지 않기 로 결정했다. 냉동실에 넣겠다고 대답하며 대화가 끝났으므로 잊어버렸다고 추론할 수 없다.', 1),
('a12ed8b0-42d1-4376-8d27-2aac0270b3ef', '17cee299-a353-4023-b25f-2c26601c7ef8', 31, '내용일치', '독해/사실확인', true, '5', '지문 마지막에 걷기가 가장 저렴한(cheapest) 운동 형태 중 하나라고 했으므로, 가장 비싸다(most expensive)는 는 사실과 일치하지 않는다.', 1),
('81004919-398f-4ac3-b814-4534ac78aead', '17cee299-a353-4023-b25f-2c26601c7ef8', 32, '제목요지', '주제파악', true, '2', '학생들이 걷기를 실천하는 데 따르는 심리적, 시간적 장벽을 언급하고, 이를 극복하여 걷기를 즐거운 일상으 로 바꿀 수 있는 방법이 있음을 제시하는 글이다. 따라 서 제목으로 가장 적절한 것은 ‘장벽 극복하기: 걷 기를 즐거운 일상으로 바꾸기’이다.', 1),
('53947d16-22a4-4411-bae5-e5b98427b1f7', '17cee299-a353-4023-b25f-2c26601c7ef8', 33, '내용일치', '독해/사실확인', true, '2', '본문 두 번째 줄 내용을 확인하면 서로 신뢰하는 동 료 메이트와 일정 계획을 결합할 경우, 상대방의 기대 치에 실망감을 남기고 싶지 않은 배려심이 부가되어 최 종적인 도보 실행 확률과 실천도가 크게 증진된다고 명 기했으므로 내용과 어울리는 것은 이다.', 1),
('94601eed-30c1-4cf6-bd11-cb46356ff0fc', '17cee299-a353-4023-b25f-2c26601c7ef8', 34, '빈칸추론', '논리/추론', true, '4', '걷기의 건강상 이점으로 지문에 언급된 ''bone strengthening(뼈 강화)''을 의미하는 ''골격 구조 강 화''가 정답이다.', 1),
('e0e8a829-4476-47fd-8800-a42b98aa10e1', '17cee299-a353-4023-b25f-2c26601c7ef8', 35, '내용일치', '독해/사실확인', true, '2', '하단 단락 첫머리 진술을 찾아보면 소리 음원과 결합 해 산책 여정을 진행하는 훈련 방식인 ''음악 산책 (music walk)'' 기법이 신체 활동을 고된 단련이나 노 동인 것처럼 체감하지 않게 완화해 주는 탁월한 처방전 이 된다고 설명하므로 일치하는 서술은 이다.', 1),
('7a9c6ad0-1d8e-427f-b788-6546a9170bab', '17cee299-a353-4023-b25f-2c26601c7ef8', 36, '제목요지', '주제파악', true, '1', '스탠퍼드 대학교의 연구 결과와 스티브 잡스의 사례 를 통해 걷기가 뇌 기능을 효율적으로 만들어 창의성을 증진시킨다는 내용을 설명하고 있다. 따라서 글의 주제 로 가장 적절한 것은 ‘걷기와 창의적 사고 사이의 관계’이다. 사무직 노동자들에게 신체 건강의 중요 성 집중적인 학습을 통해 기억력을 향상하는 방법 스티브 잡스가 앉아서 하는 회의를 선호했던 이유 체내 혈류를 증가시키는 다양한 방법', 1),
('268bdf66-34e8-4753-a66a-d31a6c71ff50', '17cee299-a353-4023-b25f-2c26601c7ef8', 37, '어법', '문법/어휘', true, '4', 'ⓓ는 전치사 by에 걸리는 walking, taking과 병렬 구조를 이루어야 하므로 동사원형 walk를 동명사 walking으로 고쳐야 한다. To using은 어법상 불 가능한 형태이다. 주어 역할을 하는 동명사로 적절 하다. 수단을 나타내는 전치사구로 적절하다. ''get + 목적어 + to부정사'' 구조로 적절하다.', 1),
('a2a3818c-d1d9-4df0-87f6-3a27a18efde1', '17cee299-a353-4023-b25f-2c26601c7ef8', 38, '어법', '문법/어휘', true, '4', 'How about ~?'' 뒤에는 동명사가 와야 하므로 to space를 spacing으로 고쳐야 한다. 동명사 주어이 다. 단수 동사 일치이다. 분사구문이다. ⓔ 형용 사 수식 부사이다.', 1),
('27b4d1b8-b584-4fcb-9ef0-23e8c320eca2', '17cee299-a353-4023-b25f-2c26601c7ef8', 39, '어휘', '문법/어휘', true, '3', '이 글은 걷기의 인지적 이점에도 불구하고 학생들이 실생활에서 실천하기 어려워하는 상황을 설명하고 있 다. 걷기가 중요하지만 학생들에게 시간을 내는 것은 '' 어렵게(challenging / difficult)'' 보인다는 흐름이 적절 하므로, ⓒ의 easy(쉬운)는 challenging 혹은 difficult 로 고쳐야 한다.', 1),
('d40285ba-6e8e-4a8d-ac58-221823e56415', '17cee299-a353-4023-b25f-2c26601c7ef8', 40, '어법', '문법/어휘', true, '3', ', , , 의 Little은 ''거의 ~않다''라는 의미의 부정 부사로 문두에서 도치를 유발하고 있다. 반면 의 Little은 ''어린'' 또는 ''작은''이라는 의미의 형용사로 뒤의 명사 children을 수식하고 있으므로 쓰임이 다르 다.', 1),
('b56cd323-3b7a-40d4-83c9-677b94fa2b0c', '17cee299-a353-4023-b25f-2c26601c7ef8', 41, '어법', '문법/어휘', true, '1', '(A)는 ''It is no wonder that ~'' 관용 구문에서 접속 사 that이 적절하다. (B)는 명사구 앞이므로 전치사 during이 적절하다. 따라서 정답은 ''that - during''이다.', 1),
('957ca538-d4d6-41de-8c0a-a1b65fa7cc28', '17cee299-a353-4023-b25f-2c26601c7ef8', 42, '무관한문장', '글의흐름', true, '3', '이 글은 뇌의 막대한 에너지 소비량을 언급하며 뇌 건강을 위해 ''멍 때리기(spacing out)''를 통한 휴식이 필요함을 설명하고 있다. 번 문장은 규칙적인 신체 운동이 천연 진통제 역할을 하는 엔도르핀 생성을 증가 시킨다는 내용으로, 뇌의 인지적 휴식이라는 주제와 관 련이 없는 신체 운동의 생리학적 효과를 다루고 있다.', 1),
('78133285-8b14-4654-89ce-9821628d5b8e', '17cee299-a353-4023-b25f-2c26601c7ef8', 43, '어휘', '문법/어휘', true, '5', 'facilitate는 어떤 일을 더 쉽게 되도록 돕는다는 의 미이다. 그러나 번의 영영풀이는 장애물을 도입하여 진전을 방해하다라고 설명하고 있으므로 정반대의 뜻을 제시하고 있어 올바르지 않다. enhance(향상시키 다): 무언가의 질, 가치, 또는 정도를 개선하는 것 accurately(정확하게): 정밀하고 왜곡이나 오류가 없는 방식으로 concrete(구체적인): 모호하거나 추상적이 기보다는 명확하게 정의되고 구체적인 evidence(증 거): 어떠한 믿음이나 주장이 사실인지 여부를 나타내 는 사실이나 데이터', 1),
('565840f8-5d32-4333-b29b-b5957af02c9d', '17cee299-a353-4023-b25f-2c26601c7ef8', 44, '제목요지', '주제파악', true, '1', '지문에서 타인에게 방해가 되지 않도록 이어폰을 챙 기고, 걷는 환경과 기분에 맞춰 적절한 음악을 골라 산 책을 즐기라는 조언을 하고 있다. 따라서 요지로 가장 적절한 것은 이다.', 1),
('b7e7b948-18be-44f6-bd30-b6a7d3590690', '17cee299-a353-4023-b25f-2c26601c7ef8', 45, '빈칸추론', '논리/추론', true, '3', '‘의자병’이라는 용어가 나타내고자 하는 바는 장시간 앉아 있을 때 발생하는 부정적인 결과들이다. 뒤이어 언급된 비만, 심장병 등의 질병을 아우르는 말인 ‘해로운 건강상의 영향’이 빈칸에 가장 적합하다.', 1),
('6b348fea-3da9-45d7-830c-2b110212773d', '17cee299-a353-4023-b25f-2c26601c7ef8', 46, '빈칸추론', '논리/추론', true, '4', '걷기가 뇌의 인지 영역을 더 효율적으로 작동하게 하 여 창의적인 성과를 낸다는 연구 결과를 요약하는 문장 이다. 따라서 (A)에는 ‘효율성’을 뜻하는 efficiency가, (B)에는 ‘창의적인’ 성과를 뜻하는 creative가 들어가는 것이 적절하다.', 1),
('fbc11c02-4b50-4b24-9025-bff7cbb1dea7', '17cee299-a353-4023-b25f-2c26601c7ef8', 47, '빈칸추론', '논리/추론', true, '2', '지문 전반부에서 정기적으로 걷는 사람들이 병가 일 수가 적고 병에 걸리더라도 증상이 가벼운 이유를 설명 하고 있다. 이는 신체의 방어 능력이 강화되었음을 의 미하므로 ''강화된 신체 방어 기제''가 정답으로 적절 하다.', 1),
('73c25c5e-a17c-48dc-8d8f-39397d86a598', '17cee299-a353-4023-b25f-2c26601c7ef8', 48, '내용일치', '독해/사실확인', true, '4', '본문 종반부에서 평소에 규칙적으로 산책을 지속한 구성원들은 혹여 유행성 독감이나 감기에 걸리더라도 투병 주기가 한층 짧고 증상의 가혹도 역시 한결 가벼 웠다(shorter period of time with milder symptoms)고 언급했으므로 는 서술이 정반대로 왜 곡되어 일치하지 않는다. 걷기는 뼈를 강화하고 혈 압을 낮추는 데 도움이 된다. 매일 15분씩 걸으면 초콜릿 소비를 절반으로 줄일 수 있다. 잦은 신체 활동은 뇌 기능을 향상시킬 수 있다. 한 연구는 규 칙적으로 걷는 것이 신체의 면역 체계를 향상시킨다는 것을 발견했다.', 1),
('af5bd487-3e46-42b6-b23c-68129f643233', '17cee299-a353-4023-b25f-2c26601c7ef8', 49, '제목요지', '주제파악', true, '4', '뇌가 체중에 비해 막대한 에너지를 소모하며 일상을 관리하기 때문에 휴식이 필요하며, ''멍 때리기''가 그 중 요한 휴식의 기회가 된다는 글이다. 따라서 제목으로 가장 적절한 것은 ‘멍 때리기: 고에너지 뇌를 위한 필수적인 휴식 시간’이다.', 1),
('2e28ab8f-2fb7-40ba-a038-16537406fc17', '17cee299-a353-4023-b25f-2c26601c7ef8', 50, '어휘', '문법/어휘', false, 'insufficient', 'not enough, not meeting a required standard는 충분하지 않다, 기준에 미치지 못한다는 의미이므로 지 문에서 이에 해당하는 단어는 insufficient이다.', 1),
('fb10301d-ff52-4dac-b2dd-7e6b8fb70440', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 1, '어휘', '문법/어휘', true, '3', '책을 빌릴 수 있는 곳 → library (도서관)
① 화장실 ② 서점 ④ 박물관 ⑤ 가게', 1),
('f12061d3-df4c-4a71-a49f-71802c955e5b', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 2, '어휘', '문법/어휘', false, 'go, straight', 'go straight: 직진하다', 1),
('903c0545-73da-4fcb-b2dd-021c6bfafa4d', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 3, '어법', '문법/어휘', false, '(1) happily (2) excited (3) perfectly (4) scientist', '(1) ‘행복하게’라는 의미로 동사 smiled를 수식하므로 부사 happily가 들어가야 한다.
(2) 주어 She가 ‘신이 난’ 감정을 경험하였기에 접미사 ‘-ed’가 붙은 excited가 들어가야 한다.
(3) 어떻게 대답했는지 동사 answer를 수식하므로 ‘완벽하게’라는 의미의 부사 perfectly로 써야 한다.
(4) 특정 직업이나 역할을 나타낼 때는 명사 뒤에 접미사 ‘-ist’를 붙일 수 있다. 과학자는 scientist이다.
(1) 아이들은 공원에서 행복하게 놀았다.
(2) 그녀는 깜짝 파티에서 친구들을 보자 신이 났다.
(3) 그녀는 질문에 완벽하게 대답해서 선생님께 만점을 받았다.
(4) 그 과학자는 우주를 더 잘 이해하기 위해 별과 행성을 연구한다.', 4),
('ebd2d7cd-bc04-4ce5-8827-7d7db4f3201a', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 4, '대화문', '화용/의사소통', true, '2', '길을 물을 때는 How can we get there?로 표현한다.', 1),
('8149372e-c0cd-4c63-b9a1-86103af0ce2f', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 5, '대화문', '화용/의사소통', true, '5', '⑤ ‘저는 무지개 폭포를 기대하고 있어요’는 기대를 나타내므로, ‘길을 물을 때 응답하는 표현’으로는 적절하지 않다.
① 그것은 카페 옆에 있습니다. ② 한 블록 직진하세요. ③ 꽃집에서 좌회전하세요. ④ 코너에서 우회전해야 해요.', 1),
('f1d3c805-d433-45a0-a6d0-b5760d5587e3', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 6, '내용일치', '독해/사실확인', true, '2', '아빠가 지도를 봐 줄 수 있냐고 물었으므로 ② ‘아빠는 길 안내를 위해 그의 전화를 확인하고 있다.’는 글의 내용과 일치하지 않는다.
① 그들은 무지개 폭포를 갈 것이다.
③ 무지개 폭포는 그들의 위치에서 가깝다.
④ 폭포까지 가는 데 8분이 걸릴 것이다.
⑤ Alicia는 무지개 폭포에 가는 것에 대해 신나 하고 있다.', 1),
('26bcf63a-8101-47c9-a127-aacc19507e2b', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 7, '어휘', '문법/어휘', false, 'bread, bakery', '그 소녀는 약간의 빵을 원한다. 그녀는 제과점을 찾고 있다.', 1),
('33e10a51-2153-48bf-bf8e-4f49ad709e95', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 8, '대화문', '화용/의사소통', true, '3', 'A의 ‘내일 학교 축제에서 공연할 준비가 되었나?’라는 질문의 응답으로 B는 공연에 대한 기대와 걱정을 나타내는 표현을 하는 것이 자연스럽다. ③은 축제와 상관없는 수학 시험에 대해 답했으므로 대화 흐름이 어색하다.
① 무대에서 공연하는 게 정말 기대돼.
② 너무 신나! 몇 주 동안 준비했어.
③ 나는 다음 주에 수학 시험이 있어서 성날 기대돼.
④ 약간 긴장되지만, 정말 기대하고 있어.
⑤ 응, 공연을 위해 모든 준비가 되어 있어.', 1),
('300240d0-1e87-4597-9784-033ed32824f5', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 9, '어법', '문법/어휘', true, '5', '주어 Sarah는 3인칭 단수라 「동사원형 + -s」가 붙는 enjoys를 써야 한다. 동사 enjoy의 목적어는 「동사원형 + -ing」 형태인 동명사가 와야 하므로 jogging을 써야 한다.
Sarah는 주말마다 공원에서 조깅하는 것을 즐긴다.', 1),
('4864a2e0-fbb4-4f9a-ae56-4ff30d92588d', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 10, '어법', '문법/어휘', false, 'not, eating', '동명사의 부정형은 「not[never] + -ing」으로 표현한다.', 1),
('76fe3d2b-9f76-4ef5-874b-0d0fc879909a', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 11, '어법', '문법/어휘', true, '5', '⑤ 조동사 will의 평서문은 「주어 + will + 동사원형~」이므로 ⑤는 어법상 올바르다.
① 조동사 will의 의문문은 「Will + 주어 + 동사원형~?」으로 Will you help me?가 되어야 한다.
②, ③ 조동사 뒤에는 동사원형이 나와야 하므로 ② She will study tonight., ③ He will go to the market.이 되어야 한다.
④ 조동사 will의 부정문은 「주어 + will not[won’t] + 동사원형~」으로 쓰므로 They will not arrive on time.이 되어야 한다.', 1),
('e97ef74d-c792-4968-a32e-2e2306fcb60d', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 12, '어법', '문법/어휘', true, '1', '① 동사 love의 목적어로 동명사 listening은 맞는 형태이다.
② 「be going to + 동사원형」으로 써야 하므로 watching을 watch로 고쳐 써야 한다.
③ 조동사 will 뒤에는 동사원형이 와야 하므로 visits를 visit으로 고쳐 써야 한다.
④ 동사 enjoy는 동명사를 목적어로 취하므로, spend를 spending으로 고쳐 써야 한다.
⑤ 동사 like의 목적어로 동사 help를 동명사 형태인 helping으로 고쳐 써야 한다.
A: 안녕, 수진. 이번 주말에 영화를 볼 예정이야. 너는 주말에 무슨 계획 있어?
B: 응, 토요일에 조부모님 댁에 갈 거야.
A: 좋겠다. 그분들과 시간 보내는 거 좋아해?
B: 물론이지. 그분들 이야기 듣는 것도 좋고, 정원 가꾸는 걸 도와드리는 것도 좋아.', 1),
('57500382-46cf-46e0-a102-fc028e482d9c', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 13, '영작', '쓰기', false, 'I dislike getting up early in the morning.', 'dislike는 동명사를 목적어로 취하는 동사로 ‘일어나는 것’을 의미하는 getting up이 나와야 한다.', 1),
('d251771c-18f8-4314-b4d0-bf80fe31a63b', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 14, '어법', '문법/어휘', true, '1', 'ⓐ는 동명사 playing이 보어로, ⓑ는 동명사 Reading이 주어로, ⓔ는 Not going이 주어로 쓰인 올바른 문장이다. ⓒ, ⓓ의 동사 enjoy와 suggested는 둘 다 목적어로 동명사를 취하므로 to watch를 watching으로, to go를 going으로 고쳐 써야 한다.
ⓐ 그녀의 취미는 피아노를 연주하는 것이다.
ⓑ 책을 읽는 것은 내가 가장 좋아하는 취미이다.
ⓒ 나는 주말에 영화를 보는 것을 즐긴다.
ⓓ 그는 저녁 식사 후 산책하자고 제안했다.
ⓔ 일찍 자지 않으면 졸릴 수 있다.', 1),
('98c92cf0-e2d9-4853-95db-6586687eedff', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 15, '문장삽입', '글의흐름', true, '2', '주어진 문장은 ‘나는 수원에서 군산으로 가는 첫 버스 승차권을 살 것이다.’라는 의미로, ‘이른 아침에는 길이 막히지 않을 것이다.’는 이유가 나오는 문장 앞인 ②에 들어가는 것이 적절하다.', 1),
('d1fecf82-3d5a-46ab-ad3b-4d4c0257e45a', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 16, '어휘', '문법/어휘', true, '2', 'get: 사다, 얻다', 1),
('9e35f37c-405b-4b8f-b6d6-85df1eeff838', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 17, '어법', '문법/어휘', true, '3', '시간의 범위가 넓은 ‘아침에’라는 의미와, 특정 장소의 안을 가리키는 ‘~안에’라는 의미로 공통으로 쓸 수 있는 전치사는 in이다.', 1),
('3c2b7790-a1a2-4c13-b2da-b6f6b59b90e3', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 18, '제목요지', '주제파악', true, '2', '윗글의 목적은 ② ‘가족 여행 계획을 공유하기 위해’가 가장 적절하다.
① 케이크를 굽는 방법을 설명하기 위해
③ 해산물 레스토랑을 소개하기 위해
④ 군산의 유명한 장소를 묘사하기 위해
⑤ 버스를 타는 것의 장점을 이야기하기 위해', 1),
('73d0708a-edb4-46d8-9cc5-dd00317f1d48', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 19, '내용일치', '독해/사실확인', true, '4', '글쓴이는 생일 케이크를 제과점에서 사고, 스튜디오에 가서는 사진을 찍을 계획이지 ④ 스튜디오에서 생일 케이크를 먹을 계획은 아니다.
① 글쓴이의 할머니 생신은 토요일이다.
② 글쓴이는 아빠와 함께 군산에 갈 예정이다.
③ 글쓴이는 아침 일찍 첫 버스를 탈 것이다.
⑤ 글쓴이는 가족 여행을 위해 네 가지 주요 활동을 계획했다.', 1),
('f1cf80b8-de0c-4e99-81a4-53abad36605a', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 20, '영작', '쓰기', false, 'we will take family pictures!', 'will의 평서문은 「will + 동사원형」으로, ‘가족사진을 찍다’는 take family pictures이다.', 1),
('61cf673a-ad23-4033-97d1-63ef3bb2fe03', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 21, '어법', '문법/어휘', true, '3', '다음 문장인 ‘제과점에는 딸기 케이크가 없었다’에 과거 시제 was가 나왔으므로 ‘문제가 생겼다’는 과거 시제 had가 들어가야 한다.', 1),
('4343b7b2-4275-43a3-80bd-1198071889bd', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 22, '어휘', '문법/어휘', true, '2', 'put on: (옷을) 입다
work out: 일이 잘 풀리다', 1),
('5112c441-2837-48f8-b66e-19d551e1a9dc', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 23, '영작', '쓰기', false, 'Grandma, you look like a student in that uniform.', '‘~처럼 보인다’ 의미로 「look like a + 명사」를 쓰고, ‘옷을 입은 상태’를 나타낼 때는 전치사 in을 쓴다.', 1),
('9e28b5b2-326e-42e7-bfc9-1d900a645427', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 24, '글의순서', '글의흐름', true, '2', '1. 글쓴이의 아빠가 버스를 놓쳤다. → 3. 그들은 온돌 객실이 있는 기차를 탔다. → 4. 그들은 딸기 케이크 대신 당근 케이크를 샀다. → 2. 그들은 해산물 레스토랑에서 할머니를 만났다. → 5. 그들은 스튜디오에 가서 교복을 입고 사진을 찍었다.', 1),
('1481e481-6d92-4c89-a36a-be49bff9315e', '03cf58f1-185b-47ae-8024-ff3d6fed1323', 25, '내용일치', '독해/사실확인', true, '1', '① 글쓴이는 늦게 일어나서 버스를 놓쳐서 차선책으로 기차를 탔기 때문에 ① ''글쓴이는 아침 일찍 세 번째 버스를 탔다''는 글의 내용과 일치하지 않는다. ② 그 기차에는 특별한 온돌방이 있었다. ③ 글쓴이와 아빠는 할머니 생신 파티에 제시간에 도착했다. ④ 해물 요리 식당은 열려 있었다. ⑤ 글쓴이와 할머니가 재미난 교복을 입었다.', 1),
('179b065a-60b7-469f-ad3e-f6b099ed0a1c', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 1, '어법', '문법/어휘', true, '3', '주어 Dad and I와 동사원형 visit 사이에 들어갈 단어는 조동사 will이 적절하다.', 1),
('e51e9ff8-d7d8-4de1-865d-46f704cf00e6', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 2, '어법', '문법/어휘', true, '4', '조동사 will과 목적어 a plan 사이에는 동사원형이 들어가야 하므로 make가 적절하다.', 1),
('95815762-b240-4527-8ba2-8be12aa410c2', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 3, '어법', '문법/어휘', true, '3', '조동사 will의 부정형은 「주어 + will not + 동사원형」 형태이므로 not 뒤에 동사원형 be가 적절하다.', 1),
('513c510f-5720-4bcd-b55d-cd6708e72ba3', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 4, '어법', '문법/어휘', true, '2', '조동사 「will + 동사원형」 형태로 ''사다''라는 의미인 get이 적절하다. ① buying → buy ③ love → loves ④ finds → find ⑤ be take → take', 1),
('86684720-3ebd-4d99-a791-de5c3106357b', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 5, '영작', '쓰기', false, 'Taking family photos in the studio will be great.', '스튜디오에서 가족사진을 찍는 것''이라는 의미로 동명사 Taking family photos in the studio가 주어 자리에 오고, ''멋질 것이다''라는 의미로 will be great이 이어서 나와야 자연스럽다.', 1),
('eb5ef859-d8ff-4c40-bf2c-1f0061931e62', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 6, '어휘', '문법/어휘', true, '2', '글쓴이는 할머니의 생신 파티를 준비하면서 여러 가지 계획을 세우고 있으므로 설레는 감정인 ''기대되는, 들뜬''의 의미의 excited가 가장 자연스럽다. ① 슬픈 ② 화난 ③ 긴장한 ⑤ 실망한', 1),
('ada96c02-9c9e-44e3-beae-3fdb09624784', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 7, '내용일치', '독해/사실확인', true, '4', '글쓴이는 케이크를 유명한 제과점에서 살 계획이지, 집에서 직접 구울 계획은 없다. ① 그녀는 여행을 위해 버스표를 살 것이다. ② 그녀는 좋은 해물 요리 식당을 찾을 것이다. ③ 그녀는 스튜디오에서 가족사진을 찍을 것이다. ④ 그녀는 할머니를 위해 집에서 케이크를 구울 것이다. ⑤ 그녀는 할머니의 생신 파티를 준비할 것이다.', 1),
('26d7aeb4-5669-4ef9-8d85-b6498a74dc88', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 8, '내용일치', '독해/사실확인', true, '3', '정확한 도착 시간은 적혀 있지 않으므로 ③ ''그녀는 군산에 몇 시에 도착할 예정인가요?''는 글을 읽고 답할 수 있는 질문이 아니다. ① 그녀의 할머니는 어디에 사시나요? ② 그녀의 할머니 생신은 무슨 요일인가요? ④ 그녀는 유명한 제과점에서 무엇을 살 예정인가요? ⑤ 그녀는 수원에서 군산으로 어떻게 이동할 예정인가요?', 1),
('4d879340-3858-44e8-9af8-a2b8c426f5e2', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 9, '내용일치', '독해/사실확인', true, '2', '아빠와 나는 군산에 계신 할머니를 방문할 것이다''라는 의미의 Dad and I will visit her in Gunsan. 문장을 통해서 할머니가 군산에 살고 계시는 것을 알 수 있다. ① 글쓴이의 할머니 생신은 이번 일요일이다. (→ 이번 주 토요일) ② 글쓴이의 할머니는 군산에 사신다. ③ 글쓴이와 그녀의 아빠는 수원에서 군산으로 비행기를 탈 것이다. (→ 버스 승차권을 살 것이므로 버스를 탈 것이다.) ④ 아침 일찍 거리는 붐빌 것이다. (→ 길이 막히지 않을 것이다) ⑤ 글쓴이, 그녀의 아빠, 그리고 할머니는 이탈리안 식당에 갈 것이다. (→ 해물 요리 식당)', 1),
('27bd2570-89a9-4838-9bfa-1fa34d25c6ce', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 10, '어휘', '문법/어휘', true, '3', '① 식사를 하는 장소 (→ restaurant) ② 다른 장소로의 여행 (→ trip) ③ 해결이 필요한 상황 (→ problem) ④ 물고기나 새우 같은 바다에서 온 음식 (→ seafood) ⑤ 장소에 들어가거나 서비스를 이용할 수 있게 해주는 종이 (→ ticket)', 1),
('88cf850a-5660-4f9a-91e4-ceb3785ab594', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 11, '문장삽입', '글의흐름', true, '4', '차선책이 있다''는 문장 전에는 차선책이 나온 이유가 나오는 것이 적절하므로 ⑤ ''하지만 아빠와 나는 늦게 일어나서 버스를 놓쳤다''가 가장 자연스럽다. ① 빵집에는 딸기 케이크가 있었다. ② 할머니와 아빠는 버스를 타는 것을 좋아하셨다. ③ 그리고 아빠와 나는 기차를 일찍 탈 것이다. ④ 우리는 이미 제시간에 할머니 댁에 도착했다.', 1),
('7e88d186-1c36-4bfd-a91d-6619a63fcf24', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 12, '무관한문장', '글의흐름', true, '3', '기차를 타고, 즐거운 시간을 보내며 제시간에 도착한다는 내용이므로 ⑤ ''나는 기차의 모든 승객의 수를 세었다''는 내용은 글의 흐름상 어색하다.', 1),
('ec678c6d-691b-4867-a944-6da7afba71f7', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 13, '어법', '문법/어휘', true, '5', '동사 is의 보어 자리에 ''~하는 것, ~하기''의 의미로 동명사(동사원형+-ing) 형태를 취해야 한다.', 1),
('39ff3436-eed2-4ac1-8828-66236073c0ce', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 14, '어법', '문법/어휘', true, '2', '첫 번째 there는 ''거기에''라는 의미이고, 두 번째 There는 「There is + 명사」 형태의 유도부사로 ''~이 있다''는 의미이다.', 1),
('6792b249-c322-4c7c-812c-9ff21217f3d9', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 15, '어법', '문법/어휘', true, '3', 'even은 ''심지어, ~조차''라는 의미로 강조의 기능을 나타낸다. 특정 장소를 가리킬 때는 ''~에서''라는 의미의 at이 가장 적절하다.', 1),
('9a6484ba-64ae-447f-859d-e8b37c0725f7', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 16, '글의순서', '글의흐름', true, '4', '(B) 다음에 ''제과점에 딸기 케이크가 없었다''는 문장이 나온다.', 1),
('2c745d38-c95d-4d0c-ba80-2eb1f4e11e36', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 17, '내용일치', '독해/사실확인', true, '5', '글쓴이의 가족들은 해물 요리 식당에서 만났다.', 1),
('53892fa0-be94-4e0f-a914-c5c74623a168', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 18, '내용일치', '독해/사실확인', false, '그들은 당근 케이크를 샀다.', '글쓴이와 아빠는 딸기 케이크를 구하지 못하고 대신 당근 케이크를 샀다. 질문: 그들은 무슨 케이크를 샀는가?', 1),
('16e3cfc3-3b17-4fe9-9250-3e8e52345c50', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 19, '어휘', '문법/어휘', false, 'seafood', '물고기나 새우 같은 바다에서 나는 음식 → seafood (해산물)', 1),
('e500f2eb-10f7-4d3f-bc1b-0930daa58f94', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 20, '글의순서', '글의흐름', true, '1', '마지막으로, 우리는 스튜디오에 갔다.'' 다음에 교복을 입고, 사진을 찍는 순서가 자연스러우므로 제일 앞에 주어진 문장이 나오는 것이 자연스럽다.', 1),
('05d86538-785f-42e0-9d45-5cd4fc9f6940', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 21, '어휘', '문법/어휘', false, '(A), put on', '스튜디오에서 교복을 입고 사진을 찍었다는 내용이 자연스러우므로 ''옷을 입다''는 의미인 put on이 자연스럽다. take off는 ''옷을 벗다''의 의미이다.', 1),
('b3b1f0ef-7244-45dc-8405-1190bae71ad6', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 22, '어휘', '문법/어휘', true, '3', '교복을 입었기에 ''학생'' 같아 보인다는 표현이 가장 자연스럽다.', 1),
('6c35c7ce-cac9-4e32-8127-f244feac6dfd', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 23, '어휘', '문법/어휘', false, 'plan', 'plan: 명 계획', 1),
('032fdcd2-37f4-48f6-9e43-b8892bf22733', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 24, '내용일치', '독해/사실확인', true, '5', '처음 계획은 잘 풀리지 않았지만, 차선책도 훌륭했다고 했으므로 ⑤가 적절하지 않다. ① 글쓴이와 그녀의 할머니는 스튜디오에서 사진을 찍었다. ② 글쓴이와 그녀의 할머니는 교복을 입었다. ③ 할머니는 학생처럼 보였다. ④ 할머니는 글쓴이에게 고마워했다.', 1),
('20dcf50d-b7d2-4aa6-bd11-fbf1dce35888', 'ba9d7f64-e605-4277-9204-8fe1b72f049f', 25, '어법', '문법/어휘', false, 'liked taking pictures', '동사 liked의 목적어로 take의 동명사 taking을 써야 한다.', 1),
('7544adbe-8b41-49e2-9e54-301038c5320b', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 1, '문장삽입', '글의흐름', true, '5', '주어진 문장은 ''스튜디오에서 가족사진을 찍는 것은 멋질 것이다.''이므로 ''네 번째, 우리는 가족사진을 찍을 것이다''라는 문장 뒤인 ⑤에 나오는 것이 흐름상 자연스럽다.', 1),
('e4f02047-559e-45b1-a281-5da622abbdb1', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 2, '어법', '문법/어휘', true, '4', '(a) ''방문할 것이다''는 미래의 계획을 나타내므로 조동사 will 또는 are going to 둘 다 가능하다. (b), (c) will은 조동사로 조동사 뒤에는 항상 동사원형이 나와야 한다. 따라서 동사원형 get, prepare가 각각 들어가야 한다.', 1),
('d83fcd0e-fb10-4b7e-9f50-5ce0ea0d3527', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 3, '어법', '문법/어휘', false, 'makes plans for', '~의 계획을 세우다''는 make plans for ~ 표현을 쓴다. 주어 Dad가 3인칭 단수형이므로 동사는 makes로 써야 하며, plan은 셀 수 있는 명사이므로 여기서는 복수 표현이 적절하다.', 1),
('ce4baa32-6ff1-4e67-aa24-6c77806c6da8', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 4, '어휘', '문법/어휘', true, '1', '① 도시 거리의 한 구역 (→ block) ② 특정한 지역 또는 장소 (→ place) ③ 나무가 많은 넓은 지역 (→ forest) ④ 다른 장소로의 여행 (→ trip) ⑤ 길고 가는 형태의 파스타 종류 (→ noodle)', 1),
('d5039791-1cde-4474-ab5d-3438dc04c7b0', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 5, '어휘', '문법/어휘', false, 'tickets', '장소에 들어가거나 서비스를 이용할 수 있게 해주는 종이 한 장 → ticket (표) 표를 2장 사야 하므로 ticket 명사의 복수 형태인 tickets로 써야 한다.', 1),
('25f9960b-976e-42c6-ad65-250ea2a7d6fe', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 6, '어법', '문법/어휘', true, '3', '출발지에서 도착지를 나타내는 전치사는 ‘~에서 …까지’ 의미의 from A to B를 쓰고, 도시명 앞에는 ‘~에서’라는 의미로 전치사 in을 쓴다.', 1),
('c1dcd3cc-6259-4263-93d3-68adc9d17814', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 7, '내용일치', '독해/사실확인', false, 'Dad, and Grandma', '할머니 생신을 위해 할머니에게 간 가족은 글쓴이와 아빠이므로 글쓴이, 아빠, 할머니가 가족사진을 함께 찍을 것이다.', 1),
('b13ec995-0e6d-48fb-9a5b-7402b4a8beab', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 8, '어법', '문법/어휘', true, '5', '사람의 감정을 표현할 때는 「동사+-ed」 형태로 형용사로 만들 수 있다. ‘신이 난, 들뜬’이라는 뜻의 excited는 ⑤에 가장 적절하다. ①②③④의 빈칸에는 무언가가 흥미롭거나 재미있다는 의미이므로 ‘신이 나게 하는, 흥미로운’ 의미의 exciting이 자연스럽다. ① 그 책은 매우 흥미진진했다. ② 그 소식은 듣기에 흥미로웠다. ③ 롤러코스터는 정말 신이 난다. ④ 이 게임은 매우 신이 난다. ⑤ 나는 내 생일 파티에 신이 났다.', 1),
('643a6169-a86d-4d90-b973-ca1000b0227d', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 9, '내용일치', '독해/사실확인', true, '4', '주인공과 아빠는 ‘이른 아침’에 버스를 탈 예정이다. 글쓴이는 언제 버스를 탈 예정인가요? ① 밤에. ② 점심시간에. ③ 늦은 저녁에. ⑤ 이른 오후에.', 1),
('eb3117c5-aff8-42cd-88d3-09cd9349e546', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 10, '내용일치', '독해/사실확인', true, '3', '가족사진을 스튜디오에서 찍을 것이라고 하였으므로 ③ ‘그 가족은 가족사진을 어디에서 찍을 예정인가요?’는 글을 읽고 답할 수 있다. ① 할머니는 몇 살이신가요? ② 딸기는 얼마인가요? ④ 그들은 군산에 몇 시에 도착할 예정인가요? ⑤ 할머니는 어떤 종류의 빵을 좋아하시나요?', 1),
('5a5ecdd0-64c8-444c-92d2-f82dde01d944', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 11, '내용일치', '독해/사실확인', true, '2', '할머니가 딸기를 좋아한다고 언급되어 있다. ① 딸기 케이크가 저렴하기 때문이다. ② 할머니가 딸기를 좋아하기 때문이다. ③ 내가 딸기 케이크를 먹고 싶기 때문이다. ④ 아빠가 딸기 케이크를 먹는 것을 좋아하기 때문이다. ⑤ 그 제과점이 딸기 케이크만 판매하기 때문이다.', 1),
('99b71209-523f-465c-b847-742ab8e15036', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 12, '글의순서', '글의흐름', true, '2', '글쓴이는 버스 승차권을 먼저 사고, 케이크를 구매한 후, 레스토랑을 찾고 마지막으로 사진을 찍을 계획이다.', 1),
('16099cde-25ee-445d-ad15-bd2b8e313f1e', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 13, '내용일치', '독해/사실확인', false, '(1) F (2) T (3) F', '(1) 할머니의 생신은 이번 주 토요일이다. (2) ‘좋은 해물 요리 식당을 찾을 것이다’는 문장을 통해 거기에 갈 것이라는 것을 추측할 수 있다. (3) ‘사진을 스튜디오에서 찍는 것은 멋진 것이다’는 문장을 통해 스튜디오에 가서 찍을 것이라는 것을 예상할 수 있다.', 3),
('66af66dd-20ca-4a6d-9eb5-cecc4a500bee', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 14, '어법', '문법/어휘', true, '2', '‘~하게 보이다’는 의미는 「look + 형용사」를 쓴다. ① ‘일이 잘 풀리다’라는 의미인 work out 뒤에는 동사를 수식해주는 부사 perfectly가 나와야 한다.', 1),
('d2e791cb-102d-4a0e-8ef6-e2c0def834a3', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 15, '글의순서', '글의흐름', true, '3', '‘우리는 해물 요리 식당에서 할머니를 만났다.’는 내용 다음에 그녀(= 할머니)가 그 음식을 좋아했다로 이어지는 것이 가장 자연스럽다.', 1),
('8ab6f78d-9472-4505-b3a5-6a6084435c88', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 16, '어법', '문법/어휘', true, '3', 'ⓑ에 들어갈 표현은 is의 보어로 동명사 taking이 들어가야 한다. 동명사 taking은 ④번 주어, ⑤번 보어, ①,②번 목적어 역할로 쓰일 수 있다. ③번은 동사원형이 나와야 하는 자리로 take가 들어가야 한다. ① 그녀는 개를 산책시키는 것을 좋아한다. ② 나는 저녁에 산책하는 것을 즐긴다. ③ 그는 어제 우산을 가져가지 않았다. ④ 버스를 타는 것은 환경에 좋다. ⑤ 그녀의 가장 좋아하는 취미는 자연 사진을 찍는 것이다.', 1),
('4e0a268d-e09a-475f-8754-e2af41f176dd', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 17, '어휘', '문법/어휘', true, '5', '차선책이 있다는 글쓴이의 말에, 아빠가 ‘훌륭해!’라고 긍정적인 반응을 보였으므로, ④ ‘~ 덕분에’라는 의미의 thanks to가 가장 자연스럽다. ① ~를 위해 ② ~없이 ③ ~옆에 ⑤ ~대신에', 1),
('00d8b64e-945e-4285-8a3e-b404b2b0f7e1', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 18, '지칭', '논리/추론', true, '2', '기차를 탔다는 문장이 앞에 있으므로, it은 기차를 가리킨다.', 1),
('a4286a9e-4669-449d-a616-112084fbd9fd', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 19, '영작', '쓰기', false, 'Dad and I really enjoyed riding on the train.', 'enjoy의 목적어로 ‘타는 것’이라는 의미로 ride의 동명사 riding을 써야 한다.', 1),
('dfa3f9b6-8043-4235-8a7f-7157bfe96cb7', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 20, '어법', '문법/어휘', true, '3', '① there는 「There is + 단수 명사」의 유도부사로 ‘~이 있다’ 의미이다. ⑤ there는 장소를 가리킬 때 ‘그곳에, 거기서’라는 뜻으로 쓰였다. ① 테이블 위에 책이 있다. ② 중국 음식점이 많이 있다. ③ 저녁 6시에 거기서 만나자. ④ 우리의 계획에 많은 실수가 있다. ⑤ 기차역 근처에 제과점이 있다.', 1),
('b8060b04-0ab3-4a87-bedf-0b70958635e3', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 21, '영작', '쓰기', false, 'Her birthday party was a big success.', '「a + 형용사(big) + 명사」 어순으로 ‘성공’이라는 의미의 명사는 success이고, succeed는 ‘성공하다’라는 의미의 ‘동사’이다.', 1),
('8d52d79f-a406-40b3-8e3f-bf35a6d87e17', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 22, '어법', '문법/어휘', true, '5', '①와 ⑥의 like는 ‘~ 처럼’이라는 의미의 전치사로 쓰였고, 나머지는 모두 ‘좋아하다’라는 의미의 동사로 쓰였다. ① 그것은 좋은 생각처럼 들린다. ② 나는 오렌지보다 사과를 더 좋아한다. ③ 그는 바다에서 수영하는 것을 좋아한다. ④ Emily와 민호는 햄버거를 먹는 것을 좋아하나요? ⑤ 그들은 파티에 가는 것을 좋아하지 않을 것이다.', 1),
('4d7cd940-cd6d-4448-8fa6-f986c73cca4d', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 23, '내용일치', '독해/사실확인', true, '3', '스튜디오에서 가족사진을 찍었을 뿐, ‘할머니 댁에서 사진 찍기’는 언급되어 있지 않다. ① 기차를 타는 것 ② 재미로 교복을 입는 것 ④ 해산물 레스토랑에서 할머니를 만나는 것 ⑤ 딸기 케이크 대신 당근 케이크를 고르는 것', 1),
('85366c41-f4df-4314-acda-969b854f4773', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 24, '내용일치', '독해/사실확인', true, '3', '③ 기차표 가격이 얼마인지는 언급되어 있지 않다. ① Plan B는 무엇이었나요? (→ Plan B was taking the train.) ② 그들이 버스를 놓친 이유는 무엇인가요? (→ They woke up late.) ④ 그들은 어디에서 사진을 찍었나요? (→ They went to the studio.) ⑤ 그들이 할머니를 위해 고른 케이크는 무엇이었나요? (→ They got a carrot cake, instead.)', 1),
('039a01a9-3ab9-4fe3-a8c0-130f8217ace1', '3dc2f04d-1a16-40f0-9ea1-2e068b4baae9', 25, '내용일치', '독해/사실확인', false, 'The train[It] had a special ondol room.', '질문: 기차에는 어떤 종류의 방이 있었나요? 기차를 탔는데, 그 기차에는 심지어 특별한 온돌마루실이 있다고 언급되어 있다.', 1),
('c83ac4c8-af59-4426-95ea-6e10adf5b402', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 1, '어휘', '문법/어휘', true, '2', '길고 가는 형태의 파스타 종류 → noodle (국수)
① 그는 내 생일에 선물을 주었다.
② 그녀는 오늘 점심으로 국수 요리를 만들었다.
③ 나는 어젯밤 저녁으로 맛있는 해산물을 먹었다.
④ 기차역에 들어가기 전에 표를 보여주세요.
⑤ 우리는 지난 주말에 시골로 여행을 갔다.', 1),
('65e735cf-ddb9-440e-82dc-0141addcbfb9', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 2, '어휘', '문법/어휘', false, 'made, plans, for, in, time, took, pictures, turned, left', 'make plans for: ~의 계획을 세우다
in time: 제시간에
take pictures: 사진을 찍다
turn left: 좌회전하다', 1),
('4759d78b-739b-4ffc-9183-07794b2bae6f', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 3, '어법', '문법/어휘', true, '3', '③ ‘빨리 과제를 끝냈다’라는 의미이므로 형용사 quick은 부사 quickly로 고쳐야 한다.
① 친구들이 선물을 줬을 때, 그는 친구들에게 행복하게 웃었다.
② 그녀는 숙제를 빨리 끝내고 놀러 나갔다.
③ 그는 과제를 빨리 끝내고 선생님께 보여줬다.
④ 학생들은 축제를 즐겼기 때문에 행복해 보였다.
⑤ 선생님은 문제를 완벽하게 설명해서 모두가 이해할 수 있었다.', 1),
('ac302308-e237-44d1-8282-540f5afb052a', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 4, '대화문', '화용/의사소통', true, '3', 'A가 B의 말에 ‘나도 그래’라고 동의하며 ‘여름 방학에 가족과 해변에 갈 것이다’라고 말하고 있으므로 B 빈칸에는 여름방학이 기대가 된다는 표현이 나오는 것이 자연스럽다. ③ ‘실망했어’는 어색하다.
① 정말 기대돼!
② 정말 신이 나!
③ 정말 기뻐!
④ 정말 기대하고 있어.', 1),
('af947f95-62b1-45ba-8a04-baec4df0e5aa', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 5, '대화문', '화용/의사소통', true, '5', 'A가 서점 가는 길을 물었고, B가 가는 방법과 시간을 알려주었는데, ‘책을 빌려줘서 고맙다’는 ⑤는 어색하다. ‘알려줘서 고맙다’는 표현인 ‘Thank you for letting me know.’와 같은 표현이 와야 한다.', 1),
('483a89ea-0b7d-4b85-ac32-ca933617082f', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 6, '대화문', '화용/의사소통', true, '5', '이어지는 B의 대답이 ‘걸어서 5분 정도 걸릴 거예요’라고 대답했으므로 ⑤ ‘거기까지 가는 데 얼마나 걸리나요?’가 가장 적절하다.
① 거기에 어떻게 갈 수 있나요?
② 그것이 오른쪽에 있나요?
③ 거기까지 버스를 타고 갈 수 있나요?
④ 가장 가까운 서점이 어디에 있나요?', 1),
('ef99c500-d468-44c4-82bc-1c30ecc56d8f', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 7, '대화문', '화용/의사소통', true, '2', '② A의 ‘가장 가까운 옷 가게가 어디 있나요?’라는 길을 찾는 질문에 B의 ‘소셜 미디어에서 그 옷들을 찾을 수 있어요.’라는 대답은 어색하다. 나머지는 길을 묻고 답하는 표현으로 자연스럽다.
① A: 버스 정류장은 어디에 있나요? B: 한 블록 직진하면 왼쪽에 보일 거예요.
③ A: 이 근처에 박물관이 있나요? B: 네, 두 블록 지나 오른쪽에 있어요.
④ A: 공원은 어디에 있나요? B: 왼쪽으로 돌아 두 블록을 곧장 걸어가야 해요.
⑤ A: 도서관에 어떻게 가는지 알려주실 수 있나요? B: 물론이죠. 다음 모퉁이에서 우회전하세요.', 1),
('1e3feaa4-acc3-4ed4-becf-c4e2d848d141', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 8, '어법', '문법/어휘', true, '3', '③ 조동사 will의 부정문은 「won’t[will not] + 동사원형」 형태이므로 finishes를 finish로 바꿔야 한다.
① 조동사 will의 평서문은 「will + 동사원형」 형태이므로 goes를 go로 바꿔야 한다.
② 조동사 will의 의문문은 「Will + 주어 + 동사원형 ~?」 형태이므로 helps를 help로 바꿔야 한다.', 1),
('d799eff9-0420-41a0-a341-b5e58702c6ce', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 9, '어법', '문법/어휘', false, '(1) take → taking (2) rest → resting (3) bringing → not bringing', '(1) climbing과 take는 접속사 and로 연결되어 있으므로 같은 구조인 동명사 taking이 맞다.
(2) 동사 suggest의 목적어로 동명사 resting이 맞다.
(3) ‘배가 고팠기 때문에’ 간식을 가져오지 않은 것을 후회한다는 의미가 자연스러우므로 동명사 부정형인 「not + 동명사」 형태 not bringing이 맞다.', 3),
('a12c5c2b-29f2-4c40-ae57-436d5d7c1acb', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 10, '어법', '문법/어휘', true, '3', '③ 「won’t[will not] + 동사원형」 형태이므로 동사원형인 clean이 들어가야 한다.
① enjoy는 동명사를 목적어로 쓰므로 walking이 들어가야 한다.
② 주어 역할을 하는 동명사 Playing이 들어가야 한다.
④ 나는 내일 내 방을 청소하지 않을 것이다.
⑤ 그녀는 공원에서 그녀의 개를 산책시키는 것을 즐긴다.
⑥ 피아노를 연주하는 것은 내가 가장 좋아하는 취미이다.', 1),
('c2296f10-cf0c-445d-9bcf-3d3e123f3b46', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 11, '영작', '쓰기', false, 'Riding, a bicycle[bike], is', '‘자전거를 타다’는 ride a bicycle[bike] 표현을 쓰고, 주어 자리에 올 경우, 동명사 형태인 riding a bicycle[bike]로 쓴다. 동명사가 주어 자리에 올 경우, 주어는 3인칭 단수로 취급해야 하기 때문에 is를 써야 한다.', 1),
('93e272f1-747c-4d1b-a47c-4050c2121aec', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 12, '어법', '문법/어휘', true, '2', '② 동명사가 주어 자리에 올 경우, 주어는 3인칭 단수로 취급하기 때문에 are가 아닌 is를 써야 한다.', 1),
('5dbbd49b-cda5-49db-9e10-8704b784de73', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 13, '영작', '쓰기', false, '(1) He won''t[will not] visit his grandparents this weekend. (2) Will they play soccer after school? (3) Yes, she will. (4) No, they won''t[will not].', '(1) 조동사 will의 부정문은 「won’t[will not] + 동사원형」 형태를 취한다.
(2) 조동사 will의 의문문은 「Will + 주어 + 동사원형 ~?」 형태를 취한다.
(3), (4) 조동사 will의 의문문에 대한 응답이 긍정일 경우, 「Yes, 주어 + will.」, 부정일 경우, 「No, 주어 + won’t[will not].」 형태를 취한다.', 4),
('8394c001-87bd-4a82-9b35-3b1ea3bba3f1', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 14, '무관한문장', '글의흐름', true, '3', '② ‘과일 섭취는 건강에 좋다’는 과일 섭취의 일반적인 특징으로 딸기 케이크를 사는 것과는 직접적인 관련이 없다.', 1),
('66e2acbf-a0ec-47bf-af7e-0916faf0dc3f', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 15, '어법', '문법/어휘', true, '5', '기대되는 감정이나 상태이므로 「동사 + -ed」 형태가 와야 한다.', 1),
('16901ac3-6c10-49e4-9e15-890cd03e56b2', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 16, '어휘', '문법/어휘', false, 'tickets', '어떤 장소에 들어가거나 서비스를 이용할 수 있게 해주는 종이 한 장 (→ ticket 표)', 1),
('d6307966-eaca-4b5d-9b4a-b19fc751a7fa', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 17, '영작', '쓰기', false, 'Taking family photos in a studio will be great.', '주어는 ‘스튜디오에서 가족사진을 찍는 것’으로 동명사 Taking이 먼저 나와야 하고, 동사 ‘멋질 것이다’는 「will + 동사원형」인 will be를 배열해야 한다.', 1),
('69770ad1-8943-4ff2-bf39-8ded1202d46a', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 18, '내용일치', '독해/사실확인', true, '3', '할머니는 딸기를 좋아하신다는 내용은 나오지만 당근 케이크를 좋아하실지에 대한 내용은 알 수 없다.
① 글쓴이와 아빠는 군산으로 갈 것이다.
② 글쓴이는 첫 번째 버스표를 구매할 것이다.
③ 할머니는 당근 케이크를 좋아할 것이다.', 1),
('2c7a536a-523d-4741-8949-3108327dd148', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 19, '내용일치', '독해/사실확인', false, 'a seafood restaurant', '할머니의 생신 파티를 준비할 것이다''라는 문장 다음에 ''나는 좋은 해물 요리 식당을 찾을 것이다''라는 문장을 통해 할머니의 생신 파티는 ''해물 요리 식당''에서 열릴 것이라는 것을 알 수 있다.', 1),
('db17d3ca-a17d-4c2c-aef1-5415121c53bf', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 20, '내용일치', '독해/사실확인', false, 'at a famous bakery in Gunsan', '문장을 통해서 글쓴이는 군산에서 유명한 제과점에서 케이크를 살 것임을 알 수 있다. 질문: 글쓴이는 생일 케이크를 어디에서 살 예정인가요?', 1),
('103f0b3c-e51f-431d-8dba-42e04a8b2a3b', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 21, '어법', '문법/어휘', true, '2', '① 동사 enjoy는 목적어로 동명사를 쓰므로 riding은 올바르게 쓰였다. ④ ''늦게''라는 의미로 late를 써야 한다. lately는 ''최근에''라는 의미이다. ⓒ ''대성공''이라는 의미로 명사 success를 써야 한다. ◇ 주어 We 다음에는 동사 put이 나와야 한다. ⓔ upset은 ''속상한''이라는 의미의 형용사로, 부정문은 wasn''t upset을 써야 한다.', 1),
('0c7f5ed0-d71a-44eb-b7f3-b7783e9b89d4', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 22, '문장삽입', '글의흐름', true, '4', '주어진 문장은 ''마지막으로 우리는 스튜디오에 갔다''이므로 교복을 입고 사진을 찍었다는 내용 앞에 나오는 것이 가장 적절하다.', 1),
('e27bbebe-46db-45e2-ad3c-7fe98b896ef3', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 23, '어법', '문법/어휘', true, '4', '(A) 동사 is의 보어인 동명사 taking이 맞다. (B) 전체 글이 과거 시제로 되어 있으므로 take의 과거동사 took가 맞다. (C) ''~처럼 보인다''라는 의미로는 look like ~ 형태가 맞다.', 1),
('d53f0cdb-3793-4728-ad65-5756c3f680fd', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 24, '내용추론', '독해/사실확인', true, '2', '글쓴이는 처음에 버스를 놓쳐 걱정했으나, 차선책을 실행하면서 차선책도 훌륭하다고 했다.', 1),
('e714c8ee-1bcd-4070-b98b-dd80e2371a7f', 'e07b147b-77f7-46c4-9f67-d31ce7f5359e', 25, '내용일치', '독해/사실확인', false, 'train, strawberry, school, birthday', '글쓴이는 늦게 일어나서 버스를 놓쳐서 차선책으로 기차를 탔다. 빵집에서는 딸기 케이크를 살 수 없어서 대신 당근 케이크를 샀다. 나중에 우리는 사진관에 가서 교복을 입고 함께 사진을 찍었다. 그것은 멋진 생일 파티였고, 할머니는 매우 행복해 보이셨다.', 1),
('3d64b507-0749-4680-8386-40bcb20aca32', '80917643-fbc2-40e5-9b47-de6429e85c8e', 1, '어법', '문법/어휘', true, '3', 'the first bus를 위한 tickets이므로 to가 아닌 for를 사용한다. ‘~하는 것’은 「동사원형 + ing」의 형태로 나타낸다. strawberry cake가 3인칭 단수이므로 were가 아닌 was를 사용해야 한다.', 1),
('64e78d8d-5c8d-47e2-9cc0-f270a890f060', '80917643-fbc2-40e5-9b47-de6429e85c8e', 2, '내용일치', '독해/사실확인', true, '4', '① 나는 빵을 좋아한다. ② 나는 여가 시간에 유명한 빵집에 방문하는 것을 좋아한다. ③ 대전에 가는 것이 내 꿈의 여행이다. ④ 나는 많은 빵을 도시락에 넣을 것이다. ⑤ 내가 언제 대전에 가는지는 알 수 없다.', 1),
('9e571a61-812f-4539-90d7-222ae1fcf33a', '80917643-fbc2-40e5-9b47-de6429e85c8e', 3, '영작', '쓰기', false, 'I will try a special strawberry cake and take a baking class.', '‘~일[할] 것이다’라는 의미는 will로 표현할 수 있다.', 1),
('cf18925f-54a7-4641-bb76-41df46072762', '80917643-fbc2-40e5-9b47-de6429e85c8e', 4, '문장삽입', '글의흐름', true, '5', '‘우리 모두 행복했다.’는 감정을 나타내는 문장이므로 즐겁고 행복했던 일들이 있었는지 나열된 문장 이후에 들어가야 한다.', 1),
('99a57c3c-65c5-475f-b546-ce47f989ba74', '80917643-fbc2-40e5-9b47-de6429e85c8e', 5, '내용일치', '독해/사실확인', true, '1', '글쓴이의 가족이 멋진 선물을 산 것은 알 수 있지만 그것을 함께 풀어 보았다는 내용은 알 수 없다.', 1),
('429cd3cf-eab7-4ac2-83ce-cb2b6c617188', '80917643-fbc2-40e5-9b47-de6429e85c8e', 6, '어법', '문법/어휘', false, '(1) missed (2) wore', 'ⓐ 과거 일반동사와 접속사로 이어져 있으므로 miss의 과거 동사인 missed로 시제를 연결해야 한다. ⓑ 앞 문장이 과거 시제이므로 이어지는 문장도 wear의 과거 동사인 wore를 써야 한다.', 2),
('44f9cccd-53f6-4283-8bf6-b46ce04e4b02', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 1, '대화문', '화용/의사소통', true, '4', 'A는 박물관 가는 길을 묻고 있으므로 ② ‘그곳은 저녁 6시쯤 연다’는 응답은 적절하지 않다. ① 모퉁이에서 좌회전하세요. ② 그곳은 커피숍 옆에 있어요. ③ 우리는 카페에서 우회전해야 해요. ⑤ 직진하다가 빵집에서 오른쪽으로 도세요.', 1),
('71ab39ba-9177-44ce-9937-6b3548a2e229', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 2, '대화문', '화용/의사소통', true, '3', 'B의 답은 직진해서 한 블록 가고, 우회전하라는 의미로 상대방이 길을 물었을 때 답하는 표현이다. ③ ‘기차는 몇 시에 출발하나요?’는 기차 출발 시간을 묻는 표현이기에 B의 대답이 적절하지 않다. ① 빵집이 어디에 있나요? ② 카페에 어떻게 가나요? ④ 여기 근처에 옷 가게가 있나요? ⑤ 꽃 가게 가는 길을 알려줄 수 있나요?', 1),
('12de2402-9f01-4b2e-a3f3-7487e38337d3', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 3, '대화문', '화용/의사소통', true, '4', '소녀: 실례합니다, 박물관이 어디에 있나요? - ④ 직진하고 빵집에서 오른쪽으로 가세요. - ③ 감사합니다! 공원은 근처에 있나요? - 네, 그것은 박물관 옆에 있어요.', 1),
('fa17b2e0-c594-47cd-a739-94a4d91c87d4', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 4, '대화문', '화용/의사소통', true, '3', 'B의 ‘I’m so upset.(정말 속상해)’를 봤을 때 A의 말에 속상한 상황이 나와야 한다. ③은 ‘행사에서 상을 받았어’는 기분 좋은 상황이므로 적절하지 않다. ① 우리는 표를 구하지 못했어. ② 콘서트가 취소됐어. ④ 놀이공원이 오늘 문을 닫았어. ⑤ 내가 좋아하는 밴드가 공연하지 않아.', 1),
('8325eeac-b1ed-43d1-8815-f32cc2a4da5f', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 5, '어휘', '문법/어휘', false, '(d)isappointed', 'I’m disappointed.: 나는 실망했어.', 1),
('6b21dea5-4210-4e72-80f1-38c69a36a423', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 6, '영작', '쓰기', false, 'Where is the museum?', '「Where is + 장소 이름 ~?」: ~은 어디 있나요?', 1),
('a40b43b0-9a61-40af-a21e-41f6eb1e72f1', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 7, '어휘', '문법/어휘', true, '1', '소녀는 박물관에 가는 것이 I’m so excited!(정말 기대돼!)라는 기대를 나타내는 표현을 썼다. 대신할 수 있는 표현은 ① ‘정말 기대돼!’이다. ② 나는 걱정돼. ③ 나는 실망감을 느껴. ④ 나는 실망했어. ⑤ 나는 관심 없어.', 1),
('624dc9c1-3ed3-4a1e-b7b4-72aeebbb4304', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 8, '영작', '쓰기', false, 'How can we get there?', '길을 물어볼 때는 ‘~에 어떻게 가나요?’라는 의미로 「How can we get to + 장소?」 또는 「How do I get to + 장소?」으로 표현한다.', 1),
('fd677725-7d07-435f-af8e-6db89a2b8b44', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 9, '어휘', '문법/어휘', true, '5', 'take는 ‘(시간이) 걸리다’라는 의미이다.', 1),
('b32a6759-e89c-4932-90ff-37c5df32dd40', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 10, '내용일치', '독해/사실확인', true, '3', 'Alicia는 버스를 타지 않고 걸어서 무지개 폭포로 갈 것이다.', 1),
('84469799-a5da-4e63-b92c-e69848df6ab9', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 11, '대화문', '화용/의사소통', true, '4', '소녀: 여기 근처에 있는 맛있는 빵집을 아니? 나는 빵을 좀 사고 싶어. ⓒ 응, Sky 빵집이 정말 맛있어. ⓓ 잘됐다. 그것은 어디에 있어? ⓐ 한 블록 직진해서 오른쪽으로 돌아. 오른쪽에 있어. ⓑ 아주 가깝네, 고마워.', 1),
('957a6fef-e0c3-4c5d-b142-191cd4bd565d', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 12, '내용일치', '독해/사실확인', true, '5', '① 소년이 박물관을 찾고 있다. ② 소년이 찾고 있는 곳은 박물관이다. ③ 여자가 소년에게 길을 안내하고 있다. ④ 소년과 여자가 함께 박물관에 가는지는 언급되어 있지 않다.', 1),
('5920ab84-25c8-43a5-b818-d553f8ae1085', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 13, '지칭', '논리/추론', false, 'at Star Restaurant', 'I''ll see you there.(거기서 만나요.)에서 there는 생일 파티가 열리는 장소인 at Star Restaurant를 가리킨다.', 1),
('9c1d78d5-ccd1-491b-9611-cc0c4839cd93', 'a92847ac-9fbb-46b4-a166-76c7627a090c', 14, '제목요지', '주제파악', true, '1', 'Come to my birthday party!(제 생일 파티에 오세요!)를 통해 생일 파티에 초대하는 글이라는 것을 알 수 있다.', 1),
('d8f0fda7-0ff0-4a9a-b175-a096c6016ae2', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 1, '대화문', '화용/의사소통', true, '3', '③ A는 ‘여기 근처에 서점이 있나요?’라고 길을 묻고 있는데, B는 ‘나는 실망감을 느껴.’라고 답을 하여 어색한 대화이다. ① A: 실례합니다. 도서관이 어디에 있나요? B: 모퉁이에서 오른쪽으로 도세요. ② A: 박물관에는 어떻게 가나요? B: 두 블록 직진하세요. ④ A: 내일 콘서트가 너무 기대돼! B: 나도! 기다릴 수 없어. ⑤ A: 가족 여행이 정말 기대돼. B: 정말 좋겠다! 즐거운 시간 보내.', 1),
('9790c250-f476-4877-a2cb-ac465126a3ed', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 2, '대화문', '화용/의사소통', true, '1', '빈칸 ⓐ의 경우, Alex가 매우 기대에 차 있어 보이고, 이어서 놀이공원에 갈 계획이라고 말하고 있기 때문에 ⓐ에는 ‘I can’t wait!(너무 기대돼!)’와 같은 기대감을 표현하는 문장이 들어가는 것이 가장 적절하다. 빈칸 ⓑ 다음에 A가 버스를 타고 15분이 걸린다고 답하여서 ⓑ는 놀이공원 위치와 거리를 묻는 ‘Is it near here?(여기서 가까워?)’ 질문이 가장 적절하다. ② - 나 정말 속상해. ③ - 나는 실망했어. ④ - 나는 낙담했어. ⑤ - 여기 근처에 버스 정류장이 있어?', 1),
('d29cfe1d-ebc9-45b4-a31c-056458e276e3', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 3, '문장삽입', '글의흐름', true, '3', '주어진 문장은 길을 물을 때 ‘어디에 있어?’라는 의미로, 카페 위치를 말해 주는 여자 응답 ‘2층으로 가서 오른쪽으로 돌아야 해.’ 전인 ③에 들어가는 것이 가장 적절하다.', 1),
('63c07b84-46e9-48d1-a345-ffd38fb9a407', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 4, '영작', '쓰기', false, 'Where will the concert take place?', '‘(행사 등이) 열리다’는 take place로 표현한다.', 1),
('70f0aabc-47e1-447f-af72-13a15c2d7af8', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 5, '내용일치', '독해/사실확인', true, '2', '소녀가 콘서트 표 2장이 있어서 소년에게 함께 가자고 했는데 소년이 콘서트에 가겠다고 대답하였다. ① 소녀는 여행을 위한 버스표 두 장을 가지고 있다. ② 콘서트는 토요일에 열린다. ③ 콘서트는 극장에서 열릴 것이다. ⑤ 콘서드는 오후 7시에 시작한다.', 1),
('596b0146-0c1f-43a2-905a-94c4c9236fe9', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 6, '글의순서', '글의흐름', true, '5', '⑤ Jason, 우리 한국 음식 먹어 보자. - ⓓ 좋아. 성발 기대돼! 식당은 어디에 있어? - ⓒ 우리는 두 블록 직진해서 오른쪽으로 돌아야 해. 그것은 왼쪽에 있어.', 1),
('0ca71369-12b4-44e6-b29f-97c8800701b0', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 7, '내용일치', '독해/사실확인', false, 'Jason[He] is excited because he will try Korean food.', '한국 음식을 먹는다고 하자, Jason은 성발 기대된다고 했다. 질문: Jason은 왜 기대하는가?', 1),
('b3c0cb93-b2cc-4a11-b627-53d1eb25cfb2', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 8, '대화문', '화용/의사소통', true, '1', '① 거기까지 어떻게 가야 하나요? ② 여기서 걸어갈 수 있어요. ③ 얼마나 시간이 걸릴까요? ④ 정말 기대돼요!', 1),
('e7f84bf0-c57d-4c7e-a3c7-4b607dfcc6ac', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 9, '내용일치', '독해/사실확인', false, 'Alicia goes to Rainbow Waterfall with Dad today.', '오늘 Alicia 아빠는 Alicia에게 무지개 폭포에 가자고 했다. 질문: 오늘 Alicia는 아빠와 어디에 가나요? 답변: Alicia는 오늘 아빠와 무지개 폭포에 간다.', 1),
('e4c85a60-501a-42df-8b11-ed582a52a292', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 10, '대화문', '화용/의사소통', true, '4', '지나는 콘서트에 함께 간다고 답했고, 이에 대한 민호의 반응으로 ‘정말 속상해’는 어색하며, ‘정말 기대돼’ 의미인 I’m so excited.로 바꿔 써야 적절하다.', 1),
('d3da8cbb-62f5-46ba-8284-a7e1ee0f8002', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 11, '영작', '쓰기', false, 'We have to take the bus and it takes', '해설 없음', 1),
('ce953358-919a-4c87-b305-33d7d6eda4f5', '34e6d49b-ef0d-4372-8908-4890accfb4bd', 12, '내용일치', '독해/사실확인', true, '2', '지나는 스타 팀을 매우 좋아한다고 했으므로 ② ‘지나는 스타 팀을 좋아하지 않는다’는 대화의 내용과 일치하는 설명이 아니다. ① 민호는 스타 팀을 매우 좋아한다. ③ 지나는 민호와 함께 스타 팀 콘서트에 갈 것이다. ④ 민호는 그 콘서트에 대해 기대하고 있다. ⑤ 콘서트장까지 가는 데 약 20분 걸린다. ⑥ 콘서트 후에 그들은 함께 햄버거를 먹을 것이다.', 1),
('e781a572-b026-4565-8faf-11c4e9afc8ba', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 1, '어법', '문법/어휘', true, '2', '동사 like 뒤에 목적어로 「동사원형 + -ing」 형태의 동명사를 취한다. 따라서 likes 뒤에는 walking이 들어가야 한다.', 1),
('d7e8dc20-27a3-4435-8891-865cbb1c6e5b', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 2, '어법', '문법/어휘', true, '2', '동명사가 문장 안에서 주어 역할을 할 때는 3인칭 단수로 취급해야 한다.', 1),
('23c10393-28ec-45cf-9e93-f4d52ea9948d', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 3, '어법', '문법/어휘', true, '3', '조동사 will 뒤에는 항상 동사의 원형이 와야 한다. ‘배드민턴을 치다’는 의미로 동사원형 play가 맞다.', 1),
('4bf1b6d5-ba37-4da2-be17-2a5d13928bfb', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 4, '어법', '문법/어휘', true, '5', '조동사 will 대신에 ‘~하려고 하다’의 의미인 be going to로 바꿔 쓸 수 있다. 나는 영화를 볼 것이다.', 1),
('178787b7-89a5-4902-8d2a-0bc21c0b4fa5', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 5, '어법', '문법/어휘', false, 'writing, reading', '첫 번째 빈칸은 동사 finished 뒤에 오는 목적어로, ‘일기를 쓰는 것’이라는 의미로 write의 동명사 writing이 들어가야 한다. 두 번째 빈칸은 동사 started 뒤에 오는 목적어로, ‘책을 읽기’라는 의미로 read의 동명사 reading이 들어가야 한다.', 1),
('9101a86b-4f3b-420c-9271-6e6305f41888', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 6, '어법', '문법/어휘', true, '2', '② 동사 eat를 동명사 eating으로 바꾸면 동사가 없는 문장이 되므로 잘못된 문장이 된다.', 1),
('f701f9e4-53d9-49bb-8843-f293bd4198af', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 7, '어법', '문법/어휘', true, '2', '①, ④ 조동사 will은 주어의 인칭 또는 수와 무관하게 「will + 동사원형」의 형태로 쓴다. ③ 조동사 will의 부정문은 「won’t[will not] + 동사원형」의 형태를 취한다. ⑤ will의 의문문은 「Will + 주어 + 동사원형~?」의 형태를 취한다.', 1),
('fbeb0c87-dab4-4af3-a089-a055f4c50eaf', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 8, '어법', '문법/어휘', false, 'She regrets not studying harder.', 'study의 동명사는 studying이고 동명사의 부정형은 「not + 동명사」의 형태를 취한다.', 1),
('570eedb4-b3ca-4950-b957-6ad048ed906d', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 9, '어법', '문법/어휘', true, '5', 'talk의 동명사 talking을 써야 하고, 문장이 과거형이므로 동사는 avoided를 사용해야 한다.', 1),
('fb94d690-59f2-433d-8eec-845e7cd1dead', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 10, '어법', '문법/어휘', false, 'won''t[will not] rain today, Will he call me later?', '조동사 will의 부정문은 ''won''t[will not] + 동사원형''의 형태를 취한다. 조동사 will의 의문문은 ''Will + 주어 + 동사원형~?''의 형태를 취한다. 지금 화상하다. 오늘은 비가 오지 않을 것이다. 그는 지금 바쁘다. 그가 나중에 전화할까?', 1),
('36af313f-f8dc-4452-a429-eadcf2395d37', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 11, '어법', '문법/어휘', true, '4', 'c. 동사 is의 보어로 동사 swim의 동명사 swimming이 들어가야 한다. 
f. enjoy의 목적어로 to play가 아니라 동명사 playing이 들어가야 한다. 
h. avoided의 목적어로 동사원형 make가 아니라 동명사 making이 들어가야 한다. 
a. 하루 종일 TV를 보는 것은 건강에 좋지 않다. b. 공원에서 산책하는 것이 어떨까? c. 내가 가장 좋아하는 취미는 호수에서 수영하는 것이다. d. 그녀는 친구들과 쇼핑 가는 것을 좋아한다. e. 우리는 학교 축제를 위해 춤 연습을 했다. f. 나는 책 읽기와 축구를 즐긴다. g. 그녀는 저녁 식사 전에 숙제를 끝마쳤다. h. 그들은 선생님과 눈을 마주치는 것을 피했다.', 1),
('b139f88a-dd2b-4679-88cb-e9155c1ba4d8', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 12, '영작', '쓰기', true, '2', '미래의 계획이나 예상을 나타낼 때 will 대신에 be going to를 쓸 수 있고, ‘쇼핑하러 가다’ 의미는 go shopping이다. 영작하면 She is going to go shopping with her friends.이므로 ★에 들어갈 말은 shopping이다.', 1),
('d78e47e6-39d4-4a73-a621-35550c86c422', '20cc22af-0649-4d9e-9810-506b7cd38bf9', 13, '어법', '문법/어휘', false, '(1) walking, in, the, park (2) not, cleaning, the, house (3) reading, a, book', 'ⓐ 민수가 아침 식사 전에 하는 활동은 ‘공원 걷기’이다. walk의 동명사 walking이 들어가야 한다. ⓑ ‘민수의 엄마와 민수는 집 청소를 안 하는 것을 싫어한다’는 의미로 동명사 cleaning의 부정형인 not cleaning이 들어가야 한다. ⓒ ‘자러 가기 전에 책 읽는 것을 끝낸다’고 하였으므로 read의 동명사 reading이 들어가야 한다. 민아: 너는 아침에 무엇을 하니? 민수: 나는 아침 식사 전에 공원에서 걷는 것을 즐겨. 민아: 정말 건강한 습관이다! 주말에 집 청소하는 것을 돕니? 민수: 응, 엄마랑 나는 방을 청소하지 않는 것을 정말 싫어해. 민아: 저녁에는 어떻니? 저녁 식사 후에 보통 무엇을 하니? 민수: 나는 잠자기 전에 책 읽는 것을 마무리해. 민아: 와, 정말 좋은 습관이다!', 3),
('964b8f42-c8b7-4161-b874-a9957deef9be', '4a766b7c-75f7-4007-af97-79dd674984ce', 1, '어법', '문법/어휘', true, '1', '첫 번째 빈칸의 경우 동사 is 앞에는 주어가 와야 하고 주어는 명사만 가능하므로 Hike의 동명사 Hiking을 사용해야 하며, 두 번째 빈칸에서는 ‘캠핑 가는 것을 즐긴다’는 의미로 enjoy 뒤에 목적어로 camp의 동명사 camping을 사용해야 한다. A: 주말에 하이킹하는 것이 내가 가장 좋아하는 활동이야. B: 재미있겠다! 나는 친구들과 캠핑 가는 것을 즐겨.', 1),
('19a66608-08ce-4aad-9968-bb8c3e994a10', '4a766b7c-75f7-4007-af97-79dd674984ce', 2, '어법', '문법/어휘', true, '4', '첫 번째 빈칸의 경우 ‘~하는 게 어때?’ 의미로 「How about + -ing?」 형태가 나와야 하므로 finishing을 사용해야 한다. 두 번째 빈칸의 경우 ‘~하려고 한다’ 의미로 「be going to + 동사원형」 형태가 나오므로 to 이하에는 동사원형인 do를 사용해야 한다. A: 저녁 먹고 숙제를 끝내는 게 어때? B: 나는 대신 내일 하려고 해.', 1),
('7f50c5b1-7f78-43b2-84b8-4e8b1d4101d4', '4a766b7c-75f7-4007-af97-79dd674984ce', 3, '영작', '쓰기', true, '3', '동명사의 부정형은 「not + 동명사」이므로 not listening으로 영작해야 한다.', 1),
('73bab82d-58c4-422d-9444-722d8c9aadab', '4a766b7c-75f7-4007-af97-79dd674984ce', 4, '어법', '문법/어휘', true, '3', '①, ⑤ will의 평서문은 「will + 동사원형」 형태이므로 ① watching이 아니라 watch, ⑤ finishes가 아니라 finish를 사용해야 한다. ② will의 부정문은 「will not[won’t] + 동사원형」 형태이므로 going이 아니라 go를 사용해야 한다. ④ will의 의문문은 「Will + 주어 + 동사원형~?」 형태이므로 to visit이 아니라 visit을 사용해야 한다.', 1),
('61081ccb-9167-48da-8999-5db7f8d9d4fb', '4a766b7c-75f7-4007-af97-79dd674984ce', 5, '영작', '쓰기', false, 'Will you watch a movie with me', 'will의 의문문은 「Will + 주어 + 동사원형~?」 형태로 물어본다.', 1),
('51f75205-e209-4e20-ad8f-b4d12af30b78', '4a766b7c-75f7-4007-af97-79dd674984ce', 6, '어법', '문법/어휘', true, '4', '④ will의 부정문은 「will not[won’t] + 동사원형」 형태이므로 visiting이 아니라 visit을 사용해야 한다.', 1),
('b0e3f253-273e-4051-af90-fadfed4953ec', '4a766b7c-75f7-4007-af97-79dd674984ce', 7, '영작', '쓰기', false, 'reading, writing, cleaning, playing, doing', '‘책을 읽는 것’이라는 의미로 reading books가 자연스럽고, ‘편지를 쓰는 것’이라는 의미로 writing a letter가 자연스럽고, ‘내 방을 청소하는 것’이라는 의미로, cleaning my room이 자연스럽고, ‘새로운 게임을 하는 것’이라는 의미로 playing a new game이 자연스럽고, ‘숙제하는 것’이라는 의미로 doing our homework이 자연스럽다.', 1),
('bc367716-bf26-4da9-8011-b6039ed7ec16', '4a766b7c-75f7-4007-af97-79dd674984ce', 8, '어법', '문법/어휘', true, '2', '조동사 will의 의문문은 「Will + 주어 + 동사원형 ~?」 형태로 물어본다. Emily는 내일 그녀의 조부모님을 방문할 것이다.', 1),
('d6fea979-bb25-4aa1-87d5-e1f89b25ac6b', '4a766b7c-75f7-4007-af97-79dd674984ce', 9, '어법', '문법/어휘', true, '5', 'ⓒ will의 의문문은 「Will + 주어 + 동사원형 ~?」 형태이므로 visits가 아닌 visit으로 고쳐 써야 한다. ① 나는 박물관을 방문할 것이다. ② 나는 내년에 해외에서 공부할 예정이다. ③ 오늘 밤 스파게티를 요리할 거니? ④ 나는 오늘 숙제를 하지 않을 것이다. ⑤ 너와 엄마는 내일 동물원을 방문할 거니?', 1),
('ff5c08b0-a6ba-4baa-90fd-1c482c2cdc7c', '4a766b7c-75f7-4007-af97-79dd674984ce', 10, '어법', '문법/어휘', true, '2', '④의 동명사 sharing my music with others가 주어 역할을 할 때는 3인칭 단수로 취급하기 때문에 동사는 makes를 사용해야 한다.', 1),
('91344dd5-206c-469a-a5e2-63cb06ae6006', '4a766b7c-75f7-4007-af97-79dd674984ce', 11, '영작', '쓰기', false, '(1) going, to, live (2) will, not, be (3) are, not, going, to, be', '(1) Lisa는 서울에서 살 것이므로, 「be going to + 동사원형」을 사용해서 밑줄 친 곳에는 going to live가 들어가야 한다. (2) Tom은 미래에 작가가 되지 않을 것이므로 will의 부정문 「will not + 동사원형」을 사용해서 밑줄 친 곳에는 will not be가 들어가야 한다. (3) Lisa와 Tom 모두 과학자가 되려고는 하지 않으므로 밑줄 친 곳에는 「be going to + 동사원형」의 부정형인 are not going to be가 들어가야 한다.', 3),
('39efd8b5-9e2c-4c2d-a4f4-511b9c3e11b1', '4a766b7c-75f7-4007-af97-79dd674984ce', 12, '영작', '쓰기', false, '(1) I will help you with your homework. (2) Will she visit her grandparents this weekend?', 'ⓒ will 다음에는 동사원형을 써야 한다. ⓔ will의 의문문은 「Will + 주어 + 동사원형 ~?」 형태로 쓴다. ⓐ 그는 나중에 너에게 전화할 것이다. ⓑ 그들은 내일 프로젝트를 끝낼 것이다. ⓒ 나는 네 숙제를 도와줄 것이다. ⓓ 그녀는 이번 일요일에 공원에 가지 않을 것이다. ⓔ 그녀는 이번 주말에 조부모님을 방문할 것인가?', 2),
('6726bceb-f488-44c7-a00d-e23a5e56adf6', '4a766b7c-75f7-4007-af97-79dd674984ce', 13, '영작', '쓰기', false, 'going shopping and collecting stamps', '쇼핑하러 가는 것''은 going shopping, ''우표 수집하는 것''은 collecting stamps로 표현한다.', 1),
('8bc854e9-4131-4154-80cb-cd9cad5c33e0', '5a573e22-18e8-4a7e-a20a-f7f1b88eef31', 1, '어법', '문법/어휘', false, 'take', '(행사 등이) 열리다''라는 의미를 나타낼 때 take place라는 표현을 사용하고, ''(시간이) 걸리다''라는 의미를 나타낼 때 「take + 시간」이라는 표현을 사용하고, ''(탈것에) 타다''라는 의미를 나타낼 때 「take + 이동수단」을 사용하므로 빈칸에 공통으로 들어갈 적절한 말은 take이다.', 1),
('351363a0-c74e-4c53-ab91-34426f6dba7f', '5a573e22-18e8-4a7e-a20a-f7f1b88eef31', 2, '어휘', '문법/어휘', true, '3', '특별한 날에 누군가에게 주는 것 → present (선물) ① 블록 ② 국수 ④ 표 ⑤ 스튜디오.', 1),
('96620ba0-14fd-4dc2-a04a-7d88b61096dc', '5a573e22-18e8-4a7e-a20a-f7f1b88eef31', 3, '어휘', '문법/어휘', true, '4', '④ succeed 성공하다 • 나는 여행을 통해 다양한 문화를 경험해. (experience 경험하다) • 방과후에 나는 소파에서 쉬는 것을 좋아해. (relax 휴식하다) • 직진해서 다음 모퉁이에서 좌회전하세요. (go straight 직진하다) • 건강을 위해 규칙적으로 운동해야 해. (exercise 운동하다)', 1),
('aafc6db6-81cf-4422-a002-3b20f80d98d2', '5a573e22-18e8-4a7e-a20a-f7f1b88eef31', 4, '어휘', '문법/어휘', false, 'early, in, the, morning', 'early in the morning 아침 일찍', 1),
('042a279d-d5d7-4903-9dc8-f9e7eaaccba1', '5a573e22-18e8-4a7e-a20a-f7f1b88eef31', 5, '어휘', '문법/어휘', true, '4', '④의 close는 ''가까운''이라는 의미로 쓰였다. ① 서둘러, 그렇지 않으면 버스를 놓칠 거야. (miss 놓치다) ② 그의 삼촌은 우주비행사이다. (astronaut 우주비행사) ③ 겨울에는 호수가 얼음처럼 차갑다. (icy 얼음같이 차가운) ⑤ 우리는 지난 주말에 박물관에 갔다. (museum 박물관)', 1),
('2597db78-f603-41ea-9358-a5d065263257', '5a573e22-18e8-4a7e-a20a-f7f1b88eef31', 6, '어휘', '문법/어휘', true, '2', 'ⓐ make plans for: ~의 계획을 세우다 ⓑ work out: 일이 잘 풀리다', 1),
('92c604a8-7175-425a-8231-d90d89bfaaa7', '5a573e22-18e8-4a7e-a20a-f7f1b88eef31', 7, '어법', '문법/어휘', false, 'quickly, interested, bakery', 'quick은 형용사로 ''빠른''이라는 뜻이고, quickly는 부사로 ''빠르게''라는 뜻이다. 문장을 수식하는 부사가 와야 하는 자리이므로 quickly가 적절하다. interesting은 ''흥미를 느끼게 하는''이라는 뜻이고, interested는 ''흥미를 느끼는''이라는 뜻이다. 놀이공원에 가자는 제안에 흥미가 느껴진다는 의미이므로 interested가 적절하다. bread는 빵이라는 명사이고, 빵을 파는 장소로 ''빵집''이라는 뜻의 bakery가 적절하다.', 1),
('efdce78e-51d4-4d4b-b532-98f232c2ee87', '8c745137-a7db-43f5-b21c-18c0af799035', 1, '어휘', '문법/어휘', true, '5', '지식을 주는 어떤 일이나 보는 것 → experience ① 나는 금요일에 시간이 있어, 그때 만나자. ② 우리 반과 함께한 현장 학습은 정말 재미있었어. ③ 그녀는 요리 실력으로 매우 유명해. ④ 내 아침 습관은 10분 동안 책을 읽는 거야. ⑤ 피터는 과학 박물관에서 좋은 경험을 했어.', 1),
('49a3b49c-94b4-4b90-bb7f-00760ef46a02', '8c745137-a7db-43f5-b21c-18c0af799035', 2, '어휘', '문법/어휘', false, 'ⓒ', 'ⓐ 도시 거리의 한 구역 → block (블록) ⓑ 책을 빌릴 수 있는 곳 → library (도서관)', 1),
('376ef873-2da3-4c12-83ae-91dc3359e89d', '8c745137-a7db-43f5-b21c-18c0af799035', 3, '어법', '문법/어휘', true, '1', '행복하게''라는 의미는 부사 happily이다. ① 그녀는 그를 사랑하고, 둘은 행복하게 산다. ② 그녀는 그 콘서트 티켓을 샀다. ③ 나는 화장실에서 손을 씻었어. ④ 그는 수업 중에 지루함을 느꼈다. 그래서 그는 잠들었다. ⑤ 그는 예술가이다. 그는 그림을 잘 그린다.', 1),
('87c4c8e2-8bb6-4ae8-94ef-56f1b6861c07', '8c745137-a7db-43f5-b21c-18c0af799035', 4, '어휘', '문법/어휘', false, 'exercise', 'exercise: 운동하다 ⓐ 운동 • 운동은 건강을 유지하는 데 중요해. • 나는 학교 가기 전에 매일 아침 운동을 해.', 1),
('461a5da6-198c-478a-a1df-b63799ce815f', '8c745137-a7db-43f5-b21c-18c0af799035', 5, '영작', '쓰기', true, '3', '버스 정류장''은 bus stop, ''제시간에''는 in time, ''놓치다''는 miss라는 표현을 사용하여 I didn''t get to the bus stop in time and missed the bus. 라고 영작한다.', 1),
('07fd1d33-5e1a-4d86-9c4b-9e47ff5944e9', '8c745137-a7db-43f5-b21c-18c0af799035', 6, '어법', '문법/어휘', false, 'ⓒ', 'ⓐ 폭포의 상대를 나타내는 형용사 ''얼음같이 차가운''이라는 뜻의 icy가 적절하다. ⓑ 어떠한 장소인지를 부연 설명해 주는 형용사 ''완벽한''이라는 뜻의 perfect가 적절하다. ⓒ 사람이 흥미로운 감정을 느끼는 상태이므로 접미사 -ed가 붙은 ''신이 난''이라는 뜻의 excited가 적절하다.', 1),
('03e34165-9e2b-4305-ba79-13160aa35d4b', '8c745137-a7db-43f5-b21c-18c0af799035', 7, '어휘', '문법/어휘', true, '3', '미래는 새로운 희망과 꿈을 가져다준다. (future: 미래) ① 규칙적으로 하는 것 (habit: 습관) ② 특정한 지역 또는 위치 (place: 장소) ③ 지금 이후에 오는 시간 (future: 미래) ④ 해결이 필요한 상황 (problem: 문제) ⑤ 금요일 저녁부터 일요일 밤까지의 시간 (weekend: 주말)', 1),
('f493367c-2c8d-4273-a7d5-772db4461364', '8c745137-a7db-43f5-b21c-18c0af799035', 8, '어휘', '문법/어휘', true, '3', 'place 상소, take place (행사 등이) 열리다 • 도서관은 시끄럽지 않아서 공부하기 좋은 장소이다. • 많은 축제가 가을에 열린다. 나는 가족과 함께 그 축제들을 즐긴다. ① 화장실 ② 가게 ③ 스튜디오 ⑤ 현장 학습', 1),
('89738942-a671-4fdd-82e0-908df0297d8c', '8c745137-a7db-43f5-b21c-18c0af799035', 9, '어휘', '문법/어휘', true, '2', 'take는 ''(시간이) 걸리다''라는 뜻과 ''(탈것에) 타다''라는 뜻을 가지고 있다. ① 지금 바로 택시를 타자. ② 그들은 여행을 위해 비행기를 탔어. ③ 그녀는 매일 아침 버스를 타. ④ 어젯밤 숙제하는 데 두 시간이 걸렸어. ⑤ 친구들과 나는 여행을 위해 기차를 타.', 1),
('db04431c-b7d5-4032-b4ed-e4d474e5f759', '8c745137-a7db-43f5-b21c-18c0af799035', 10, '어휘', '문법/어휘', false, 'next, to', 'next to: ~ 옆에', 1),
('7fb51009-cfe9-4c7e-9de4-a411e078d16c', '8c745137-a7db-43f5-b21c-18c0af799035', 11, '어휘', '문법/어휘', true, '2', '②의 upset과 happy는 반의어 관계이다. 나머지는 바꿔 쓸 수 있는 유의어 관계의 단어들이다. ① 우리는 이 문제를 빠르게 해결했다. (issue: 문제) ② 그녀는 경기에 져서 속상했다. (happy: 행복한) ③ 우리 가족은 캐나다로 여행을 계획했다. (journey: 여행) ④ 나는 멋진 생일 선물을 받았다. (gift: 선물) ⑤ 그녀는 가방을 사기 위해 가게에 갔다. (shop: 가게)', 1),
('026780b0-5a69-4ec5-a307-7713be5b0840', '8c745137-a7db-43f5-b21c-18c0af799035', 12, '어휘', '문법/어휘', false, 'local, tradition, volunteer, work, noodle, wonderful', 'local tradition 지역 전통, volunteer work 자원봉사, noodle 국수, wonderful 훌륭한, 멋진', 1),
('fdd08203-83e5-45d5-b99c-5ea347a8aa5c', '8c745137-a7db-43f5-b21c-18c0af799035', 13, '어법', '문법/어휘', true, '4', '명사 뒤에 접미사 -ist가 붙으면 특정 직업 또는 역할을 나타내는 단어가 된다. ⓐ의 florist(플로리스트, 꽃집 주인)는 artist(예술가)가 자연스럽다. ⓑ의 novelist(소설가)는 journalist(신문기자)가 자연스럽다.', 1),
('11a8def0-49ac-4c0f-ac4b-f3b4b1c15714', '8c745137-a7db-43f5-b21c-18c0af799035', 14, '어휘', '문법/어휘', false, 'museum, restaurant, tickets, concert', '• 음식을 먹는 장소 (restaurant: 식당) • 관람을 위한 음악 공연 (concert: 콘서트) • 역사적 또는 예술적 물건들을 볼 수 있는 장소 (museum: 박물관) • 장소에 들어가거나 서비스를 이용할 수 있게 해주는 종이 (ticket: 표)', 1),
('ce090608-f569-49a2-b8d8-4f91bd82ddf3', 'da680376-2abf-4418-b302-a874bb101302', 1, '어휘', '문법/어휘', true, '4', 'crime scene: 범죄 현상
① 경치, 풍경 ② 코드, 암호 ③ 표시, 흔적 ④ 현장, 장면 ⑤ 평화', 1),
('cbcbacf7-6313-4153-9aff-8a78d09dba6c', 'da680376-2abf-4418-b302-a874bb101302', 2, '어휘', '문법/어휘', true, '3', '③의 clearly는 ''분명하게''라는 의미로 쓰였다.
① 나는 오늘 나쁜 일이 일어나지 않기를 바란다.
② 나는 쇼핑몰에서 값비싼 시계를 찾았다.
③ 그녀는 학급에 그 의미를 분명하게 설명했다.
④ 그 영화는 너무 지루했다.
⑤ 창문에 돌을 던지지 마라.', 1),
('76f147e4-1150-4ab6-8272-4de0e1eb9085', 'da680376-2abf-4418-b302-a874bb101302', 3, '어휘', '문법/어휘', false, 'secret', '소수의 사람들만 아는; 다른 사람들에게 숨겨진 → secret (비밀의)
• 그는 그의 어린 시절에 관한 비밀 이야기를 공유했다.', 1),
('351bd144-ca2e-4c73-a622-75a6955739cb', 'da680376-2abf-4418-b302-a874bb101302', 4, '대화문', '화용/의사소통', true, '4', '④는 ''나의 개를 가게에 데려와도 될까요?''라는 의미로, 자신의 행동이나 계획에 대한 상대방의 허락을 구하는 표현이다.', 1),
('01f7a8f8-0228-401e-9d95-c2b854cb01f2', 'da680376-2abf-4418-b302-a874bb101302', 5, '영작', '쓰기', false, 'You must not bring pets inside.', '「must not + 동사원형~」: ~하면 안 된다', 1),
('74a3687f-70ad-40a7-82bf-06b43c0eacb2', 'da680376-2abf-4418-b302-a874bb101302', 6, '대화문', '화용/의사소통', true, '5', '영상물실에 가도 되는지 물어보는 소년의 질문에 가도 된다고 허락한 후 뛰지 말라는 당부를 하는 내용이 나와야 하므로, 허락의 의미를 나타내는 Of course., Sure., Yes, you may., Why not? 등의 표현이 들어가야 적절하다.', 1),
('320e7f6d-5341-44de-a013-c9cd7bc4d765', 'da680376-2abf-4418-b302-a874bb101302', 7, '내용일치', '독해/사실확인', true, '4', '소년은 아직 뛰지 않았으며, 엄마가 먼저 뛰지 말라고 충고하고 있다.', 1),
('4df99b36-f21d-48ed-90c4-09bf1a8a11d7', 'da680376-2abf-4418-b302-a874bb101302', 8, '어법', '문법/어휘', true, '2, 5', 'There was 뒤에는 단수 명사가 와야 한다. ② bread와 ⑤ sand는 불가산 명사이므로 단수 취급한다. ① balloon은 단수 명사이지만 some과 함께 쓰이려면 There were some balloons로 수 일치가 필요하다.
상자 안에는 약간의 ② 빵 ⑤ 모래가 있었다.', 1),
('4f057f35-c565-4879-aec5-900a225dc11b', 'da680376-2abf-4418-b302-a874bb101302', 9, '어법', '문법/어휘', true, '1', '② (difficultest → most difficult), 형용사 difficult의 최상급은 앞에 most를 씀
③ [were → was], 주어 someone이 단수이므로 was를 씀
④ [tallest → the tallest], 「the + 최상급」의 형태
⑤ [aren''t → isn''t], 주어 coffee가 셀 수 없는 명사이므로 isn''t를 씀
① 이 가방이 가장 덜 비싸다.
② 이것이 가장 어려운 질문이다.
③ 방에 누가 있었니?
④ 아버지는 우리 가족 중 가장 키가 큰 사람이다.
⑤ 마실 커피가 많지 않다.', 1),
('021a7829-407f-4979-bdb6-1f70eae50e92', 'da680376-2abf-4418-b302-a874bb101302', 10, '어법', '문법/어휘', true, '1', 'ⓐ [is → are], 주어 options가 복수이므로 be동사 are를 씀
ⓑ [better → best], 「the + 최상급」의 형태이므로, good의 최상급 best를 씀
ⓒ [most strong → strongest], 형용사 strong의 최상급은 뒤에 -est를 붙임
ⓐ 이번에는 가능한 선택지가 더 적다.
ⓑ 지금이 내 인생에서 가장 좋은 순간이다.
ⓒ 세상에서 가장 강한 남자는 누구인가?
ⓓ 이것보다 더 빨리 움직일 수 있니?
ⓔ 너의 아이디어는 모든 것들 중 가장 창의적이다.
ⓕ 작년보다 더 많은 학생이 있다.', 1),
('dbd9523f-a994-47ad-90d5-fca9b1528aa6', 'da680376-2abf-4418-b302-a874bb101302', 11, '어법', '문법/어휘', true, '2', '①와 ⑥의 「there + be동사」 구문의 주어가 모두 단수이므로, be동사 is를 쓴다.', 1),
('43b25b63-a40e-43f7-b6b6-6c1578cb68a0', 'da680376-2abf-4418-b302-a874bb101302', 12, '영작', '쓰기', false, 'It is the biggest of all the rooms.', '「the 최상급 + of + 비교 대상 복수 명사」의 형태로 쓴다.', 1),
('cd2b9b5e-1868-4f67-80bc-73dcd9098fb5', 'da680376-2abf-4418-b302-a874bb101302', 13, '영작', '쓰기', false, 'Jackson is the fattest cat of all. 또는 Jackson is the fattest of all cats.', '「the + 최상급 of ~」: ~중에서 가장 …한
형용사 fat의 최상급은 끝 자음 하나를 더 붙여서 fattest로 만든다.
• Jackson은 모든 고양이들 중 가장 뚱뚱하다.', 1),
('fc385bb2-10cd-4a18-a44e-2fdc08aa7ab7', 'da680376-2abf-4418-b302-a874bb101302', 14, '문장삽입', '글의흐름', true, '3', '주어진 문장은 ''그것은 그의 가방이었다.''라는 의미로 대명사 It이 그의 머리에서 떨어진 무언가(something)를 가리켜야 하므로 ③에 들어가는 것이 가장 적절하다.', 1),
('76ae6adc-3aec-4470-b491-c8f9d1a5610c', 'da680376-2abf-4418-b302-a874bb101302', 15, '어휘', '문법/어휘', true, '2', '①과 ②의 about은 ''약 ~''이라는 의미로 쓰였고, ①③④⑤는 ''~에 대한[대하여]''이라는 의미로 쓰였다.
① 우리가 가장 좋아하는 음식에 대해 이야기해 보자.
② 그들은 약 1시간쯤 기다렸다.
③ Bella는 방학 동안의 그녀의 여행에 대해 이야기했다.
④ 나는 숙제에 대해 질문이 있다.
⑤ Harry가 나에게 주말 계획에 대해 물었다.', 1),
('91bd88a3-b977-49a8-b306-e29506c74355', 'da680376-2abf-4418-b302-a874bb101302', 16, '영작', '쓰기', false, 'he was a little taller than me', '「비교급 + than ~」: ~보다 더 …한
a little: 조금, 약간', 1),
('928f0691-e885-4450-98e8-514dc7bc3e3d', 'da680376-2abf-4418-b302-a874bb101302', 17, '어휘', '문법/어휘', true, '2', '② run away: 도망치다, 달아나다
④ run after: ~를 쫓아가다, 추격하다', 1),
('7bfa893c-c6df-4c5b-8971-6b4f3f4c1e26', 'da680376-2abf-4418-b302-a874bb101302', 18, '어휘', '문법/어휘', true, '3', '③ fall off: ~에서 떨어지다 (fell은 fall의 과거형)', 1),
('6c7b51a2-c7c1-4d2a-9bc3-960dd7c15eed', 'da680376-2abf-4418-b302-a874bb101302', 19, '내용일치', '독해/사실확인', true, '2', '범인이 휠체어 앞에 서 있었고, 매우 빨리 날렸다고 했다.', 1),
('9a6dc71a-ba81-4eb5-b944-f4d5ca621cfb', 'da680376-2abf-4418-b302-a874bb101302', 20, '어휘', '문법/어휘', true, '5', '⑤의 앞에서 많은 다른 종류의 케이크가 있는데 그날은 한 개만 받았다고 했으므로, 그를 분명하게 ''잊었다(forgot)''가 아닌 ''기억하다(remember)''가 와야 적절하다.', 1),
('6b29e925-058e-4b95-bb38-8be4714e6e0c', 'da680376-2abf-4418-b302-a874bb101302', 21, '빈칸추론', '논리/추론', true, '3', '케이크 조각들이 그림 곳곳에 있었다''라는 의미가 들어가야 하므로, 빈칸에는 all over가 적절하다.
① 전반적으로 ② 결국 ③ 곳곳에, 전체에 ④ 사이에 ⑤ 저기에', 1),
('04771b20-6b2f-445e-bdba-6b3e89b7634f', 'da680376-2abf-4418-b302-a874bb101302', 22, '어휘', '문법/어휘', true, '4', 'next to: ~의 옆에
① 휠체어 위에
② 휠체어 아래에
③ 휠체어 뒤에
⑤ 휠체어 앞에', 1),
('2babe043-0124-4c01-ac6f-7da18583b2e3', 'da680376-2abf-4418-b302-a874bb101302', 23, '내용일치', '독해/사실확인', true, '2, 4', '①③⑤는 글에서 알 수 없다.
① 그는 제빵사이다.
② 그는 파란 눈을 가지고 있다.
③ 그는 케이크를 좋아하지 않는다.
④ 그는 스페인어를 할 줄 모른다.
⑤ 그는 2개 이상의 언어를 말할 수 있다.', 1),
('002c1c9d-5b30-4be3-a96d-4c0c77f60acd', 'da680376-2abf-4418-b302-a874bb101302', 24, '어법', '문법/어휘', false, 'the smallest', '「the + 최상급」: 가장 …한', 1),
('2910b29e-5a08-4808-90af-91507b24703c', 'da680376-2abf-4418-b302-a874bb101302', 25, '내용추론', '독해/사실확인', false, '[예시답안] ''모나리자'' 그림에 던질 케이크를 사기 위해', '경비원의 신고에서 그림에 던진 Camila 빵집 케이크 상자를 발견했고, 빵집 주인이 그 케이크를 남자에게 팔았다고 했다. 질문: 범인은 왜 Camila 빵집을 방문했는가?', 1),
('df0ceeff-4ad4-4f27-962a-41c141e0176c', '1a6df917-1826-4acc-bb55-f4f627665091', 1, '어법', '문법/어휘', true, '2', 'ⓐ throw A at B: B에 A를 던지다 ⓓ look at: ~을 보다', 1),
('e03dd7fc-2704-4a06-8afd-e713df2c200d', '1a6df917-1826-4acc-bb55-f4f627665091', 2, '어법', '문법/어휘', false, 'There were four eyewitnesses.', '「there + be동사」: ~가 있다. 주어(four eyewitnesses)가 복수이며 과거이므로 be동사 were를 써야 한다.', 1),
('d99cae1f-62a9-48e1-9e52-81f9c6c4b5b2', '1a6df917-1826-4acc-bb55-f4f627665091', 3, '지칭', '논리/추론', true, '5', 'ⓑ가 포함된 문장은 ''그들은 무엇이라고 말했을까?''라는 의미이므로, 대명사 they는 앞에서 언급된 ''범인을 본 목격자들''을 가리킨다.', 1),
('7cf77b63-2a99-4ffb-a799-01877695a30b', '1a6df917-1826-4acc-bb55-f4f627665091', 4, '어휘', '문법/어휘', true, '4', '다음''을 읽어보라는 의미로 빈칸에는 명사인 ④ following이 들어가는 것이 적절하다. * follower: 추종자', 1),
('e73aa5ce-baa2-489b-a71d-8c0af97e94c5', '1a6df917-1826-4acc-bb55-f4f627665091', 5, '어법', '문법/어휘', true, '2', '의문사 who가 주어로 쓰인 과거형 문장은 「Who + 동사의 과거형 + 목적어 ~?」의 형태로 문장을 만든다.', 1),
('cce618d0-f692-4717-886b-8733d35a97dd', '1a6df917-1826-4acc-bb55-f4f627665091', 6, '어휘', '문법/어휘', false, 'criminal', '범죄를 저지른 사람 → criminal (범인, 범죄자)', 1),
('8d286c31-0768-4cc5-96db-3cf5a7bcd62c', '1a6df917-1826-4acc-bb55-f4f627665091', 7, '글의순서', '글의흐름', true, '2', '글의 마지막에서 다음 용의자들의 정보를 보고 누가 ''모나리자''에 케이크를 던졌는지 묻는 말이 나오므로, 다음에는 용의자들의 특징에 대한 진술이 이어지는 것이 적절하다.', 1),
('fa527517-81b6-4d17-95a3-b1031249461b', '1a6df917-1826-4acc-bb55-f4f627665091', 8, '어휘', '문법/어휘', false, 'visitor', '누군가 또는 무언가를 보기 위해 어떤 장소에 가는 사람 → visitor (방문객)', 1),
('da92034f-6696-4fde-8091-420656176712', '1a6df917-1826-4acc-bb55-f4f627665091', 9, '어법', '문법/어휘', true, '5', '⑤ 앞에 주어와 be동사가 나와 있으므로, ⑤에는 과거 진행형을 만드는 동사원형-ing 형태가 적절하다.', 1),
('29908a57-6988-45bf-8a48-196522f1460a', '1a6df917-1826-4acc-bb55-f4f627665091', 10, '어법', '문법/어휘', true, '4', '@ 그림에 케이크를 던진 것이므로 전치사 at이 적절하다. ⓑ turn around: 뒤돌아보다', 1),
('1c9f2db1-b9e1-40b2-a088-ac68324e822b', '1a6df917-1826-4acc-bb55-f4f627665091', 11, '어휘', '문법/어휘', true, '3', 'in front of: ~ 앞에', 1),
('5458c6fc-4400-4a72-b2bc-e6e1a791a525', '1a6df917-1826-4acc-bb55-f4f627665091', 12, '영작', '쓰기', false, 'I''m about 170 cm tall', 'about + 숫자: 약 ~ be동사 + 키(수치) + tall: 키가 ~이다', 1),
('021bcf75-8aeb-4a15-ab56-15ffa3912ce7', '1a6df917-1826-4acc-bb55-f4f627665091', 13, '내용일치', '독해/사실확인', true, '3', '③ 그는 키가 170cm인 Ann보다 조금 더 크다고 했다. ① 그는 케이크를 좋아하지 않는다. ② 그는 걸을 수 없다. ③ 그는 키가 170cm가 넘는다. ④ 그는 Ann보다 어리다. ⑤ 그는 그림 그리는 것을 좋아한다.', 1),
('47886439-da71-4229-8419-3a9957d88ebb', '1a6df917-1826-4acc-bb55-f4f627665091', 14, '영작', '쓰기', false, 'An old man with gray hair was running away', '회색 머리의''라는 말은 전치사 with를 사용하여 with gray hair로 표현하며, ''달아나다''라는 뜻은 run away를 사용한다.', 1),
('82d0d11e-349e-4e3c-80ae-cd79661ef37c', '1a6df917-1826-4acc-bb55-f4f627665091', 15, '지칭', '논리/추론', false, '가발', '무언가(something) 그의 머리에서 벗어졌고 뒤에 이어진 문장 It was his wig.에서 그것은 그의 가발이었다고 말하고 있다.', 1),
('5894cb85-d3bf-4275-a3b8-b966c2c1f513', '1a6df917-1826-4acc-bb55-f4f627665091', 16, '어휘', '문법/어휘', true, '4', '④에는 ''사실은''이라는 의미의 In fact가 어울리며, finally는 ''마침내''라는 뜻으로 글의 흐름에 맞지 않다. ① fall off: ~에서 떨어지다 ② run after: ~를 쫓아가다 ③ 비교급 than ~: ~보다 더 …한 ⑤ with 뒤에 신체적 특징이 나오면 ''~을 가진, ~인''이라는 의미이다.', 1),
('555b1112-89cf-4e04-9fe6-ea87b94f04a4', '1a6df917-1826-4acc-bb55-f4f627665091', 17, '어법', '문법/어휘', true, '2, 5', '의 ''~할 수 없었다''는 과거 시제이므로 조동사 can의 과거형 could를 사용하여 「couldn''t + 동사원형」 또는 「wasn''t able to + 동사원형」의 형태로 쓸 수 있다.', 1),
('f9c9103d-b587-4dc7-8670-fb40c3a578d2', '1a6df917-1826-4acc-bb55-f4f627665091', 18, '어휘', '문법/어휘', true, '4', '① 정보나 의견을 제공하는 말이나 글 → statement (진술, 서술) ② 소통하는 데 사용되는 낱말들의 체계 → language (언어) ③ 무언가의 더 큰 부분에서 잘라낸 양 → piece (조각, 부분) ④ 위험을 경계하거나 재산을 보호하는 사람 → guard (경비원, 경호원) ⑤ 어떤 것이 왜 그러한지 설명해주는 사실 → reason (이유, 근거)', 1),
('cfa4e2bc-ce78-41d6-bf7e-79a0efd38f65', '1a6df917-1826-4acc-bb55-f4f627665091', 19, '글의순서', '글의흐름', true, '3', '(B)에서 그림 곳곳에 케이크가 묻어 있었다는 이야기를 한 뒤, (A)에서는 사건 현장의 또 다른 모습을 묘사하고 있다. 그리고 나서 (C)에서는 (A)에서 발견한 a cake box에 대해 부가 설명을 하고 있으므로, 올바른 순서는 (B)-(A)-(C)이다.', 1),
('453cdea0-b728-4511-a027-f8dd12576e69', '1a6df917-1826-4acc-bb55-f4f627665091', 20, '어법', '문법/어휘', true, '2', '⑤ 주어가 a wheelchair로 단수이며 과거시제이다. ⓒ 주어가 pieces of cake로 복수이며 과거시제이다.', 1),
('06525b1b-fa40-4d4b-82b7-35b24cca75ff', '1a6df917-1826-4acc-bb55-f4f627665091', 21, '내용추론', '독해/사실확인', true, '3', '그림에 던져진 케이크가 들어 있던 상자를 범인이 서 있던 휠체어 옆에서 찾았고, 그것이 Camila 빵집에서 온 것이라고 했으므로, ③ ''범인은 Camila 빵집에서 케이크를 샀다''고 추론할 수 있다.', 1),
('d637b14b-b97b-40f7-840f-2fea488f3527', '1a6df917-1826-4acc-bb55-f4f627665091', 22, '어휘', '문법/어휘', true, '2, 5', '③ last Friday: 지난 금요일 ⓒ different: (서로) 다른 ④ the smallest one: 가장 작은 것', 1),
('390e3615-8b90-4352-b56f-58f2355972f4', '1a6df917-1826-4acc-bb55-f4f627665091', 23, '영작', '쓰기', false, 'I spoke to him in Spanish', '「in + 언어」: ~로', 1),
('788250fc-77f1-41f5-bc19-882864de2155', '1a6df917-1826-4acc-bb55-f4f627665091', 24, '빈칸추론', '논리/추론', true, '2', 'only: 오직, ~만 (B) 앞에서 Camila가 그 남자에게 스페인어로 말했을 때 이해하지 못했다고 했으므로, 그 남자는 영어로''만'' 말했다는 내용이 자연스럽다. (C) 그날 케이크를 단 한 개''만'' 팔았다는 내용이므로 only가 들어가는 것이 적절하다.', 1),
('5e24a769-f16f-43d7-8bf8-7240aa038fa3', '1a6df917-1826-4acc-bb55-f4f627665091', 25, '내용일치', '독해/사실확인', true, '3', '③ 가게에 많은 종류의 다른 케이크들이 있었지만 남자는 가장 작은 것을 사 갔다고 했다.', 1),
('e82d7f5d-797d-4078-94d0-8e2440926f57', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 1, '어법', '문법/어휘', false, 'Who threw a cake at the Monalisa?', '의문사 who가 주어로 쓰인 과거시제 의문문은 「Who + 과거형 동사 + 목적어 ~?」의 순으로 쓴다.', 1),
('bcab39ad-5f3d-418f-ae0c-903dbf451aac', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 2, '어법', '문법/어휘', true, '3', '지억이나 공간 내''라는 의미의 in(~에)을 사용한다. 도시와 나라 이름을 동시에 표기할 때는 「in + 도시 이름, 나라 이름」 순으로 쓴다.', 1),
('c20ae67c-925f-4869-978c-09cba7501356', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 3, '어휘', '문법/어휘', true, '4', '① 사람이 얼마나 키가 큰지 → height (키) ② 범죄를 저지른 사람 → criminal (범인, 범죄자) ③ 범죄를 저지른 것으로 추정되는 사람 → suspect (용의자) ④ 무언가 일어나는 것을 직접 눈으로 본 사람 → eyewitness (목격자) ⑤ 어떤 표면에 붙이는 인쇄된 지시문, 공지, 또는 경고 → sign (표시, 표지판)', 1),
('a1aad3d8-355a-4407-af4a-54e9c23b3cfb', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 4, '내용일치', '독해/사실확인', true, '4', '글에서 네 명의 목격자들이 있다고 했으며, ''그들이 무엇이라고 말했을까?''라는 질문 뒤에 ''다음을 읽고~''라는 말이 이어지므로, ④에 해당하는 내용은 ②이다.', 1),
('4fa38f4e-79b6-41e5-81c4-08b36240a1c4', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 5, '어법', '문법/어휘', false, 'was, were', 'There was four eyewitnesses.에서 주어가 복수이므로 was를 were로 고쳐야 한다.', 1),
('3c482187-428e-4b38-b772-0fe402d0ffde', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 6, '내용일치', '독해/사실확인', true, '3', '범인의 나이는 글에서 알 수 없다. ① 사건이 언제 벌어졌는가? (→ 지난 토요일) ② 사건이 어디에서 벌어졌는가? (→ 콜롬비아 Bogota의 Botero 박물관 내부) ③ 범인은 몇 살인가? (→ 알 수 없음) ④ 범인은 그림에 무엇을 던졌는가? (→ 케이크) ⑤ 목격자는 몇 명인가? (→ 4명)', 1),
('07b80bab-73be-4ed1-9886-d5502b7b6f3a', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 7, '어법', '문법/어휘', true, '3', '①②④⑤는 모두 주어가 단수이므로 be동사 was가, ③은 주어가 pieces of cake(케이크 조각들)로 복수이므로 be동사 were가 들어가야 한다.', 1),
('d201d023-069d-4cde-9280-6dabe791684b', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 8, '어휘', '문법/어휘', true, '5', '⑤ next to the wheelchair는 ''휠체어 옆에''라는 의미이다. next to: ~ 옆에', 1),
('6c74daf4-15e6-4ba1-b1df-c6c749bdf8cd', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 9, '어법', '문법/어휘', true, '2', '비교급 + than ~」은 ''~보다 더 …한''이라는 의미이며 tall의 비교급은 taller로 쓴다. ''약간, 조금''은 a little로 나타낼 수 있다.', 1),
('f832448b-4943-4d1f-a8c0-a41219febd6d', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 10, '빈칸추론', '논리/추론', true, '1', '사건이 벌어진 장소에 갔다는 말이 들어가야 하므로, ①이 가장 적절하다. ① 범죄 현장 ② 다른 박물관 ③ 경찰서 ④ Camila 빵집 ⑤ 범인의 집', 1),
('37824e2b-3438-4150-957f-f9611cac55c8', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 11, '내용일치', '독해/사실확인', false, 'Camila''s. Bakery', '경비원 Diego는 사건 현장의 휠체어 옆에서 케이크 상자를 발견했고, 그것은 Camila 빵집에서 온 것이라고 했다. 질문: 그 케이크는 어디에서 왔는가?', 1),
('98a3912c-798b-4820-869f-77dfdd59e9ce', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 12, '내용추론', '독해/사실확인', true, '3', '③ 범인이 던진 케이크 상자가 사건 현장에서 발견되었고, 그 상자가 Camila 빵집에서 온 것이라고 했다. ① 범인의 키는 180cm가 넘는다. ② 범인은 종종 Camila 빵집에 간다. ③ 범인은 Camila 빵집에서 케이크를 샀다. ④ Camila 빵집은 박물관과 매우 가깝다. ⑤ 범인은 케이크 상자에 지문을 남겼다.', 1),
('d2c1e472-1120-494c-b6cc-c108458cd5dd', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 13, '어휘', '문법/어휘', true, '2', '② ''그의 머리에서 떨어지다''라는 의미로 (fell) off가 들어가야 한다. fall off: ~에서 떨어지다 fall on: ~로 떨어지다', 1),
('373d8556-9212-455d-843f-2608c7f1d773', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 14, '어법', '문법/어휘', true, '2', '④ ''~보다''라는 의미의 than이 나오므로 비교급이 들어가야 하며, fast의 비교급은 faster이다. ③ ''가장 …한''이라는 의미의 the + 최상급을 써야 하며, small의 최상급은 smallest로 쓴다.', 1),
('87758538-adaa-4307-9961-f28cb53aaa0d', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 15, '빈칸추론', '논리/추론', true, '1, 2', '그 노인이 자신보다 빨랐다고 한 뒤, 노인이 아니라 젊은 남자였다는 말이 이어지므로 ''사실은''이라는 의미의 ①과 ②가 들어가는 것이 적절하다. ③ 특히 ④ 게다가 ⑤ 예를 들어', 1),
('06226ace-12db-4b6e-b95c-0ac74d0b9304', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 16, '빈칸추론', '논리/추론', true, '3', 'He was a young man with ⓐlong brown hair.', 1),
('d55834fc-b545-4f7d-ac07-3ca1e45abdf3', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 17, '어휘', '문법/어휘', false, 'Spanish', 'Spain이라는 나라 이름에 어미 -ish를 붙여 ''~언어, ~나라 사람''이라는 의미로 쓴다. 해당 문장은 ''나는 그에게 스페인어로 이야기했다.''라는 의미이다. → Spanish (스페인어, 스페인 사람)', 1),
('803859de-98d8-4b06-9c97-682fb834e1f4', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 18, '내용일치', '독해/사실확인', true, '4', '① 노인이 쓴 가발의 길이가 얼마나 되는지는 글에서 언급되지 않았다. ① 빵집의 주인은 누구인가? (→ Camila Santos) ② 젊은 남자는 스페인어를 이해했나? (→ 이해하지 못함) ③ 젊은 남자의 눈은 어떤 색이었나? (→ 파란색) ④ 노인이 쓴 가발은 얼마나 길었나? (→ 알 수 없음) ⑤ Camila는 그날 케이크를 몇 개 팔았는가? (→ 한 개)', 1),
('a99234ab-b1df-4e03-a942-65d5f1daff60', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 19, '내용일치', '독해/사실확인', false, 'He spoke only English.', '그 남자는 영어로만 말해서 Camila의 말을 이해하지 못했다고 했다. 질문: Camila가 그에게 말할 때 그는 왜 이해하지 못했나?', 1),
('61a10551-bea8-4080-a4fe-74f121e98392', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 20, '어휘', '문법/어휘', true, '2, 4', '⑤ eyewitness: 목격자 ④ suspect: 용의자', 1),
('e317abb3-c2a2-46d3-bb7a-f5b199c3c876', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 21, '어법', '문법/어휘', true, '3', '③[was→did], 일반동사 say가 쓰인 의문사가 있는 과거 의문문은 「의문사+did+주어+동사원형~?」의 형태로 쓴다.', 1),
('5e4b5300-da05-4de3-90a8-d46c8142edba', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 22, '어휘', '문법/어휘', false, 'Language', '소통하는 데 사용되는 낱말들의 체계 → language (언어)', 1),
('a8939462-e4ec-45c2-b432-7822b8a7d8fa', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 23, '내용일치', '독해/사실확인', true, '2', '위 표의 목격자 진술에 모두 해당하는 범인은 글에서 ② Larry Johnson이다.', 1),
('16fbb25d-d4c9-4c03-97fd-c94c24d6e0c7', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 24, '제목요지', '주제파악', true, '3', '누군가가 ''모나리자'' 그림에 케이크를 던진 사건을 소개하면서 용의자의 정보를 알려주고 있으므로, ③이 글의 목적으로 가장 적절하다. ① Botero의 예술 스타일을 이야기하기 위해 ② 범죄 사건의 목격자들을 나열하기 위해 ③ 용의자들에 대한 정보를 제공하기 위해 ④ ''모나리자''의 중요성을 설명하기 위해 ⑤ Botero 박물관의 역사를 이야기하기 위해', 1),
('1bc94df8-b44f-41c0-82eb-36b82e44a06b', '93de8373-8bb9-4de9-bf0d-86e6f70677c6', 25, '내용일치', '독해/사실확인', false, 'He threw a cake at the Monalisa.', '범인은 ''모나리자''에 케이크를 던졌다고 했다. 질문: 범인은 어떤 범죄를 저질렀는가?', 1),
('5dcc10fb-f23b-426b-83e7-4f330137ac5a', '4236b15d-6bca-40ec-aac3-cded50635d08', 1, '어휘', '문법/어휘', true, '5', 'turn around: 뒤돌아보다
• 성지 표지판을 본 후, 그들은 뒤돌아서 돌아갔다.
② turn in: 제출하다 ③ turn out: 나타나다 ④ turn down: 거절하다 ⑤ turn on: 켜다', 1),
('ddeb9a2f-e3cd-45ce-b838-df4ad3d553c8', '4236b15d-6bca-40ec-aac3-cded50635d08', 2, '어휘', '문법/어휘', false, 'The street was empty that night.', '아무것도 보유하거나 포함하지 않은 ↔ empty (빈, 비어 있는)', 1),
('0f5aeead-1269-4734-b3ff-4474c6bbe04f', '4236b15d-6bca-40ec-aac3-cded50635d08', 3, '어휘', '문법/어휘', true, '3', 'catch: (동) 잡다, 받다
• James는 3개 언어를 말할 수 있다. (speak: (동) 말하다)
• 우산을 가져오세요. 비가 올 거예요. (bring: (동) 가져오다)
• 쓰레기를 땅에 버리지 마세요. (throw: (동) 던지다, 버리다)
• 다음 단어들을 읽을 수 있나요? (following: (형) 다음, 다음의)', 1),
('9c2e368a-9939-4ea4-a245-d06e8e112908', '4236b15d-6bca-40ec-aac3-cded50635d08', 4, '어법', '문법/어휘', true, '2, 4', '② [terrible → terribly], 형용사 sorry를 수식하는 부사의 형태가 와야 한다.
④ [Texted → Texting], 문장의 주어로 쓰였으므로, 동명사의 형태가 와야 한다.', 1),
('31ab7ea6-7fc2-4887-8b64-58f9316f8ac7', '4236b15d-6bca-40ec-aac3-cded50635d08', 5, '어법', '문법/어휘', true, '2', 'ⓐ ‘전화를 하면 안 된다’라는 의미의 must not이 들어가야 한다.
ⓑ ‘(휴대폰을 끌) 필요가 없다’라는 의미의 don’t have to가 들어가야 한다.', 1),
('82633603-b437-42a2-846d-bcf336616d7f', '4236b15d-6bca-40ec-aac3-cded50635d08', 6, '내용일치', '독해/사실확인', true, '1', '문자를 하는 것은 괜찮다고 했으므로, ①이 대화의 내용과 일치한다.
① 소년은 여기에서 문자 메시지를 할 수 있다.
② 소년은 여기에서 전화 통화를 할 수 있다.
③ 소년은 문자보다 대화를 더 좋아한다.
④ 여자는 소년에게 그녀에게 문자를 보내달라고 요청한다.
⑤ 소년은 이제 휴대폰을 꺼야 한다.', 1),
('d0aa905f-bad3-47de-ab4c-cbdb0429cc24', '4236b15d-6bca-40ec-aac3-cded50635d08', 7, '영작', '쓰기', false, 'You must not ride a bike here.', '‘여기에서 자전거를 탈 수 있나요?’라고 허락을 구하는 질문에 ‘아니요, 안 됩니다.’라고 말한 후, ‘여기에서 자전거를 타면 안 됩니다.’라는 문장이 나와야 한다.', 1),
('f59bf3ae-a93d-4ba5-b71a-5081af843d51', '4236b15d-6bca-40ec-aac3-cded50635d08', 8, '어법', '문법/어휘', true, '1, 4', 'ⓐ [→ the most beautiful], 최상급 앞에는 the를 쓰며, beautiful의 최상급은 앞에 most를 붙인다.
ⓓ [→ There were], ‘~이 있다’는 의미로 「there + be동사」의 형태를 쓰며, 뒤의 주어 leaves(잎들)가 복수이므로, be동사 were를 쓴다.
① 그것은 이 매장에서 가장 아름다운 드레스이다.
② Sam은 다른 선수들보다 축구를 더 잘한다.
③ 주방 선반에 밀가루가 더 있니?
④ 땅에 나뭇잎이 몇 개 있었다.
⑤ 그녀는 우리나라에서 가장 유명한 배우이다.', 1),
('b3358357-e853-4ffc-a797-9e4d6ae95136', '4236b15d-6bca-40ec-aac3-cded50635d08', 9, '영작', '쓰기', false, 'is the most expensive of', '가방의 가격이 가장 비싸므로, 「the 최상급 + of + 비교 대상의 복수 명사」의 형태로 쓴다.
• 그 가방이 모든 품목 중에 가장 비싸다.', 1),
('f80ee15e-ce9b-4999-9bde-1db3df596c4d', '4236b15d-6bca-40ec-aac3-cded50635d08', 10, '내용일치', '독해/사실확인', true, '3', '① 드레스가 모자보다 더 저렴하다. (→ 더 비쌈)
② 신발이 가장 비싸다. (→ 가방이 가장 비쌈)
③ 모자는 다른 어떤 품목보다 더 저렴하다.
④ 가방은 신발과 모자보다 더 저렴하다. (→ 가방이 더 비쌈)', 1),
('f20cff22-c6a9-4023-a63d-7a36263302d0', '4236b15d-6bca-40ec-aac3-cded50635d08', 11, '어법', '문법/어휘', true, '1', '‘~가 있을[없을] 것이다’라는 의미로 there will be (no) ~를 쓸 수 있다. ‘~보다 더 …한’이라는 의미는 「비교급 + than ~」의 형태로 쓰며, 형용사 bad의 비교급은 worse이다.', 1),
('1c43dec9-369d-426b-92d4-dd0c7bfc31e8', '4236b15d-6bca-40ec-aac3-cded50635d08', 12, '어법', '문법/어휘', true, '2', 'ⓐ [Is → Are], 주어가 two bathrooms이므로 be동사 Are를 쓴다.
ⓒ [less sweeter → less sweet], ‘덜 ~한’은 less + 형용사 원급의 형태로 쓴다.
② 상자 안에는 선물이 하나도 없다.
③ 이 음악보다 더 크게 말할 수 있는 사람은 누구일까?
④ 당신의 집에 욕실이 두 개 있나요?
⑤ 이것은 우리 마을에서 가장 맛있는 피자이다.
⑥ 이 쿠키는 케이크보다 덜 달다.
⑦ 나는 나의 학교생활 중 최악의 실수를 저질렀다.', 1),
('de3db71b-2144-49d6-a9d8-6f7591313389', '4236b15d-6bca-40ec-aac3-cded50635d08', 13, '영작', '쓰기', false, '(1) Is this test easier than (2) is the cheapest in town', '(1) easy의 비교급은 easier로 쓴다.
(2) 「the + 최상급」의 형태로 쓰며, 형용사 cheap의 최상급은 cheapest로 쓴다.', 2),
('ff81807d-31e9-4539-b7eb-c66838120884', '4236b15d-6bca-40ec-aac3-cded50635d08', 14, '어법', '문법/어휘', true, '1', '① [throw → threw], ‘던졌다’라는 과거의 일을 기술하므로 동사 throw의 과거형 threw가 들어가야 한다.', 1),
('a28b2c50-2eb6-4de3-ba0a-891ccc667dca', '4236b15d-6bca-40ec-aac3-cded50635d08', 15, '어휘', '문법/어휘', true, '1', 'ⓑ about은 글에서 ‘약 ~’이라는 의미로 쓰였다.
ⓒ a little은 글에서 ‘약간, 조금’이라는 의미로 쓰였다.
ⓓ fell off는 글에서 ‘~에서 떨어졌다’라는 의미로 쓰였다.', 1),
('596178d3-c6b8-46e4-99e0-a3b8f65bd188', '4236b15d-6bca-40ec-aac3-cded50635d08', 16, '어휘', '문법/어휘', true, '1, 3', '① went after와 ③ followed는 모두 ‘~를 쫓아갔다’라는 의미이므로, ⓔ ran after와 바꾸어 쓸 수 있다.
② look after: ~를 돌보다
④ run out of: ~가 다 떨어지다
⑤ run away from: ~로부터 달아나다', 1),
('4c892bfa-b729-4f9f-8111-c7e7c410ab0e', '4236b15d-6bca-40ec-aac3-cded50635d08', 17, '빈칸추론', '논리/추론', true, '1', '그가 나보다 빨라서 잡을 수 없었다는 내용에 이어 ‘사실은’이라고 말한 후, 그 노인이 젊은 남자였다고 말하고 있으므로, 빈칸에는 ① the old man was not old가 가장 적절하다.
① 그 노인은 나이 들지 않았어요
② 나는 바보 그를 잡았어요
③ 그는 케이크를 던지지 않았어요
④ 그 노인은 너무 늙었어요
⑤ 그는 남자가 아니라 여자였어요.', 1),
('dbb10c1d-99c5-4694-8a99-025e264137e4', '4236b15d-6bca-40ec-aac3-cded50635d08', 18, '내용일치', '독해/사실확인', true, '2', '② 노인이 어디로 도망쳤는지는 글에 언급되지 않았다.
① 방문객이 뒤돌아봤을 때 무엇을 보았는가? (→ 휠체어 앞에 선 노인)
② 노인은 어디로 도망쳤는가? (→ 알 수 없음)
③ Ann Jones의 키는 어떻게 되는가? (→ 약 170 cm)
④ 노인은 도망치다가 무엇을 떨어뜨렸는가? (→ 가발)
⑤ 청소부는 노인에 대해 무엇을 알게 되었는가? (→ 사실 긴 갈색 머리의 젊은 남자였다는 것)', 1),
('050d8e87-0f5b-4dfb-9ca0-7909bf2ed083', '4236b15d-6bca-40ec-aac3-cded50635d08', 19, '영작', '쓰기', false, 'Carlos was slower than the old man.', '「비교급 + than」: ~보다 …한
질문: 왜 Carlos는 노인을 잡지 못했는가?', 1),
('d1b4aa00-6f01-4b81-aecc-0be15a8c42bc', '4236b15d-6bca-40ec-aac3-cded50635d08', 20, '어법', '문법/어휘', true, '4', 'ⓐ crime scene: 범죄 현장 (seen: 동사 see의 과거완료형)
ⓑ 많은 케이크들 중 가장 작은 케이크 하나를 원했다는 내용이므로 앞서 나온 케이크(cake)를 대신하는 부정대명사 one을 써야 한다.
ⓒ ‘분명하게’라는 의미로, 동사 remember를 수식하는 부사 clearly가 적절하다.', 1),
('8205061d-13f3-4389-9131-16bcac18b374', '4236b15d-6bca-40ec-aac3-cded50635d08', 21, '문장삽입', '글의흐름', true, '4', '주어진 문장은 ‘그는 영어로만 말했어요.’라는 의미로, 그에게 스페인어로 말했지만 이해하지 못했다는 내용 뒤에 이어지는 것이 자연스럽다.', 1),
('0c923b63-5650-459c-b885-528dedab3036', '4236b15d-6bca-40ec-aac3-cded50635d08', 22, '영작', '쓰기', false, 'There was also a wheelchair near the painting.', '「there + be동사」의 과거형」: ~가 있었다. 주어가 a wheelchair이므로 be동사 was를 써야 한다.', 1),
('85b6fe2b-9855-4ebf-b1f3-ae409ff9a0af', '4236b15d-6bca-40ec-aac3-cded50635d08', 23, '빈칸추론', '논리/추론', true, '5', '(B) 그에게 스페인어로 말했지만, 말을 이해하지 못했다고 했으며, (C) 여러 가지 다른 케이크를 팔았지만, 가장 작은 것을 원했다고 했으므로, 두 곳 모두 접속사 but이 적절하다.', 1),
('a6310316-05a2-4b56-9f7c-aa413a09af30', '4236b15d-6bca-40ec-aac3-cded50635d08', 24, '어휘', '문법/어휘', false, 'piece', '무언가의 더 큰 부분에서 잘라낸 양 → piece (조각, 부분)', 1),
('a1f07320-cf54-404f-beaf-621f366efae0', '4236b15d-6bca-40ec-aac3-cded50635d08', 25, '내용일치', '독해/사실확인', true, '4', '④ 빵집에서는 많은 다른 케이크를 판다고 했으므로 글의 내용과 일치하지 않는다.
① 그림은 케이크 조각들로 덮여 있었다.
② 휠체어는 그림에서 멀지 않았다.
③ 그 젊은 남자는 스페인어를 하지 않았다.
④ Camila의 빵집은 한 종류의 케이크만 판다.
⑤ 빵집 주인은 범인을 잘 기억한다.', 1),
('87d4f34a-0cdf-4c6b-b215-d2af3dc947ef', '7d5a4aaa-8516-404b-9fd3-bacf73036d3e', 1, '어법', '문법/어휘', true, '3', '밑줄 친 문장은 ''너는 여기에서 드론을 날리면 안 된다.''라는 의미로 상대방의 행동을 금지하는 「must + 동사원형」이 쓰였다.', 1),
('0d08ea1f-1dc4-4d1f-a806-d45061a145b0', '7d5a4aaa-8516-404b-9fd3-bacf73036d3e', 2, '어휘', '문법/어휘', false, 'running', 'run away: 도망가다 run after: ~를 쫓아가다', 1),
('02ab429b-2ddf-4e63-831b-ad57e73fa025', '7d5a4aaa-8516-404b-9fd3-bacf73036d3e', 3, '어법', '문법/어휘', true, '4', 'ⓐ 「There + be동사」 뒤에 복수 명사 two bedrooms가 주어로 쓰였으므로, be동사 are가 적절하다. ⓑ 앞에 the가 있고, 뒤에 세 개 이상의 비교 범위를 나타내는 of ~가 나오므로 최상급 biggest(가장 큰)가 적절하다.', 1),
('90a3f4ec-719b-4d66-b4d7-41a612dbcce6', '7d5a4aaa-8516-404b-9fd3-bacf73036d3e', 4, '제목요지', '주제파악', true, '2', '민호의 집 구조와 방에 대해 설명하는 글이므로 ②가 주제로 가장 적절하다. ① 민호의 가족 구성원들 ② 민호의 집 소개 ③ 큰 집을 소유하는 방법 ④ 민호가 집에서 운동하는 이유 ⑤ 민호의 이웃', 1),
('2b9f0548-49ec-4635-89da-f42f67b05d09', '7d5a4aaa-8516-404b-9fd3-bacf73036d3e', 5, '어법', '문법/어휘', true, '2', '뒤에 복수 명사 four suspects가 주어로 쓰였으므로 be동사 are가 적절하다.', 1),
('d0179bf1-8158-4b4a-be18-6f6f3bd7f597', '7d5a4aaa-8516-404b-9fd3-bacf73036d3e', 6, '어법', '문법/어휘', false, 'is, shorter, than', '비교급 than ~: ~보다 …한', 1),
('fadf5863-650a-4e26-9249-15e601a8d98d', '7d5a4aaa-8516-404b-9fd3-bacf73036d3e', 7, '내용추론', '독해/사실확인', true, '4', 'Tim이 파란 눈이 아니라서 범인이 아니라고 했으므로, 범인은 파란 눈이라는 것을 유추할 수 있다. ① → 금반지 ② → 4명 ③ → 180cm보다 큼 ⑤ → 빨간 머리 아님', 1),
('3d5427c3-feba-448f-aebc-4e309869b2b0', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 1, '어법', '문법/어휘', true, '3', 'You must not ~은 ‘~하면 안 된다’라는 의미로, 상대방의 말이나 행동을 제한하거나 금지하고자 할 때 쓰는 표현이다. • 박물관 안에서 뛰면 안 됩니다.', 1),
('b7cd22ef-4993-40f6-a05e-5f0cd92736d9', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 2, '대화문', '화용/의사소통', true, '2', 'May I ~?는 ‘제가 ~해도 될까요?’라는 의미로 이에 대한 허락의 표현으로는 Yes, you may. / Of course. / Why not?, 거절의 표현으로는 No, you may not. / I’m afraid not. 등이 있다. ② ‘네, 저는 봅니다.’는 상대방의 행동에 대한 허락의 표현이 아니므로 실설하지 않다. • 문을 닫아도 될까요? ① 왜 안 되겠어요? ③ 물론이죠. ④ 안 될 것 같아요. ⑤ 아니요, 당신은 해서는 안 돼요.', 1),
('476ad923-579c-44b4-b1c1-b51d63ca985f', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 3, '어법', '문법/어휘', false, 'not, open', '「must not + 동사원형」: ~하면 안 된다', 1),
('013c6b38-47e3-473c-aafc-05398630bf77', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 4, '대화문', '화용/의사소통', true, '4', '여기서 먹어도 되냐는 B의 물음에 대한 답으로 안에서 먹으면 안 된다는 ⓑ가 이어지고, 물은 가능한지 묻는 ⓒ의 질문에 물은 괜찮다는 ⓐ의 답이 이어지는 것이 자연스럽다. ⓐ 여기에서 먹어도 되나요? ⓑ 아니요, 박물관 안에서는 먹으면 안 됩니다. ⓒ 물은 어떤가요? 물을 마셔도 되나요? ⓓ 물론이에요, 물은 괜찮아요.', 1),
('fac98bef-9edd-4d46-ac44-e065f09b9518', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 5, '대화문', '화용/의사소통', true, '5', '빈칸에는 ‘~하면 안 된다’라는 금지의 표현이 들어가야 하므로 ⑤ don’t have to(~할 필요 없다)는 적절하지 않다. A: 재킷 없이 밖에 나가도 되나요? B: 아니요, 이 추위에 외출해서는 안 됩니다!', 1),
('a9a9e7a2-5ada-434a-a990-bfb3fa955c89', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 6, '영작', '쓰기', false, 'you must not talk on the phone here', '‘must not + 동사원형」은 ‘~하면 안 된다’라는 의미이다. talk on the phone: 전화 통화하다', 1),
('22ed9c57-d7f8-4cde-b2e2-f9ced3908370', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 7, '대화문', '화용/의사소통', true, '5', '전화를 끊겠다고 한 소년의 말 뒤에 문자를 보내는 것은 괜찮다고 했으므로, ‘~할 필요가 없다’라는 의미의 ⑤ don’t have to가 들어가야 한다.', 1),
('0cb19f08-195a-4bf1-b3fe-e47df6501d47', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 8, '대화문', '화용/의사소통', true, '4', 'I see.는 ‘알겠습니다.’라는 의미로 상대방의 말을 이해했다는 표현이다.', 1),
('10e3c777-f879-4a7a-9e84-cb1455fb10f8', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 9, '대화문', '화용/의사소통', true, '4, 5', '수업 중에 간식을 먹어도 되냐는 질문에 대한 대답으로, 빈칸 ⓐ 뒤에 간식을 먹으면 안 된다고 말하고 있으므로, 거절하는 말인 ④, ⑤가 적절하다. ① 왜 안 되겠니? ② 물론이야. ③ 응, 돼. ④ 안 될 것 같아. ⑤ 아니, 안 돼.', 1),
('6423d0b7-8711-49b1-8d68-5e03343ad167', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 10, '내용일치', '독해/사실확인', true, '4', 'You must not eat snacks in class.(너는 수업 중에 간식을 먹어서는 안 된다.)에서 알 수 있다.', 1),
('abf15554-a3e2-4611-8801-53a8f1fa42dc', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 11, '영작', '쓰기', false, 'May I touch this golden bear?', '‘~해도 될까요?’라는 의미로 「May I + 동사원형 ~?」의 형태를 쓴다.', 1),
('bd458b36-7952-4cfc-bdaa-932e1efda447', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 12, '어법', '문법/어휘', true, '2', '‘~하면 안 된다’라는 의미로 「must not + 동사원형」의 형태를 쓴다. ⑤ 너는 이 방 안의 어떤 것도 만질 필요가 없다.', 1),
('6c5be2a2-d3dd-49b0-a28e-8059038ebad1', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 13, '어휘', '문법/어휘', true, '4', 'ⓐ 이후 내용에서 방문객들이 동물원에서 지켜야 할 규칙들이 나오므로 rules(규칙들)가 적절하다. (role: 역할, roll: 롤, 두루마리) ⓑ 방문객들이 지켜야 할 세 가지 규칙 중 두 가지를 말했고, 마지막 규칙을 말할 차례이므로 lastly(마지막으로)가 적절하다. (lately: 최근에, later: 나중에)', 1),
('5d16e0d4-6d0e-4192-8942-5c8f87f40db1', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 14, '제목요지', '주제파악', true, '3', 'Dream Zoo에서 지켜야 할 세 가지 규칙을 말하고 있으므로 ③이 주제로 가장 적절하다. ① 반려동물을 돌보는 방법 ② 동물원에서의 재미있는 활동들 ③ 동물원 방문 규칙 ④ 동물원에 있는 동물의 종류 ⑤ 동물원의 역사', 1),
('3fdc837c-070f-4e20-ad44-0768c73d95e0', '85f91559-52ac-47e8-94e9-e39bfdfd6711', 15, '영작', '쓰기', false, 'you must not throw trash at the animals', '‘~하면 안 된다’라는 의미로 「must not + 동사원형」의 형태를 쓴다. 주어진 단어에 not을 추가하여 배열한다.', 1),
('f90c87c6-250f-40d3-9504-768f3c409339', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 1, '대화문', '화용/의사소통', true, '1, 4', 'May I ride a bike here?(내가 여기에서 자전거를 타도 되니?)는 상대방에게 허락을 구하는 표현으로, 같은 의미의 ① 또는 ④와 바꿔 쓸 수 있다.
② 내가 여기에서 자전거를 타야 할까?
③ 너는 여기에서 자전거를 탈 거니?
⑤ 너는 여기에서 자전거를 탈 수 있니?', 1),
('3557c9dd-7931-4b93-911c-15df21cdacb6', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 2, '대화문', '화용/의사소통', true, '2', '②의 Do you mind ~?는 ‘~하는 것을 꺼리시나요?’라는 의미로, 허락의 대답은 No, I don’t (mind).로, 거절의 대답은 Yes, I do (mind).로 하는 것에 주의해야 한다. 뒤에서 ‘사용하지 마세요.’라고 말했으므로, 허락의 의미인 No, I don’t.는 적절하지 않다.
① A: 펜을 빌려도 될까요? B: 네, 여기 있습니다.
② A: 휴대폰을 사용해도 될까요? B: 괜찮아요. 사용하지 마세요.
③ A: 그녀에게 남상 선화해야 할까? B: 아니, 그럴 필요는 없다고 생각해.
④ A: 지금 쉬어도 되나요? B: 아니요, 회의 중에는 쉬어서는 안 됩니다.
⑤ A: 아이스크림을 좀 먹어도 될까요? B: 물론이지, 하지만 너무 많이는 먹지 마.', 1),
('301047d8-6bd6-49db-ace6-714df9b24028', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 3, '영작', '쓰기', false, 'You must not fly a drone here.', '「must not + 동사원형 ~」: ~하면 안 된다
fly a drone: 드론을 날리다', 1),
('b4bee255-89cf-4e3e-bd80-c9a1af514a7e', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 4, '대화문', '화용/의사소통', true, '2', '가게에 개를 데려와도 되는지 허락을 구하는 소녀의 질문에, 반려동물을 안에 데려오면 안 된다고 말하고 있으므로, 거절의 의미를 표현하는 대답 No, you may not.(아니, 당신은 해서는 안 돼요.), I’m afraid not.(안 될 것 같아요.), 또는 Of course not.(물론 안 돼요.) 등이 들어가야 한다.', 1),
('49df8d39-a012-4ed6-a920-5f239fda78c7', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 5, '대화문', '화용/의사소통', true, '1, 2', '가게에 개를 데려오는 것을 금지한다는 대답을 듣고 알겠다는 표현을 해야 하므로, ① ‘알겠어요’ ④ ‘안 그럴게요’ ⑤ ‘이해했어요’ 등의 답이 적절하다.', 1),
('2038ab3e-8de5-4dba-99ec-1146b863db47', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 6, '대화문', '화용/의사소통', false, '[예시답안] 왜 안 되나요?', 'Why not?은 상황에 따라, ‘안 될 게 뭐야?’ ‘물론이야.’ 등 허락의 의미로 쓰일 수도 있으나, 이 대화에서는 뛰지 말라고 한 여자의 말에 그 이유를 묻는 질문이다.', 1),
('d39ba3e9-2f62-404e-b162-69a28bc5b992', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 7, '내용추론', '독해/사실확인', true, '3', '대화에서 여자가 소년에게 뛰면 안 된다고 말하고 있으므로, that sign(저 표지판)은 뛰는 것을 금지하는 내용이어야 한다.', 1),
('7044cbc6-6239-4193-a607-bbe583074f54', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 8, '영작', '쓰기', false, 'Is it okay to take food into the museum?', '「May I + 동사원형 ~?」은 ‘~해도 되나요?’라는 의미로 「Is it okay to + 동사원형 ~?」과 같은 의미로 쓸 수 있다.', 1),
('746281d0-0df5-409c-99b6-d8bf6c86ab37', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 9, '어법', '문법/어휘', true, '2', '② 금지를 나타내는 must not 부정문이 쓰였으므로, any가 들어가야 한다. ‘병에 든’ 물을 나타내는 형용사 bottled가 들어가야 한다.', 1),
('96231b7d-901e-4bd5-bea0-b9c9a681cd91', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 10, '대화문', '화용/의사소통', true, '5', '음식을 가져오면 안 된다는 여자의 말 이후, 소년의 질문에 이어 병에 든 물은 괜찮다고 했으므로, ⑤ How[What] about water?(물은 어떤가요?)라는 질문이 들어가야 가장 적절하다.
① 물은 왜 안 되나요?
② 음식은 어떤가요?
③ 물은 어디에 있나요?
④ 저 물은 무엇인가요?', 1),
('6c0037de-3a70-4849-8b68-f4602a707efb', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 11, '어휘', '문법/어휘', true, '3', '[bright(밝은) → dark(어두운)], 대화에서 소녀가 사진을 찍을 때 플래시를 왜 사용하면 안 되는지 묻고 있으므로 사진을 찍기에는 장소가 ‘어둡다’라고 말하는 것이 흐름상 적절하다.', 1),
('95bb649b-8796-4f22-93fb-14fcd8179f40', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 12, '문장삽입', '글의흐름', true, '2', '주어진 문장은 ‘그것(해바라기 그림)의 사진을 찍어도 되나요?’라는 의미로, 그림을 소개하는 남자의 말 뒤, 그렇게 해도 된다고 대답하는 남자의 말 앞인 ②에 들어가는 것이 가장 적절하다.', 1),
('fe70a8ea-6b72-4548-8b52-7371e538e1f0', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 13, '내용일치', '독해/사실확인', true, '3', '③ 다음엔 그림을 몇 점 볼지는 대화에서 알 수 없다.
① 소녀가 가장 좋아하는 그림은 무엇인가? (→ 반 고흐의 ‘해바라기’)
② 소녀는 그림의 사진을 찍어도 되는가? (→ 됨)
④ 반 고흐의 그림 이름은 무엇인가? (→ ‘해바라기’)
⑤ 소녀는 왜 사진을 찍을 때 플래시를 사용할 수 없는가? (→ 그림에 손상을 입히기 때문에)', 1),
('2a2a8146-18d1-4745-945b-43428be40c40', '16f0236f-8aff-4ca2-9530-a0d6673701c1', 14, '영작', '쓰기', false, 'She must not use the flash', '「must not + 동사원형 ~」: ~하면 안 된다
사진을 찍어도 되지만 플래시는 사용하면 안 된다고 했다.', 1),
('5cc1523a-d14e-4aa8-9247-c320c24bc971', '5023e900-c542-4c41-a694-f41626185beb', 1, '어법', '문법/어휘', true, '5', 'yesterday(어제)라는 과거 시점의 일을 나타내고 주어가 many people로 복수이므로, 「There + were(be동사 과거형)」로 ‘~들이 있었다’라고 표현한다. • 어제 공원에는 많은 사람들이 있었다.', 1),
('85c37d9a-8620-40f0-be02-ad17071257cc', '5023e900-c542-4c41-a694-f41626185beb', 2, '어법', '문법/어휘', true, '3', '「비교급 + than ~」은 ‘~보다 더 …한’이라는 뜻이고, big은 ‘단모음 + 단자음」으로 끝나는 형용사이므로 마지막 자음을 하나 더 쓰고 -er을 붙여 비교급을 만든다. • 나의 개는 너의 고양이보다 더 크다.', 1),
('a6901844-4b04-4227-9c8e-45b3d8e5eae5', '5023e900-c542-4c41-a694-f41626185beb', 3, '어법', '문법/어휘', true, '4', '부사 clearly(분명히)의 비교급은 more clearly(더 분명히)의 형태로 쓴다. ② 아픈 - 더 아픈 ③ 적은 - 더 적은 ④ 많은 - 더 많은 ⑤ 예쁜 - 더 예쁜', 1),
('7720a683-4759-4c0b-a0d7-97a5dc87f61f', '5023e900-c542-4c41-a694-f41626185beb', 4, '어법', '문법/어휘', false, 'There, was', 'There was ~: ~가 있었다. 주어인 (some) money는 셀 수 없는 물질명사이므로 단수 취급하며, 과거형 be동사 was를 쓴다.', 1),
('e846282b-cb2d-4c5a-b79d-d6f3dd3d7cc2', '5023e900-c542-4c41-a694-f41626185beb', 5, '어법', '문법/어휘', true, '3', '형용사 cheap의 최상급 표현은 「the + 형용사 원급 + -est + of ~」의 형태를 써서, ‘~(비교 대상들) 중에 가장 ~한’이라는 의미를 나타낸다.', 1),
('f765a1dc-e17b-4fd9-bfbf-4b9e6e7a1385', '5023e900-c542-4c41-a694-f41626185beb', 6, '어법', '문법/어휘', true, '4', '주어가 a birthday party로 단수이며, 과거(어제)에 일어난 일이므로 be동사 과거형 was의 부정문 wasn''t를 사용한다.', 1),
('77e5958c-34d7-4173-94be-1a1a08fc3519', '5023e900-c542-4c41-a694-f41626185beb', 7, '어법', '문법/어휘', false, '(1) There was a lot of homework. (2) This food is better than that one. (3) What is the smallest animal in the world?', '(1) 주어인 homework는 셀 수 없는 명사이므로 be동사 was를 쓴다. (2) 형용사 good의 비교급은 better로 불규칙 변화한다. (3) 형용사 small의 최상급은 -est를 붙여 smallest로 쓴다. (1) 숙제가 많았다. (2) 이 음식은 저것보다 더 좋다. (3) 세상에서 가장 작은 동물은 무엇이니?', 3),
('e731bb7e-7699-4b93-8ee2-993cecbf1195', '5023e900-c542-4c41-a694-f41626185beb', 8, '어법', '문법/어휘', true, '4', '첫 번째 문장에 last night이라는 과거시제가 나타나 있으므로 정답은 과거 동사가 되어야 하며, stars와 people이 모두 복수 명사이므로 빈칸에 공통으로 들어갈 be동사는 were이다. • 어젯밤에는 하늘에 별이 전혀 없었다. • 버스 정류장에 사람들이 있었니?', 1),
('7eeabcf4-88b6-466d-9b2f-6e4247cac9f9', '5023e900-c542-4c41-a694-f41626185beb', 9, '어법', '문법/어휘', true, '2', '② [tall → taller], 「비교급 + than ~」은 ‘~보다 더 …한’의 의미로 형용사 tall은 끝에 -er를 붙여 비교급의 형태를 만든다.', 1),
('15293cf3-7ae6-45bb-ad2c-be875161c8d4', '5023e900-c542-4c41-a694-f41626185beb', 10, '어법', '문법/어휘', false, 'the tallest tree in the park', '「the + 최상급 + in ~」은 ‘~에서 가장 …한’의 의미로 형용사 tall 뒤에 -est를 붙여 최상급의 형태를 만든다.', 1),
('3589426b-803e-4c39-b876-4c32e1c56793', '5023e900-c542-4c41-a694-f41626185beb', 11, '어법', '문법/어휘', true, '1, 4', '② [more fast → faster], 형용사 fast의 비교급은 단어 끝에 -er를 붙인다. ③ [is → are], 주어가 복수(a few children)이므로 be동사 are를 쓴다. ⑤ [smartest → the smartest], 형용사의 최상급 앞에는 the를 붙여야 한다. ① 어젯밤 폭풍이 있었다. ② 내 차가 네 차보다 더 빠르다. ③ 학교에 아이들이 몇 명 있다. ④ 이 꽃은 정원에서 가장 예쁘다. ⑤ Jessica는 모든 학생들 중에서 가장 똑똑하다.', 1),
('f41765dc-0250-455a-94a7-f90ba0a9243b', '5023e900-c542-4c41-a694-f41626185beb', 12, '내용일치', '독해/사실확인', true, '4', '④ 가장 무거운 학생은 Bill이 아니라 Peter이다. ① Peter는 John보다 키가 크다. ② Bill은 가장 키가 큰 학생이다. ③ John은 Peter와 Bill보다 키가 작다. ④ Bill은 모든 학생 중 가장 무겁다. ⑤ John은 Peter보다 가볍다.', 1),
('3b64b91e-f4e5-493c-8aa0-1eab05a879dc', '5023e900-c542-4c41-a694-f41626185beb', 13, '어법', '문법/어휘', false, 'Bill is heavier than John.', '「비교급 + than ~」을 활용하고, 형용사 heavy는 y를 i로 고친 후 -er를 붙여 비교급의 형태를 만든다.', 1),
('f4a9e015-109d-42bf-ab75-a33e171837a6', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 1, '어법', '문법/어휘', false, 'the highest, in', '「the 최상급 + in + 장소/집단의 단수명사」는 ‘~에서 가장 …한’이라는 의미이다. 형용사 high의 최상급은 뒤에 -est를 붙여 highest로 쓴다.', 1),
('328eae33-9fe8-4853-b0c8-39feab8a11f4', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 2, '어법', '문법/어휘', true, '5', 'Are there ~?는 ‘~들이 있니?’라는 의미로, be동사 are가 쓰였으므로 빈칸에는 복수 형태의 주어가 쓰여야 한다. 셀 수 없는 명사인 ⑥ ‘가구’는 문장에 적절하지 않다. • 너의 집에 ⑦ 남자들 ⑧ 쥐들 ⑨ 의자들 ⑩ 아이들이 있니?', 1),
('63b04550-9da2-4695-88fd-c5321efd202f', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 3, '어법', '문법/어휘', true, '2', '‘~보다 더 …한’이라는 비교급의 형태가 들어가야 하므로 형용사의 원급인 ② ‘작은’은 적절하지 않다. • 그의 재킷이 내 것보다 ① 더 좋아 ③ 더 따뜻해 ④ 더 예뻐 ⑤ 더 비싸 보인다.', 1),
('790f5605-fbdb-4ad5-8db7-d1f335d382a7', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 4, '영작', '쓰기', false, 'What kind of bread is there in the bakery?', '「의문사(주어) + be동사 + there ~?」의 형태로 의문문을 만든다. 이때, bread(빵)는 셀 수 없는 명사이므로 be동사 is를 쓴다. what kind of: 어떤 종류의 ~', 1),
('a9eb34ce-3897-475d-bfe9-10b585f5dfaa', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 5, '어법', '문법/어휘', true, '1, 4', '① [more tastier → tastier], 형용사 tasty의 비교급은 tastier이므로, more는 불필요하다. ⑤ [was → were], 주어 memories가 복수이므로 be동사의 복수형 were를 쓴다. ① 닭고기가 소고기보다 더 맛있다. ② 너에게 가장 중요한 사람은 누구니? ③ 내 컴퓨터에 문제가 있니? ④ 나의 어린 시절의 멋진 추억이 있었다. ⑤ 그 남자는 다른 사람들이 하는 것보다 더 열심히 일한다.', 1),
('d0538a46-fc91-4df6-ade4-4a1888c3c7d2', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 6, '어법', '문법/어휘', true, '3', '③은 ‘거기에’라는 의미의 부사이다. 나머지는 모두 be동사와 함께 쓰여 ‘~가 있다’라는 뜻으로 쓰였다. ① 마당에 어떤 개도 없었다. ② 하늘에 몇 개의 별이 있나요? ③ 그쪽에 무엇이 보이나요? ④ 테이블 위에 책이 있었나요? ⑤ 어떤 종류의 선물들이 있나요?', 1),
('84aa0322-5e97-4120-b472-f295429e59c7', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 7, '어법', '문법/어휘', false, '(1) the smallest of (2) larger than, smaller than', '(1) 「the 최상급 of + 비교 대상의 복수명사」는 ‘~중 가장 …한’이라는 의미이다. (2) 「비교급 + than ~」은 ‘~보다 더 …한’의 의미이다. (1) 빨간색 공은 모든 공 중에서 가장 작다. (2) 녹색 공은 파란색 공보다 크고 노란색 공보다 작다.', 2),
('b6b38da7-fcee-4745-8aa3-98ca430312d7', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 8, '어법', '문법/어휘', true, '1', 'ⓐ 형용사 little의 불규칙 비교급 less를 쓴다. ⓑ 형용사 happy의 최상급 형태는 y를 i로 고치고 -est를 붙인다. ⓒ 주어 coffee는 셀 수 없는 명사이므로 단수형 be동사 is의 부정문 isn''t를 쓴다. • 그는 옷에 나보다 더 적은 돈을 쓴다. • 오늘은 내 인생에서 가장 행복한 날이다. • 컵에 커피가 많지 않다.', 1),
('e4928d07-ba5e-479d-a69f-f64d54cd3fcf', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 9, '어법', '문법/어휘', false, '(1) (1) ⓐ There was a lot of sand in my shoes. (2) (2) ⓓ Tom is the oldest boy in his school', 'ⓐ 주어인 sand는 셀 수 없는 명사이므로 be동사 was로 수를 일치시킨다. 
ⓓ 최상급 뒤의 비교 집단이 장소/집단의 단수 명사일 경우 전치사 in을 쓴다. 
ⓐ 내 신발에 모래가 많았다. ⓑ 오늘은 어제보다 더 덥다. ⓒ 마을에 새로운 레스토랑이 있다. ⓓ Tom은 그의 학교에서 가장 나이 많은 소년이다. ⓔ 그 책은 영화보다 더 흥미롭다.', 2),
('b7e4d24a-2b6b-4c2b-b773-42ec77568a67', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 10, '어법', '문법/어휘', true, '5', '「소유격 + 최상급 ~」: ~의 가장 …한
최상급 앞에는 the 대신 소유격을 사용할 수 있으며, 형용사 exciting은 앞에 most를 붙여서 최상급을 만든다. 바르게 영작하면 When was your most exciting experience?이므로 다섯 번째로 오는 단어는 exciting이다.', 1),
('c523653a-7e2c-4512-8ca5-640e38e48d40', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 11, '어법', '문법/어휘', true, '3', '〈보기〉와 ①②④⑤는 모두 주어가 복수이므로 be동사 are가, ③의 주어는 time으로 단수이므로 is가 들어간다. ①의 sheep(양)은 단수와 복수의 형태가 같다. 〈보기〉지금 상영 중인 좋은 영화가 있니? ① 오늘 회의는 몇 개 있니? ② 그 행사에는 많은 사람들이 있다. ③ 우리에게 시간이 충분하니? ④ 농장에 검은 양들이 있니? ⑤ 너의 보고서에는 실수가 없다.', 1),
('c179110f-28eb-45c9-962e-991f1fabce4f', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 12, '어법', '문법/어휘', true, '4', 'a. [to→than], 「비교급+than~」: ~보다 더 …한 
d. [worse→worst], 형용사 bad의 최상급은 worst로 쓴다. 
e. [are→is], 주어인 information은 셀 수 없는 명사이다. 
a. 이 문제는 다른 어떤 문제들보다도 더 쉽다. b. 빈지가 지호보다 더 분명하게 말한다. c. 네가 지각한 이유가 있니? d. 오늘이 올해 최악의 날씨이다. e. 웹사이트에 많은 정보가 있다.', 1),
('bd3e51a7-10a7-4ad0-bf9e-6fa146dc680c', '750d5f1e-c421-485a-b71e-7ddd5208bc2c', 13, '영작', '쓰기', false, 'She is the funniest person of my friends.', '「the 최상급 of + 비교 대상의 복수명사」는 ''~ 중 가장 …한''이라는 의미이다. 형용사 funny의 최상급은 funniest로 쓴다.', 1),
('c7814079-6431-4c0d-977c-88d6de345fff', 'f5104e81-4330-483a-9425-1c724fc133dd', 1, '어휘', '문법/어휘', false, 'Chinese', 'Korea : Korean은 ''한국 : 한국어, 한국인''이라는 의미로 나라 이름에 접미사 -(a)n이 붙어 ''그 나라의 언어 또는 사람''의 뜻을 나타낸다. China(중국)는 접미사 -ese가 붙어 같은 의미를 나타내므로, 빈칸에는 Chinese(중국어, 중국인)가 들어가야 한다.', 1),
('f58f8dbe-cb5e-4cd2-be11-aef5947397f6', 'f5104e81-4330-483a-9425-1c724fc133dd', 2, '어휘', '문법/어휘', true, '4', '~를 조심하다''라는 의미의 watch out for가 들어가야 한다. • 산에서는 뱀을 조심하세요.', 1),
('78424f9e-2929-4cb0-a602-2ff818862b3e', 'f5104e81-4330-483a-9425-1c724fc133dd', 3, '어휘', '문법/어휘', false, 'over', 'look over: 살펴보다, 훑어보다 all over: 곳곳에, 전체에 • 나는 회의 전에 보고서를 전부해야 한다. • 그는 집안 곳곳에서 열쇠를 찾았다.', 1),
('a21b4b17-ac6c-4f82-9e46-c8e278550756', 'f5104e81-4330-483a-9425-1c724fc133dd', 4, '어휘', '문법/어휘', true, '2', '무언가 또는 누군가에게 나쁘거나 해로운 영향을 미치다 → damage (손상을 입히다) ① 먹이를 주다 ③ 따라가다 ④ 잊어버리다 ⑤ 이해하다', 1),
('8e95f3fa-cdd8-4a2f-857f-39b46f6a3c5c', 'f5104e81-4330-483a-9425-1c724fc133dd', 5, '어휘', '문법/어휘', true, '3', '③ steal: 훔치다 sell: 팔다 ① 케이크 한 조각 주시겠어요? ② 그녀는 나에게 비밀을 말했다. ③ 누군가 내 자전거를 훔치려고 했다. ④ 그녀는 바닥을 밝은색으로 칠했다. ⑤ 너의 키는 얼마니?', 1),
('1f8ff921-8ff9-4851-a35c-91b2bdd41be4', 'f5104e81-4330-483a-9425-1c724fc133dd', 6, '어휘', '문법/어휘', true, '4', 'a seat: 명 자리, 좌석 (sit: 앉다, set: 세트) b clearly: 분명하게 (clean: 깨끗한, 청소하다, clear: 분명한) A: 여기 앉으세요. B: 감사합니다! 이 자리에서 무대가 분명하게 보이네요.', 1),
('392d93c0-2d9f-46f2-aac9-f8040e44ecc3', 'f5104e81-4330-483a-9425-1c724fc133dd', 7, '어휘', '문법/어휘', false, 'In, fact', 'in fact: 사실은', 1),
('3c0be180-63a0-4aee-aa1e-28f72666d76b', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 1, '어법', '문법/어휘', true, '2', 'slow : slowly는 ''느린 : 느리게''라는 의미이므로, ①③④⑤와 동일하게 형용사 : 부사 관계이다. ②는 ''친구 : 친근한''의 의미로 명사 : 형용사 관계이다. ① 분명한 : 분명히 ③ 끔찍한 : 끔찍하게 ④ 조심하는 : 조심스럽게 ⑤ 비싼 : 비싸게', 1),
('2cc36e14-36f3-401b-aad4-51b597415b9b', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 2, '어휘', '문법/어휘', true, '3', 'inside : outside는 ''안으로 : 밖으로''라는 의미이므로, ①②④⑤와 동일하게 반의어 관계이다. ③은 near와 close 둘 다 ''가까운''의 의미로 유의어 관계이다. ① 기억하다 : 잊다 ② 비어 있는 : 가득 찬 ④ 비싼 : 싼 ⑤ 어두운 : 밝은', 1),
('de76d449-43c4-4a34-ba8d-98b52ed1554b', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 3, '어휘', '문법/어휘', false, 'floor', 'floor: 명 층, 바닥 • 내 사무실은 건물 3층에 있다. • 카펫이 깔리지 않아 바닥이 차갑게 느껴졌다.', 1),
('1cdbcb83-d0ee-4748-b964-de1d0ac2fe37', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 4, '어휘', '문법/어휘', true, '4', 'next to: ~ 옆에 ① ~ 아래에 ② ~ 안에 ③ ~ 뒤에 ⑤ ~ 앞에', 1),
('7f43405b-0d33-401c-905b-3d26a82ef609', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 5, '어휘', '문법/어휘', true, '4', 'feed: 동 먹이를 주다 ① 먹다 ② 느끼다 ③ 팔다 ⑤ 던지다 A: 공원에 있는 오리에게 먹이를 주고 싶니? B: 물론이지! 내가 빵 몇 조각을 가져왔어.', 1),
('5044646a-ce49-4e95-8677-da07d214b2f6', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 6, '어휘', '문법/어휘', true, '5', 'watch out for는 ''~를 조심하다''라는 의미이므로 같은 뜻의 ⑤ be careful of와 바꿔 쓸 수 있다. • 도로를 건널 때 차를 조심해라. ① ~을 돌보다 ② ~을 돌보다 ③ ~로 넘어가다 ④ ~에서 도망치다', 1),
('a88f11a5-e8ba-463e-8950-6e6939921bd2', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 7, '어휘', '문법/어휘', false, '(e)yewitness', '무언가 일어나는 것을 직접 눈으로 본 사람 → eyewitness (목격자)', 1),
('91a29a86-fb8f-4e5e-a0bf-a615f346261f', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 8, '어휘', '문법/어휘', true, '2', 'run after: ~를 쫓아가다 run away (from): (~로부터) 도망가다 • 개는 공을 쫓는 것을 좋아한다. • 그녀는 위험으로부터 도망치려고 했다.', 1),
('b464cc2d-91cf-4c29-9aee-d0b84b4ad2f6', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 9, '어휘', '문법/어휘', true, '3', '③ piece: 명 조각 (peace: 명 평화) ⓐ secret: 형 비밀의 명 비밀 (scene: 명 현장, 장면) ⓒ flash: 명 섬광, 번쩍임 (fresh: 형 신선한, flush: 동 붉어지다) • 그녀는 나에게 초콜릿 한 조각을 주었다. • 그는 비밀 암호로 메시지를 작성했다. • 카메라가 밝게 번쩍였다.', 1),
('36a7398f-0da7-4a0a-8038-be00378a5988', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 10, '어휘', '문법/어휘', true, '5', '무언가의 의미 또는 작동 방식을 알다 → understand (이해하다) ① 규칙을 준수하세요. ② 내일 무슨 일이 일어날까? ③ 내일 수업에 책을 가져오세요. ④ 그녀는 항상 친구의 생일을 기억한다. ⑤ 프로젝트 주제를 이해했니?', 1),
('afd50d72-e198-42d8-b831-28bb9d52203d', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 11, '어휘', '문법/어휘', false, 'fall, off', 'fall off: ~에서 떨어지다', 1),
('e2078143-8435-4f79-a969-426833a71f73', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 12, '어휘', '문법/어휘', true, '2', '위험을 경계하거나 재산을 보호하는 사람 → guard (경비원, 경호원) ① 간호사 ③ 교사 ④ 변호사 ⑤ 엔지니어, 기술자', 1),
('e926ad02-12db-46c9-afa5-e54219a307ee', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 13, '어휘', '문법/어휘', true, '1', 'ⓒ의 bright(밝은)는 dark(어두운)가 되어야 자연스럽다. ① 저녁에는 공원이 밝아(→ 어두워)진다. ② 고양이가 상자 안에 숨어 있다. (inside: ~ 안에) ③ 당신의 목표를 기입하라. (remember: 기입하다) ④ 가구가 없어 방이 텅 빈 느낌이었다. (empty: 비어 있는) ⑤ 그녀는 창문 가까이에 앉았다. (near: ~의 가까이에)', 1),
('90d4604d-7193-418a-b1d8-630eb286b189', '7aedcc7e-99df-4368-8b2c-af786ce369c7', 14, '어법', '문법/어휘', false, 'is, talking, on, the, phone', 'talk on the phone: 전화 통화하다 현재진행형 「be동사 + 동사원형-ing」의 형태로 쓴다.', 1),
('655767c6-34a7-4581-a19a-a17357e9c9d3', '702b84ee-1696-4524-92d8-ff8a500b3beb', 1, '어휘', '문법/어휘', true, '4', '<보기>와 ①, ②, ③, ⑤는 반의어 관계이며 ④는 ''명사 : 형용사'' 관계이다. ① 젖은 : 마른 ② 잘못된 : 올바른 ③ 유용한 : 쓸모없는 ⑤ 늦게 : 늦은 : 일찍 : 이른', 1),
('9889fabf-0049-4d4e-9c8d-93fcc05ccdb0', '702b84ee-1696-4524-92d8-ff8a500b3beb', 2, '어휘', '문법/어휘', true, '2', 'go out: 외출하다 오늘 오후에는 나가서 점심을 먹자.', 1),
('d1bcbb67-b010-44da-acfe-da7bd4ac5c11', '702b84ee-1696-4524-92d8-ff8a500b3beb', 3, '어휘', '문법/어휘', false, 'did', 'do volunteer work: 자원봉사를 하다 / do some exercise: 운동을 하다 • 우리는 지난 여름에 병원에서 자원봉사를 했다. • 그는 학교에 가기 전에 한 시간 동안 운동을 했다.', 1),
('a0813276-3b99-4190-8204-c3c3fde587ec', '702b84ee-1696-4524-92d8-ff8a500b3beb', 4, '대화문', '화용/의사소통', true, '3', '카페에서 주문을 할 때 사용하는 표현이므로 I want (to have / to order) the strawberry juice, please.로 써야 한다.', 1),
('dbe319f1-98f2-4494-aeca-1c5a14bd6565', '702b84ee-1696-4524-92d8-ff8a500b3beb', 5, '대화문', '화용/의사소통', true, '2', 'Why don''t you~?는 상대방에게 무엇인가를 제안할 때 쓰는 표현이므로 ②가 적절하다.', 1),
('a8f8a27d-efbd-4460-8901-be3e1224a118', '702b84ee-1696-4524-92d8-ff8a500b3beb', 6, '대화문', '화용/의사소통', true, '1, 2', '상대방이 계획을 물어보고 있으므로 ''너는 어때?''라는 의미의 ①이나 계획을 묻는 말인 ②가 적절하다.', 1),
('bb092444-ba4e-4c2a-8884-0c7ac4b39581', '702b84ee-1696-4524-92d8-ff8a500b3beb', 7, '영작', '쓰기', false, 'Show me some pictures later.', '수여동사 show는 ''수여동사 + 간접목적어 + 직접목적어''의 4형식으로 나타낼 수 있으며 명령문이므로 동사원형이 문장 맨 앞에 온다.', 1),
('86021ef9-306e-4c7e-8085-843cdcce43bd', '702b84ee-1696-4524-92d8-ff8a500b3beb', 8, '내용일치', '독해/사실확인', true, '2', 'Emma는 서핑을 못한다며 이번이 처음이라고 말했다. ① 누가 Emma를 가르칠 것인가? → 엄마 ② Emma의 지난 번 서핑은 어땠는가? → 언급되지 않음 ③ 지후는 Emma의 계획에 대해 어떻게 생각하는가? → 멋지다고', 1),
('d0d808b2-eb4f-469b-a863-323ee2852d8e', '702b84ee-1696-4524-92d8-ff8a500b3beb', 9, '어법', '문법/어휘', true, '2, 4, 5', 'Jamie는 나에게 아름다운 목걸이를 주었다. (for me to me) ②그녀는 아들에게 새 배낭을 사 주었다. ③ 엄마는 우리에게 아침으로, 팬케이크를 만들어 주셨다. (to us for us) ④ 나는 내 가장 친한 친구에게 모든 것을 말했다. ⑤ 그는 나에게 가장 빠른 길을 알려 주었다.', 1),
('4c8897fc-abd2-4794-82d8-0ecb63eaeac9', '702b84ee-1696-4524-92d8-ff8a500b3beb', 10, '어법', '문법/어휘', false, 'must careful → must be careful', '조동사 must 다음에 형용사가 있으므로 뒤에 be동사의 원형 be를 써야 한다. 스쿨존에는 아이들이 많기 때문에 우리는 조심해야 한다.', 1),
('f4d22cc0-bd0b-4d4b-97fe-8d3c4bea6cc4', '702b84ee-1696-4524-92d8-ff8a500b3beb', 11, '어법', '문법/어휘', true, '3', '수여동사 find, make가 쓰인 문장은 3형식으로 바꿔 쓸 때 전치사 「or를 쓴다. • 나는 내 남동생에게 흥미로운 책을 찾아 주었다. • 나는 우리 엄마에게 차 한 잔을 만들어 드렸다.', 1),
('2d4c36b7-f90a-4df3-98af-a4c57401bccb', '702b84ee-1696-4524-92d8-ff8a500b3beb', 12, '영작', '쓰기', true, '1', '두 문장을 순서대로 배열하면 We have to follow traffic rules.와 You must not touch the hot stove. 이므로, 빈칸에서 두 번째로. 오는 단어는 각각 to와 not이다.', 1),
('8b929fb7-b2e5-446e-aab1-b0fc613bf958', '702b84ee-1696-4524-92d8-ff8a500b3beb', 13, '어법', '문법/어휘', false, 'a blanket to his sister', '수여동사 bring이 쓰인 문장은 3형식으로 바꿔 쓸 때 전치사 to를 쓴다.', 1),
('8d740bc5-30ea-488c-80f8-5eb33fd3b486', '702b84ee-1696-4524-92d8-ff8a500b3beb', 14, '어휘', '문법/어휘', true, '2', '② 바로 뒤에서 자신도 챌린지를 해보았다고 했으므로 흐름상 didn''t like, didn''t try가 아니라 liked, tried가 되어야 자연스럽다.', 1),
('5ad093da-efa2-49a4-bec2-5ec631ee30d1', '702b84ee-1696-4524-92d8-ff8a500b3beb', 15, '어법', '문법/어휘', true, '5', '주어 my one-week plan과 Today가 단수이므로. be동사 is가 알맞다.', 1),
('16de60a7-e23a-4aa7-ba02-e83f5f6afae8', '702b84ee-1696-4524-92d8-ff8a500b3beb', 16, '영작', '쓰기', false, 'I should not[shouldn''t] be so wasteful.', '조동사 should의 부정문은 「should not + 동사원형」 형태로 나타내며 형용사 앞에 be동사의 원형인 be를 쓴다.', 1),
('6d7506de-a452-4b72-a997-07940cf699b6', '702b84ee-1696-4524-92d8-ff8a500b3beb', 17, '내용추론', '독해/사실확인', true, '2', '지우의 조언을 듣고 글쓴이가 자신의 쓰레기를 살펴본 것은 자신의 습관을 이해하려 한 행동으로, 볼 수 있다.', 1),
('2cc20b8e-38ac-45e7-a021-08ed0c16e734', '702b84ee-1696-4524-92d8-ff8a500b3beb', 18, '어법', '문법/어휘', true, '1', '① It은 날씨를 나타내는 비인칭 주어이므로 어법상 맞다. ② Dad bought me lemonade. (4형식) 또는 Dad bought lemonade for me. (3형식)로 쓴다. ③ 조동사 should 뒤에는 동사원형이 오므로 say로 쓴다. ④ 과거의 일이므로 과거형인 used로 쓴다. ⑤ money는 셀 수 없는 명사이므로, 단수인 that으로. 쓴다.', 1),
('9b3315b0-fd04-4c5d-94ae-b7b5bcdfb174', '702b84ee-1696-4524-92d8-ff8a500b3beb', 19, '어휘', '문법/어휘', true, '3', '오랫동안 인지 않은 티셔츠들을 중고품을 사고파는 앱에 올렸다는 내용이 이어지므로 문맥상 ‘너무 많은 티셔츠들을 찾아 냈다(found too many T-shirts)''라는 말이 와야 자연스럽다.', 1),
('6a5f94de-faff-491d-aba9-68f01fcf9abc', '702b84ee-1696-4524-92d8-ff8a500b3beb', 20, '영작', '쓰기', false, 'We listed my T-shirts on the app.', '주어 다음에 과거의 일을 나타내는 과거형 listed가 오고 목적어 my T-shirts를 쓴 다음 부사구 on the app을 쓴다.', 1),
('b8b95319-a24b-4f94-a756-064a8b0b1fa7', '702b84ee-1696-4524-92d8-ff8a500b3beb', 21, '내용일치', '독해/사실확인', true, '5', '티셔츠를 팔아 얼마를 빌었는지는 구체적으로 언급되지 않았다. ① 그 레모네이드는 무엇과 함께 나왔는가? → 빨대 ② 아빠는 더운 날에 무엇을 샀는가? → 레모네이드 ③ 글쓴이는 오늘 무엇을 청소했는가? → 글쓴이의 방 ④ 글쓴이가 앱을 사용하는 것을 누가 도왔는가? → 엄마 ⑤ 글쓴이는 티셔츠를 팔아서 얼마를 벌었는가? 언급되지 않음', 1),
('c0b535c2-ef65-4b99-af19-e8a732116a3f', '702b84ee-1696-4524-92d8-ff8a500b3beb', 22, '문장삽입', '글의흐름', true, '3', 'It은 앞서 언급한 shampoo를 가리키므로 샴푸도 병을 채웠다는 내용 뒤에 오는 것이 알맞다.', 1),
('012dc369-7f30-41d2-8aed-127533e431f2', '702b84ee-1696-4524-92d8-ff8a500b3beb', 23, '어휘', '문법/어휘', true, '1', 'run out of: ~을 다 써 버리다 글쓴이는 아침에 샴푸가 하나도 없어서 더 필요했다.', 1),
('5047b064-75df-414a-a348-473590cc7eb0', '702b84ee-1696-4524-92d8-ff8a500b3beb', 24, '제목요지', '주제파악', true, '2', '글쓴이는 빈 샴푸 병을 재사용했으며 이런 방식으로, 플라스틱을 줄이려는 자신의 노력을 소셜 미디어에 올렸다.', 1),
('6100bd03-19a8-4b25-bd7c-6e6b0631f8c9', '702b84ee-1696-4524-92d8-ff8a500b3beb', 25, '영작', '쓰기', false, 'Some of my friends even tried the challenge.', '주어 Some of my friends 뒤에 동사 tried를 수식하는 부사 even 을 쓰고 동사 다음에 목적어 the challenge를 쓴다.', 1),
('592aef33-6789-42d3-b2fb-7fa818c30227', '01997015-fd39-48cd-8f24-ba655c57bc41', 1, '어휘', '문법/어휘', true, '2', 'stay away from - keep away from(~에 가까이 가지 않다, ~에 서 멀리 떨어져 있다)', 1),
('0d403a95-6b74-4f93-9491-33be5f445e3c', '01997015-fd39-48cd-8f24-ba655c57bc41', 2, '어법', '문법/어휘', true, '2', 'try는 「to + 동사원형과 함께 쓰여 ''~하려고 노력하다''의 의미를 나타낸다.', 1),
('b973d83c-b36d-4552-8255-9b753e723ee2', '01997015-fd39-48cd-8f24-ba655c57bc41', 3, '어휘', '문법/어휘', false, '(i)ncorrect', '잘못된, 틀린''의 의미를 가진 단어 중에서 i로 시작하는 incorrect 를 쓴다.', 1),
('a52f575e-3ecc-4e2c-8052-cad3b9ca6a01', '01997015-fd39-48cd-8f24-ba655c57bc41', 4, '대화문', '화용/의사소통', true, '4', '상대방의 의견을 묻고 있으므로 자신의 의견이나 생각을 제안하는 표현인가 적절하다.', 1),
('5b02a2b2-95c0-41cf-9866-597c23d8b44f', '01997015-fd39-48cd-8f24-ba655c57bc41', 5, '대화문', '화용/의사소통', true, '2, 4', '① ''~할 예정이다''라는 의미로 계획을 말할 때 쓰는 표현이다. ③ ''시원하게 하다''라는 의미로 쓰였다. ⑤ 제안하는 표현이므로. Why don''t you join me?가 적절하다.', 1),
('d0b1355a-d9ad-461f-b1c6-1082acc49899', '01997015-fd39-48cd-8f24-ba655c57bc41', 6, '어휘', '문법/어휘', false, '3, good', 'Emma가 질문에 부정문으로 답하며 이번이 서핑이 처음이라고 했으므로. Are you good at surfing?으로 쓴다. poor: (용) 서투른', 1),
('5545774d-90d7-42ec-8c25-baf201c06abb', '01997015-fd39-48cd-8f24-ba655c57bc41', 7, '대화문', '화용/의사소통', true, '4', '상대방이 자신의 계획을 말하고 있으므로 계획(plans)을 묻는 표현이 적절하다. ⑤ 문맥상 사진을 자신에게 보여 달라(Show)는 뜻이 되어야 자연스럽다.', 1),
('506cafcb-8219-43db-84a3-7bab37812242', '01997015-fd39-48cd-8f24-ba655c57bc41', 8, '내용일치', '독해/사실확인', true, '4', '지호의 남동생은 자전거를 탈 수 있다. ⑥ 지호는 이번 주말에 특별한 일이 없다. → 남동생과 자전거를 탈 계획이다. ⓒ Emma의 가족은 이번 주말에 서핑을 하러 갈 예정이다. @Emma의 엄마는 서핑을 잘하신다.', 1),
('07eaf424-246c-499b-bff5-c3506dccfceb', '01997015-fd39-48cd-8f24-ba655c57bc41', 9, '어법', '문법/어휘', true, '1', '수여동사 ask가 쓰인 4형식 문장은 3형식으로 바꿀 때 간접목적어 앞에 전치사 이름 쓰고, 수여동사 pass, show, send, lend는 전치사 to를 쓴다.', 1),
('158cf43c-1b88-4d7a-85c9-f7cbe46b1b1c', '01997015-fd39-48cd-8f24-ba655c57bc41', 10, '영작', '쓰기', false, 'Children should not put toys on the floor.', '조동사 should의 부정문은 「should not[shouldn''t] + 동사원형」 형태로 나타낸다.', 1),
('27a955af-ed73-462d-afe0-3201f716ba96', '01997015-fd39-48cd-8f24-ba655c57bc41', 11, '어법', '문법/어휘', true, '5', '수여동사 get이 쓰인 4형식 문장을 3형식으로 바꿔 쓸 때는 전치사 for를 쓴다. ① 누가 너에게 이 케이크를 만들어 주었니? ②그는 우리에게 우유를 사 주었다. ③그들은 Sarah에게 초콜릿 한 상자를 가져다 주었다. ④ 나는 엄마에게 재미있는 이야기를 해 드렸다.', 1),
('e9fda895-1d7d-432d-92a7-43cfa730460d', '01997015-fd39-48cd-8f24-ba655c57bc41', 12, '어법', '문법/어휘', true, '3', '조동사 should 다음에 형용사가 이어지므로 뒤에 be동사의 원형 be를 써야 한다.', 1),
('0049186c-b27c-4878-8bf2-bb4fa3582e6c', '01997015-fd39-48cd-8f24-ba655c57bc41', 13, '영작', '쓰기', false, 'sent Michael an email', '4형식 문장은 「주어 + 수여동사 + 간접목적어 + 직접목적어의 어순으로 쓴다.', 1),
('a695352c-848e-4cd0-9db9-23c515274fed', '01997015-fd39-48cd-8f24-ba655c57bc41', 14, '영작', '쓰기', false, 'The challenge was making no trash.', '주어는 The challenge도, 동사는 과거 시제이므로 was로 쓴다. was의 보어 자리에 ''쓰레기를 만들지 않는 것''이라는 의미로, 동명사구 making no trash를 쓴다.', 1),
('fbacbd42-1749-44ce-9c19-587361e5194f', '01997015-fd39-48cd-8f24-ba655c57bc41', 15, '어법', '문법/어휘', true, '4', '「Here + be동사 + 주어~」 형태로 단수 동사 is 뒤에는 단수 주어 plan이 적절하다. ⑥ 수여동사 give의 4형식 문장은 「주어 + 수여동사 + 간접목적어 + 직접목적어」의 어순으로 쓴다. ⓒ paper와 plastic은 셀 수 없는 명사이므로 much가 적절하다.', 1),
('7e6de2e9-1c2d-416c-be65-6d2d97a1a1f9', '01997015-fd39-48cd-8f24-ba655c57bc41', 16, '어법', '문법/어휘', false, 'It', '주어 자리의 Today는 시간, 날짜, 요일 등을 나타내는 비인칭주어 It으로 바꿔 쓸 수 있다.', 1),
('d7cdfda0-ef1a-4990-8112-b7b6cc0eb83b', '01997015-fd39-48cd-8f24-ba655c57bc41', 17, '내용일치', '독해/사실확인', true, '3, 5', '글쓴이는 지우의 소셜 미디어에서 #제로웨이스트챌린지를 보았고 일주일 간 쓰레기 없는 생활을 위한 계획을 실천하기로 했다.', 1),
('7c41aee2-d8ce-48bb-82ef-ba90a2e5f128', '01997015-fd39-48cd-8f24-ba655c57bc41', 18, '영작', '쓰기', false, 'bought lemonade for me', '수여동사 buy는 「주어 + 수여동사 + 간접목적어 + 직접목적어」의 4형식 또는 「주어 + 수여동사 + 직접목적어 + for + 간접목적어, 의 3형식으로 쓸 수 있다.', 1),
('2d514f94-27a0-405e-a667-6b978b0bf06d', '01997015-fd39-48cd-8f24-ba655c57bc41', 19, '어휘', '문법/어휘', true, '4', '문맥상 (B)와 ④에는 should가 들어가는 반면, 나머지는 모두 should not [shouldn''t]이 들어간다.', 1),
('34b4eaf9-6d4f-409c-ad05-f554626402cd', '01997015-fd39-48cd-8f24-ba655c57bc41', 20, '내용일치', '독해/사실확인', true, '4', '앞 문장에서 엄마의 도움으로, 중고품을 사고파는 앱을 사용했다고 했으므로. ④는 event board(행사 게시판)가 아닌 app이 적절하다.', 1),
('9aa2c8d3-0dee-4d4a-95d9-cf8729b6e245', '01997015-fd39-48cd-8f24-ba655c57bc41', 21, '내용일치', '독해/사실확인', true, '4', '티셔츠 한 장의 가격에 대해서는 구체적으로 언급되지 않았다.', 1),
('4d35f1f6-0737-4343-b476-fd7860e480b9', '01997015-fd39-48cd-8f24-ba655c57bc41', 22, '어휘', '문법/어휘', true, '4', 'even은 ''심지어''라는 의미로 쓰였다.', 1),
('b8e72626-5b56-4105-b74a-2d4855ec0963', '01997015-fd39-48cd-8f24-ba655c57bc41', 23, '어휘', '문법/어휘', true, '4', '(A) run out of: ~을 다 써 버리다 (B) cut down on: ~을 줄이다', 1),
('5af12040-5616-4414-bbdf-d33eace2c685', '01997015-fd39-48cd-8f24-ba655c57bc41', 24, '내용일치', '독해/사실확인', true, '1', '빈 샴푸 병을 다시 채워서 쓰는 방식으로 플라스틱을 줄임으로써 환경 보호를 도왔다. 지문에 따르면, 글쓴이는 환경을 어떻게 도왔는가? ① 빈 샴푸 병을 다시 채움으로써. ② 자신의 인생 이야기를 공유함으로써. ③ 함께 쓰레기를 주움으로써. ④ 우정을 쌓음으로써. ⑤ 소셜 미디어에서 유명해짐으로써.', 1),
('a758fcd3-1026-4a99-b0e5-e8668f7ed91a', '01997015-fd39-48cd-8f24-ba655c57bc41', 25, '어휘', '문법/어휘', false, '(1) post (2) refilled (3) new (4) tried', 'A: 너는 왜 너의 샴푸 병 사진을 올렸니? B: 나는 제로웨이스트 상점에 가서 새것을 사는 대신 그것을 다시 채웠어. A: 오, 그거 현명하네! B: 응, 그리고 내 친구들도 그 아이디어를 좋아해서 그것을 해 봤어!', 4),
('41bdff05-34b0-4fe7-bb72-9e9c11fb9a49', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 1, '어법', '문법/어휘', true, '4', 'advise는 동사이며 전치사 for 다음에 쓸 수 있는 명사 advice로 고쳐야 한다. 우리 이것에 대해 나중에 얘기해도 될까? ⑤ 그녀는 쓰레기통 안에 쓰레기를 버렸다. ⓒ 나는 조언을 들으러 종종 선생님께 간다. 축구 선수들은 내일 아침 운동을 한다.', 1),
('5474ccf0-cda1-4ed1-b6fa-3f86442d13d4', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 2, '어휘', '문법/어휘', true, '1', 'plant: 통 심다 식물 ◆ 나는 내일 물 한 병을 가지고 다닌다. → carry 그녀는 책에서 중요한 정보를 찾았다. → information ⓒ 학교까지 걸어서 가는 것은 환경에 좋다. → environment 나는 다음 주에 자원봉사단에 합류할 것이다. → join', 1),
('ae42712c-8621-423d-b4e7-354bca49ae1c', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 3, '어휘', '문법/어휘', false, 'recycle', '다른 방식으로 다시 사용하다 - recycle(재활용하다) 너는 슈퍼마켓에서 유리병을 재활용할 수 있다.', 1),
('b52b175f-5ebe-44d6-82b2-c6b05be8df01', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 4, '대화문', '화용/의사소통', true, '4', '① 플로깅이 무엇인지 설명하는 답이 이어지므로 ⑥ What is that?이 적절하다. ② ''좋아, 그러고 싶어.''라고 제안을 수락하고 있으므로 함께할 것을 제안하는 Why don''t you join me?가 적절하다. ③ ''10시에 Green Park에서 만나자.''라고 답하고 있으므로. What time and where should we meet?이 적절하다.', 1),
('eaa667fe-a77b-4f04-ad41-e7210482afcb', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 5, '어법', '문법/어휘', false, 'It''s jogging and picking up trash.', '접속사 and.로. 연결되는 동사 jog와 pick은 동명사로 쓴다.', 1),
('195832c9-5d8d-47bb-b899-d0b7373eea69', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 6, '대화문', '화용/의사소통', true, '3', '빈칸 다음 대답이 ''쓰레기 봉투와 물만 있으면 돼.''라고 했으므로 질문으로 적절한 것은 ③이다.', 1),
('69c45791-6a42-4ca2-b9a8-2e32e73ee76a', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 7, '내용일치', '독해/사실확인', true, '5', '조깅을 하며 쓰레기를 줍는 플로깅을 같이 하기로 한 것으로 보아 둘 다 환경을 보호하는 네 관심이 있음을 알 수 있다. ① Dylan은 유나에게 오늘 계획이 무엇인지 묻는다. (→ 내일 계획) ② Dylan은 유나와 함께 조깅하고 싶어 한다. (→ 플모깅) ③ 유나는 혼자 플모깅을 하러 갈 것이다. (→ Dylan과 함께) ④ Dylan은 오후에 유나름 만날 것이다. (→ 오전) ⑤ 두 사람 모두 환경 보호에 관심이 있다.', 1),
('91108d21-9b67-40c9-9cb7-9c3255cbabce', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 8, '내용일치', '독해/사실확인', false, 'discount, own bottle', 'Sun Cale에서 소년은 자신의 개인 병을 사용함으로써 딸기 주스를 500원 할인받는다.', 1),
('d0b722a7-b93e-4b2d-b05e-8f7d5217d20e', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 9, '어법', '문법/어휘', true, '3', '의문사 의문문은 의문사를 문장 맨 앞에 쓰며, 조동사 should의 의문문은 should름, have to의 의문문은 do동사를 주어 앞에 쓴다. • 우리는 지금 날씨를 확인해야 할까? (checks → check) • 우리는 어떻게 환경을 보호해야 할까? • 그는 오늘 체육관에 갈 필요가 없다. • 그녀는 언제 보고서를 끝내야 하나요? (When she has to ~ → When does she have to ~)', 1),
('8c642d11-515f-4fb9-99ef-91a1393dc7ea', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 10, '어법', '문법/어휘', false, 'They cooked spaghetti for their guests. / They cooked their guests spaghetti.', '수여동사 cook은 「주어 + 수여동사 + 간접목적어 + 직접목적어, 의 4형식 또는 「주어 + 수여동사 + 직접목적어 + for + 간접목적어의 3형식으로 쓸 수 있다.', 1),
('05e2e1a7-2782-474b-bc2b-4b7eecb9e01c', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 11, '어법', '문법/어휘', false, 'Children shouldn''t watch too much TV.', 'watch는 동사이므로. be를 삭제하고 쓴다.', 1),
('68706b72-06fc-4a73-9b72-61a16c00924a', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 12, '어법', '문법/어휘', true, '3', '수여동사 bring, give, teach는 3형식 문장으로, 바꿀 때 전치사 to를 쓴다. • 그들은 아이들에게 장난감을 가져다 주었다.', 1),
('7787bc8f-9d77-4acf-bf64-12c5755b3507', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 13, '어법', '문법/어휘', false, '(1) ⓑ, has → had (2) ⓒ, does → do', '과거의 일을 나타내므로, has를 과거형인 had로 고쳐야 한다. ⓒ조동사 should 뒤에는 동사원형이 와야 하므로 does를 do로 고쳐야 한다. 너는 하루에 두 번 그 약을 먹어야 한다. David는 어제 시험을 준비해야 했다. ⓒ 그는 저녁 식사 후 설거지를 해야 한다.', 2),
('1f272fab-96da-4044-9a35-139c5bf61de1', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 14, '어법', '문법/어휘', true, '4', '① 과거의 일이므로, see를 과거형 saw.로. 고쳐야 한다. ② my one-week plan이 단수이므로 단수 동사 is를 써야 한다. Jiwoo gave me some advice, 또는 Jiwoo gave some advice to me..루. 쓴다. ⑤ 과거에 진행 중인 일을 나타내므로 am을 was로 고쳐야 한다.', 1),
('2aa181e1-a1b2-456a-94ae-dff9e7f5c981', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 15, '어휘', '문법/어휘', true, '2', '어떤 사람이 무엇을 해야 하는지에 대한 생각 → advice(조언, 충고) SNS나 인터넷에서 시도해 보는 재미있거나 어려운 것 - challenge((SNS에서의) 챌린지, 도전) 공기, 물, 땅과 같은 우리 주변의 세계 → environment(환경) 건물에서 위아래로 이동하는 네 도움을 주는 계단 → stairs(계단) 버려야 할 것들 → garbage, trash, waste(쓰레기)', 1),
('2484ccb4-5b43-4e62-b951-dff8440134fe', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 16, '영작', '쓰기', true, '5', '영어로 옮기면 I should not[shouldn''t] be so wasteful. 이므로. 필요하지 않은 단어는 ⑤ waste이다.', 1),
('6a655a1c-4d0b-4a4e-a35e-03e53dfb2d38', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 17, '내용일치', '독해/사실확인', false, 'ⓐ, ⓑ', '글쓴이는 자신의 쓰레기에 대해 무엇을 알아냈는가? ⑥ 글쓴이는 얼마나 많은 종이와 플라스틱을 버렸는가?', 1),
('2e6e1008-6bf1-4710-a1a9-97f65a63d45d', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 18, '어법', '문법/어휘', false, 'A: say no to B: buy (for) C: for (~동안)', 'say no to: ~을 거절[거부]하다 (B) 수여동사 buy는 3형식 문장으로 바꿀 때 전치사 for를 쓴다. (C) ''~동안''이라는 의미로 일정한 기간을 나타낼 때는 전치사 for를 쓴다.', 1),
('90e0d012-ec15-4b76-99db-730164d9e134', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 19, '어휘', '문법/어휘', false, '(1) came (2) say (3) used (4) bought', 'ⓐ에는 came, ⓑ에는 say, ⓒ에는 used, ⓓ에는 bought가 들어 간다.', 4),
('f1592bba-5699-4f38-b0fd-3aa3ff9ba2e4', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 20, '어법', '문법/어휘', false, 'D: to one''s surprise E: sell (to)', '(D) to one''s surprise: 놀랍게도 (E) 수여동사 sell은 3형식 문장으로 바꿀 때 전치사 to를 쓴다.', 1),
('43400bb1-c9a3-4f2b-990e-2c534003d1b7', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 21, '내용일치', '독해/사실확인', false, 'ⓒ, ⓓ', '글쓴이의 엄마가 그녀가 앱을 사용하는 것을 도왔다. ⑥ 어떤 이가 글쓴이의 티셔츠 중 하나를 사는 데 관심을 보였다. ⓒ 그 레모네이드는 집에서 만든 것이었다. → 사 먹었다. 글쓴이는 더운 날에 레모네이드를 샀다. 아빠가 사주셨다.', 1),
('1c65e8ef-ce42-475c-b660-e9681d4dce44', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 22, '내용추론', '독해/사실확인', false, '새 샴푸를 사지 않고 빈 샴푸 통을 다시 채워 씀으로써 플라스틱을 줄인다는 의미', '새 샴푸를 사지 않고 빈 샴푸 통을 다시 채워 씀으로써 플라스틱을 줄인다는 의미가 되어야 자연스럽다.', 1),
('448b852a-ebaa-4aec-97df-79dfa8845b2e', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 23, '어휘', '문법/어휘', false, '1 protect 2 fill 3 list 4 post 5 waste', '위험으로부터 무언가나 누군가를 안전하게 지키다 → protect(보호하다) 어떤 것을 용기에 가득 채울 때까지 넣다 → fill(채우다) 판매를 위해 목록에 물건을 올리다 → list(판매 목록에 올리다) 소셜 미디어 또는 온라인에 정보를 공유하다 → post(게시하다) 잘못 또는 부주의하게 무언가를 사용하다 → waste(낭비하다)', 1),
('c209fe8c-acb6-4cdd-bba3-85bd2abf76cc', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 24, '내용일치', '독해/사실확인', true, '3, 4', '③ 제로웨이스트 상점이 있는 곳과 ④ 챌린지에 참여한 친구들의 수는 언급되지 않았다. ① 글쓴이의 샴푸가 떨어진 때는? ② 글쓴이는 상점에 무엇을 가져갔는가? ③ 제로웨이스트 상점은 어디에 있는가? ④ 얼마나 많은 친구들이 챌린지에 동참했는가? ⑤ 왜 챌린지가 좋았는가?', 1),
('bc304d27-d7c9-4d8c-ac86-8a03e427ecc8', 'a364c2bc-ba40-40b3-bd7a-e3660a891c27', 25, '대화문', '화용/의사소통', false, 'A: 너는 너의 제로웨이스드 상점의 경험을 공유했니? B: 응, 나는 내 사진을 소셜 미디어에 올렸어. A: 잘했네! 사람들이 좋아했니? B: 응! 나는 많은 "좋아요"를 받았고, 몇몇 친구들은 심지어 그 챌린지를 시도했어.', 'A: 너는 너의 제로웨이스드 상점의 경험을 공유했니? B: 응, 나는 내 사진을 소셜 미디어에 올렸어. A: 잘했네! 사람들이 좋아했니? B: 응! 나는 많은 "좋아요"를 받았고, 몇몇 친구들은 심지어 그 챌린지를 시도했어.', 1),
('8cad5751-0b17-4a3e-befc-f68ec6666db2', '3ae326f3-73f6-406f-a179-dfe87d06e343', 1, '어법', '문법/어휘', true, '4', '①, ②, ③, ⑤는 동명사로 쓰였고, ④는 현재진행형으로 쓰였다. ① Daniel은 한가한 시간에 무엇을 하는 것을 즐기니? ② 만화책을 읽는 것은 내가 가장 좋아하는 취미다. ③ Emma는 노래를 잘 부르니? ④ 그들은 공원에서 무엇을 하고 있니? ⑤ 나는 우리 가족과 여행하는 것을 좋아해.', 1),
('10274c6c-e7df-4ee0-8454-64a9c76adce0', '3ae326f3-73f6-406f-a179-dfe87d06e343', 2, '어휘', '문법/어휘', true, '5', '그녀의 생각이 마음에 들었다고 했으므로, ''그 챌린지를 해 보았다 (tried).''라는 의미가 적절하다. ① 낭비했다 ② 청소했다 ③ 채웠다 ④ 절약했다', 1),
('124b622c-a5d0-4667-b187-5e9980708e89', '3ae326f3-73f6-406f-a179-dfe87d06e343', 3, '영작', '쓰기', true, '2', '주어진 우리말을 영어로 옮기면 Here is my one-week plan for a trash-free life.이므로 네 번째로 오는 단어는 one-week이다.', 1),
('7e49d83c-5555-4a9a-b653-4f6d6f9bf8d5', '3ae326f3-73f6-406f-a179-dfe87d06e343', 4, '내용일치', '독해/사실확인', true, '4', '지우의 소셜 미디어 계정은 언급하지 않았다.', 1),
('9ed89586-ebc6-468e-bc4b-cffd26f60025', '3ae326f3-73f6-406f-a179-dfe87d06e343', 5, '어법', '문법/어휘', true, '2', '두 개의 목적어를 취하는 수여동사 give를 써서 Jiwoo gave me some advice, 또는 전치사를 사용해 Jiwoo gave some advice to me.로 쓸 수 있다.', 1),
('f94c6e08-419b-4ebd-87cc-b1ff8a6fdff1', '3ae326f3-73f6-406f-a179-dfe87d06e343', 6, '어법', '문법/어휘', true, '1', 'ⓐ는 자신의 쓰레기를 아는 것이 중요하므로, 쓰레기를 살펴보았다는 의미이고, ⓑ는 날씨가 더워 아빠가 레모네이드를 사 주셨다는 의미이므로 이유 및 결과를 뜻하는 접속사 so가 적절하다.', 1),
('1bed1fc2-9a29-4e90-99f7-75b64b5ea003', '3ae326f3-73f6-406f-a179-dfe87d06e343', 7, '어법', '문법/어휘', true, '2', '조동사 should의 부정문은 「should not[shouldn''t] + 동사원형」 형태로 나타내므로 not be로 고쳐 써야 한다.', 1),
('a1134103-f246-4565-8d0b-f84509a7191d', '3ae326f3-73f6-406f-a179-dfe87d06e343', 8, '지칭', '논리/추론', true, '4', 'ⓐ, ⓑ의 it은 시간, 거리, 날씨 등을 나타내는 비인칭 주어이며, ⓒ, ⓓ의 it은 ''그것''이라고 해석되는 인칭대명사이다. ⓐ 그것은 누구 책이니? ⓑ 오늘은 월요일이니? ⓒ 그것은 좋은 영화였어. ⓓ 그것을 만지지 마! ⓔ 벌써 정오야.', 1),
('f3850159-196b-4b9c-94b7-93e6e7e4f4b3', '3ae326f3-73f6-406f-a179-dfe87d06e343', 9, '내용일치', '독해/사실확인', true, '5', '빨대와 함께 나온 레모네이드를 보고 빨대를 거절했다고 했으므로 ⑤는 글의 내용과 일치하지 않는다.', 1),
('dbe04559-c5d3-4c94-b21c-a449efe88420', '3ae326f3-73f6-406f-a179-dfe87d06e343', 10, '제목요지', '주제파악', true, '5', '쓰레기 없는 생활을 위한 5번째 날의 계획으로 오랫동안 입지 않은 티셔츠들을 중고품을 사고파는 앱에 올려 누군가에게 판매했다는 내용의 글이므로, ⑤가 알맞다. ① 오래된 옷은 버려라. ② 돈을 낭비하지 마라. ③ 물건을 사고팔 때는 앱을 사용하라. ④ 중고 티셔츠를 입어라. ⑤ 중고품을 사고팔아라.', 1),
('ccf17fe2-3885-45ce-92f0-f57b55443c7b', '3ae326f3-73f6-406f-a179-dfe87d06e343', 11, '어법', '문법/어휘', true, '4', 'ⓐ T-shirts가 셀 수 있는 명사의 복수형이므로 many가 알맞다. ⓑ 너무 많은 티셔츠 중 일부를 의미하므로 some이 알맞다.', 1),
('5594267c-f2be-436d-9157-fbf41ba9ae90', '3ae326f3-73f6-406f-a179-dfe87d06e343', 12, '어휘', '문법/어휘', true, '4', '(A) 티셔츠를 ''앱에 올렸다''라는 뜻이 문맥상 적절하므로 listed(판매 목록에 올렸다)가 알맞다. (B) 자신이 입던 티셔츠를 누군가가 사고 싶어 한다는 사실에 놀랐다는 흐름이 적절하므로 surprise(놀라움)가 알맞다. (C) 옷을 판매한 돈으로, 중고 배드민턴 라켓을 샀다는 뜻이 문맥상 적절하므로, bought(샀다)가 알맞다.', 1),
('d54ae8bb-054f-4b6b-82f5-03737d14a9d0', '3ae326f3-73f6-406f-a179-dfe87d06e343', 13, '지칭', '논리/추론', true, '1', '판매 목록에 올린 티셔츠 중 하나를 원하는 사람이 있어 그에게 그것을 팔았다는 의미이므로 T-shirt를 가리킨다.', 1),
('fc951936-e866-459e-9c69-b6dc54016f15', '3ae326f3-73f6-406f-a179-dfe87d06e343', 14, '내용일치', '독해/사실확인', true, '5', '글쓴이는 중고 티셔츠를 판매한 돈으로 중고 배드민턴 라켓을 샀다. ① 아무도 글쓴이의 티셔츠를 사고 싶어 하지 않았다. ② 글쓴이의 엄마는 앱에서 그녀의 티셔츠를 팔려고 했다. ③ 앱은 중고 물품을 팔 수만 있는 곳이다. ④ 글쓴이는 자기 티셔츠를 누군가에게 공짜로 주었다.', 1),
('de30d9bd-eec4-4260-833c-00a261a9b375', '3ae326f3-73f6-406f-a179-dfe87d06e343', 15, '내용일치', '독해/사실확인', true, '4', '④', 1),
