('1cf47580-ac05-4c94-abb8-08d92ea1747e', '3ae326f3-73f6-406f-a179-dfe87d06e343', 17, '내용일치', '독해/사실확인', false, '(1) shampoo (2) This challenge', 'ⓐ shampoo ⓑ This challenge', 2),
